_previous_send_prepared_control_consolidated = send_prepared_control_post_to_main


def send_prepared_control_post_to_main(token: str) -> str:
    """Prepare the report again and send the report body—not the ספק/reason envelope."""
    item = _restore_prepared_send(token)
    if not item:
        return "הפוסט הישן לא ניתן לשחזור. בצע בדיקת כתב חדשה."
    post: Post = item["post"]
    edited = _get_manual_edit(token) if "_get_manual_edit" in globals() else ""
    if edited:
        message = _extract_body_only_from_control_wrapper(edited)
    else:
        translated = str(item.get("translated", "") or "")
        quoted_translated = str(item.get("quoted_translated", "") or "")
        quoted_author_translated = str(item.get("quoted_author_translated", "") or "")
        if not translated and not quoted_translated:
            translated, quoted_translated, quoted_author_translated = manual_force_translation(post)
        message = build_message(post, translated, quoted_translated, quoted_author_translated, include_video_link=False)
    state = load_state()
    reply_message_ids = find_bot_reply_target_for_post(post, state)
    images = selected_post_images(post)
    video_url = sendable_video_url(post) if SEND_VIDEO_FILES else ""
    message_ids, mode = manual_force_send_prepared_message(post, message, images, video_url, reply_message_ids)
    if message_ids:
        remember_bot_sent_reply_target(post, state, message_ids)
        remember_channel_news_text(_finalize_outgoing_message_only(message), state, message_id=post.link, source="manual_force")
        confirm_recent_news_event(post, state)
        seen = set(state.get(post.username, []))
        seen.update(post.dedupe_ids)
        state[post.username] = list(seen)[-500:]
        save_state(state)
    return f"גוף ההודעה נשלח לערוץ נטו ספורט. מצב שליחה: {mode}"


# ----- General, failure-tolerant 10-latest aggregation -----
LAST_TEN_HISTORY_DIAGNOSTICS: dict[str, dict[str, Any]] = {}


def _post_from_sent_memory_item(username: str, item: Any) -> Post | None:
    if not isinstance(item, dict):
        return None
    source = str(item.get("username") or item.get("source") or "")
    if _ten_history_account_key(source) != _ten_history_account_key(username):
        return None
    text = str(item.get("original_text") or item.get("text") or item.get("preview") or "").strip()
    link = str(item.get("link") or "")
    post_id = str(item.get("post_id") or link or "")
    if not (text or link or post_id):
        return None
    return Post(
        post_id=post_id,
        username=username,
        text=text,
        link=link,
        image_urls=list(item.get("image_urls") or []),
        video_urls=list(item.get("video_urls") or []),
        has_video=bool(item.get("has_video") or item.get("video_urls")),
        primary_has_video=bool(item.get("has_video") or item.get("video_urls")),
        quoted_has_video=False,
        quoted_author="",
        quoted_text=str(item.get("quoted_text") or ""),
        published_ts=float(item.get("published_ts") or item.get("ts") or 0.0),
        dedupe_ids=[value for value in (post_id, link) if value],
        source_name=str(item.get("source_name") or "history"),
    )


def fetch_last_ten_control_isolated(username: str, limit: int = 10) -> list[Post]:
    merged: dict[str, Post] = {}
    diagnostics: dict[str, Any] = {"sources": {}, "errors": []}

    def add_stage(stage: str, producer: Any) -> None:
        before = len(merged)
        try:
            values = producer() if callable(producer) else producer
            for post in values or []:
                if not isinstance(post, Post):
                    continue
                post.username = username
                identity = _ten_history_post_identity(username, post)
                if identity and identity not in merged:
                    merged[identity] = post
            diagnostics["sources"][stage] = len(merged) - before
        except Exception as exc:
            diagnostics["sources"][stage] = 0
            diagnostics["errors"].append(f"{stage}: {short_error(exc, 240)}")

    add_stage("memory_cache", lambda: _control_cached_posts(username))
    add_stage("saved_history", lambda: _ten_history_load(username))
    add_stage("normal_fetch", lambda: fetch_posts(username))
    add_stage("control_fetch", lambda: fetch_control_posts_reliable(username, limit=max(limit, 10)))
    add_stage("safe_fallback", lambda: fetch_posts_safely(username)[1])
    add_stage("known_control_state", lambda: _ten_history_collect_existing_state_posts(username))

    def sent_memory_posts() -> list[Post]:
        result: list[Post] = []
        for item in load_json_list_file(persistent_memory_path("football_sent_memory.json"))[-700:]:
            post = _post_from_sent_memory_item(username, item)
            if post is not None:
                result.append(post)
        return result

    add_stage("sent_memory", sent_memory_posts)
    ordered = sorted(merged.values(), key=lambda post: float(post.published_ts or 0.0), reverse=True)
    diagnostics["after_dedupe"] = len(ordered)
    diagnostics["returned"] = min(limit, len(ordered))
    LAST_TEN_HISTORY_DIAGNOSTICS[_ten_history_account_key(username)] = diagnostics
    if ordered:
        try:
            _remember_control_rss_posts(username, ordered)
        except Exception:
            pass
        try:
            _ten_history_save(username, ordered)
        except Exception as exc:
            diagnostics["errors"].append(f"save_history: {short_error(exc, 240)}")
    return ordered[:limit]


# ----- Forwarded/replied message source identification in the quiet/control chat -----
def _telegram_internal_chat_id(chat_id: Any) -> str:
    digits = re.sub(r"\D", "", str(chat_id or ""))
    return digits[3:] if digits.startswith("100") else digits


def identify_telegram_message_source(message: dict[str, Any]) -> dict[str, str]:
    origin = message.get("forward_origin") if isinstance(message.get("forward_origin"), dict) else {}
    origin_chat = origin.get("chat") if isinstance(origin.get("chat"), dict) else {}
    legacy_chat = message.get("forward_from_chat") if isinstance(message.get("forward_from_chat"), dict) else {}
    reply = message.get("reply_to_message") if isinstance(message.get("reply_to_message"), dict) else {}
    chat = origin_chat or legacy_chat or (reply.get("chat") if isinstance(reply.get("chat"), dict) else {}) or {}
    message_id = (
        origin.get("message_id") or message.get("forward_from_message_id") or
        reply.get("message_id") or message.get("message_id")
    )
    username = str(chat.get("username") or "").lstrip("@")
    chat_id = chat.get("id")
    source_name = str(
        origin.get("sender_user_name") or origin.get("author_signature") or message.get("author_signature") or
        chat.get("title") or username or "מקור לא מזוהה"
    )
    original_date = origin.get("date") or message.get("forward_date") or reply.get("date") or message.get("date")
    try:
        date_text = datetime.fromtimestamp(float(original_date), ZoneInfo(SHABBAT_TIMEZONE)).strftime("%d/%m/%Y %H:%M")
    except Exception:
        date_text = "לא ידוע"
    link = ""
    if username and message_id:
        link = f"https://t.me/{username}/{message_id}"
    elif chat_id and message_id:
        internal = _telegram_internal_chat_id(chat_id)
        if internal:
            link = f"https://t.me/c/{internal}/{message_id}"
    # Prefer an original X/site link embedded in the message body.
    body = str(message.get("text") or message.get("caption") or reply.get("text") or reply.get("caption") or "")
    external = re.search(r"https?://(?:x\.com|twitter\.com|[^\s<>]+)/(?:[^\s<>]*)", body)
    if external:
        link = external.group(0).rstrip(".,)")
    return {"source": source_name, "date": date_text, "link": link}


_previous_process_control_text_consolidated = process_control_text_update


def process_control_text_update(update: dict[str, Any]) -> None:
    message = update.get("message") or update.get("channel_post") or update.get("edited_channel_post") or {}
    if isinstance(message, dict):
        chat_id = str((message.get("chat") or {}).get("id", ""))
        is_control = bool(CONTROL_CHAT_ID and chat_id == CONTROL_CHAT_ID)
        has_origin = bool(message.get("forward_origin") or message.get("forward_from_chat") or message.get("forward_from_message_id"))
        has_reply = isinstance(message.get("reply_to_message"), dict)
        if is_control and (has_origin or has_reply):
            metadata = identify_telegram_message_source(message)
            lines = [f"מקור: {metadata['source']}", f"תאריך ושעה: {metadata['date']}"]
            if metadata.get("link"):
                lines.append(f"קישור: {metadata['link']}")
            send_control_text("\n".join(lines), message.get("message_id"), control_delete_message_reply_markup())
            return
    return _previous_process_control_text_consolidated(update)


