_FABRIZIO_CONFIRMATION_GENERIC_ENTITIES = {
    "agreement", "contract", "clause", "documents", "document", "exchanged", "sealing",
    "reached", "sell-on", "sign", "transfer", "move", "deal", "offer", "bid", "talks",
    "grmnt", "dcmnts", "xchngd", "slng", "קלאב", "קלאוסה", "גרמנט", "אגרימהנט",
    "דוקומהנטס", "דקמנטס", "קסצאנגהד", "קסצנגד", "סהלל-ונ", "סל-נ",
}


def _fabrizio_confirmation_match(post: Post, item: Any) -> bool:
    """Match a Fabrizio confirmation to Schira/Di Marzio/Moretto by event entities.

    The match is stricter than generic text similarity: it requires a transfer-family
    action, a shared club/team and a shared distinctive player/event token.
    """
    if not isinstance(item, dict):
        return False
    source = str(item.get("username") or item.get("source") or "").strip().lstrip("@").casefold()
    if source not in _FABRIZIO_CONFIRMATION_SOURCES or is_pending_memory_item(item):
        return False
    previous = item.get("signature", {})
    if not isinstance(previous, dict) or not previous:
        return False
    current = news_event_signature(post)
    current_actions = set(current.get("actions", []))
    previous_actions = set(previous.get("actions", []))
    if not _duplicate_family_overlap(current_actions, previous_actions):
        return False

    current_entities = set(current.get("entities", []))
    previous_entities = set(previous.get("entities", []))
    shared_teams = {token for token in current_entities & previous_entities if str(token).startswith("team:")}
    if not shared_teams:
        return False

    current_players, _current_teams = _canonical_sets_from_signature(current)
    previous_players, _previous_teams = _canonical_sets_from_signature(previous)
    if current_players & previous_players:
        return True

    shared_distinctive = {
        token for token in current_entities & previous_entities
        if not str(token).startswith("team:")
        and str(token).casefold() not in _FABRIZIO_CONFIRMATION_GENERIC_ENTITIES
        and len(re.sub(r"[^A-Za-zא-ת]", "", str(token))) >= 5
    }
    if shared_distinctive:
        return True

    current_tokens = set(current.get("tokens", []))
    previous_tokens = set(previous.get("tokens", []))
    shared_tokens = {
        token for token in current_tokens & previous_tokens
        if str(token).casefold() not in _FABRIZIO_CONFIRMATION_GENERIC_ENTITIES
        and len(re.sub(r"[^A-Za-zא-ת]", "", str(token))) >= 5
    }
    return len(shared_tokens) >= 2


_previous_send_post_retry_safety = send_post


def send_post(post: Post, reply_message_ids: dict[str, int] | None = None, state: dict[str, Any] | None = None) -> dict[str, Any]:
    """Keep translation/system-output failures pending for a later Gemini retry."""
    result = _previous_send_post_retry_safety(post, reply_message_ids=reply_message_ids, state=state)
    if not result.get("sent") and str(result.get("mode", "")) in {
        "translation_quality_blocked", "main_blocked_untranslated"
    }:
        result["mode"] = "translation_unavailable_retry"
    return result

