# ====== X-LAYOUT / ONE-KEY / STRICT FABRIZIO CONFIRMATION PATCH ======
# This final layer intentionally changes runtime behavior only. Persistent JSON
# filenames, state keys and stored formats remain exactly backward-compatible.

# One Gemini network request, one model and one key per post attempt. If that key
# fails it is cooled down and the post remains pending; a later scan may select a
# different available key. Sentence/paragraph translation is still performed in
# the same single request, never one request per sentence.
GEMINI_TRANSLATION_ATTEMPTS = 1
GEMINI_MAX_REAL_TRANSLATION_REQUESTS = 1
GEMINI_MAX_KEYS_PER_OPERATION = 1

_previous_gemini_translation_keys_one_request = gemini_translation_keys_for_operation
_previous_gemini_models_one_request = gemini_models_for_operation


def gemini_translation_keys_for_operation() -> list[tuple[int, str]]:
    return list(_previous_gemini_translation_keys_one_request() or [])[:1]


def gemini_models_for_operation() -> list[str]:
    return list(_previous_gemini_models_one_request() or [])[:1]


# Detect every clear generated equivalent, while avoiding ordinary phrases that
# merely contain the words "זה קורה" in an unrelated sentence.
_HERE_WE_GO_OUTPUT_RE = re.compile(
    r"\bhere\s*[,!:-]?\s*we\s*[,!:-]?\s*go\b|"
    r"\bhw[gq]\b|"
    r"היר\s*ווי\s*גו|"
    r"הנה\s*[,!:-]?\s*(?:זה\s+קורה|אנחנו\s+הולכים|זה\s+בא|זה\s+הולך)|"
    r"כאן\s+אנחנו\s+הולכים",
    re.IGNORECASE | re.UNICODE,
)


def _enforce_here_we_go_from_source(post: Post, translated: str) -> str:
    """HERE WE GO is controlled only by the untouched source caption."""
    source_has = bool(_HERE_WE_GO_SOURCE_RE.search(_post_original_text(post)))
    value = str(translated or "")
    if source_has:
        if _HERE_WE_GO_OUTPUT_RE.search(value):
            value = _HERE_WE_GO_OUTPUT_RE.sub("HERE WE GO", value)
            # Gemini can repeat it; source presence permits one copy only.
            first = value.find("HERE WE GO")
            head, tail = value[:first + len("HERE WE GO")], value[first + len("HERE WE GO"):]
            tail = re.sub(r"(?i)\bHERE\s+WE\s+GO\b", "", tail)
            return (head + tail).strip()
        blocks = value.split("\n\n", 1)
        blocks[0] = blocks[0].rstrip(" .,!;:") + ", HERE WE GO!"
        return "\n\n".join(blocks)

    value = _HERE_WE_GO_OUTPUT_RE.sub("", value)
    value = re.sub(r"\s+([,.;!?])", r"\1", value)
    value = re.sub(r"([,;])\s*([.!?])", r"\2", value)
    value = re.sub(r"\s{2,}", " ", value)
    value = re.sub(r"^[\s,;:!.-]+|[\s,;:-]+$", "", value)
    return value.strip()


def _source_logical_layout(source: str) -> tuple[list[str], list[str]]:
    """Return logical source segments and the real separators after each segment.

    Separators are either a single line break or a paragraph break. Only newlines
    actually present in the source text are used; Telegram/Desktop visual wrapping
    never enters the source string and therefore cannot create a new line here.
    """
    value = _attach_orphan_emoji_lines(str(source or "").replace("\r\n", "\n").replace("\r", "\n"))
    value = _DIRECTIONAL_ONLY_RE.sub("", value).strip()
    if not value:
        return [], []
    chunks = re.split(r"(\n+)", value)
    segments: list[str] = []
    separators: list[str] = []
    pending_separator = ""
    for chunk in chunks:
        if not chunk:
            continue
        if chunk.startswith("\n"):
            pending_separator = "\n\n" if len(chunk) >= 2 else "\n"
            continue
        clean = chunk.strip()
        if not clean:
            continue
        if segments:
            separators.append(pending_separator or "\n")
        segments.append(clean)
        pending_separator = ""
    return segments, separators


def _allocate_translation_to_source_segments(source_segments: list[str], translated: str) -> list[str]:
    """Conservative fallback when Gemini did not preserve all source separators."""
    target = len(source_segments)
    if target <= 1:
        return [re.sub(r"\s*\n+\s*", " ", translated).strip()]

    current = [part.strip() for part in re.split(r"\n+", translated) if part.strip()]
    if len(current) == target:
        return current

    units = _sentence_units(translated)
    if len(units) < target:
        # Do not fabricate sentence fragments unless the source itself has more
        # logical lines. Split the longest translated unit at a safe clause space.
        units = current or [translated.strip()]
        while len(units) < target:
            index = max(range(len(units)), key=lambda i: len(units[i]))
            candidate = units[index]
            split_points = [m.start() for m in re.finditer(r"\s+(?:[-–—;:]|אבל|אך|כאשר|בעוד|ו(?:הוא|היא|הם|המועדון))\s+", candidate)]
            if not split_points:
                words = candidate.split()
                if len(words) < 4:
                    break
                midpoint = len(words) // 2
                left, right = " ".join(words[:midpoint]), " ".join(words[midpoint:])
            else:
                point = min(split_points, key=lambda p: abs(p - len(candidate) / 2))
                left, right = candidate[:point].strip(), candidate[point:].strip()
            if not left or not right:
                break
            units[index:index + 1] = [left, right]

    if len(units) < target:
        return [translated.strip()]

    source_weights = [max(1, count_content_words(segment)) for segment in source_segments]
    total_weight = sum(source_weights)
    result: list[str] = []
    cursor = 0
    for idx, weight in enumerate(source_weights):
        remaining_segments = target - idx
        remaining_units = len(units) - cursor
        if remaining_segments == 1:
            take = remaining_units
        else:
            proportional = round(len(units) * weight / max(1, total_weight))
            take = max(1, min(proportional, remaining_units - (remaining_segments - 1)))
        result.append(" ".join(units[cursor:cursor + take]).strip())
        cursor += take
    return result


def _source_layout_is_artificial_sentence_rows(
    source_segments: list[str],
    source_separators: list[str],
) -> bool:
    """Detect RSS/translator sentence-per-line noise, not genuine X paragraphs.

    Some RSS mirrors turn an ordinary one-paragraph tweet into one physical row
    per sentence.  Those rows must not be reproduced in Telegram.  Genuine
    paragraphs (blank-line separators), lists, headings and quote blocks remain
    untouched.
    """
    if len(source_segments) < 3 or not source_separators:
        return False
    if any(separator == "\n\n" for separator in source_separators):
        return False
    if any(_LIST_LINE_RE.match(segment) for segment in source_segments):
        return False
    if any(segment.rstrip().endswith(":") for segment in source_segments[:-1]):
        return False

    # A run of ordinary prose sentences separated only by single newlines is the
    # exact shape produced by the problematic RSS/Google-Translate fallback.
    sentence_like = 0
    for segment in source_segments:
        plain = segment.strip().strip('"“”׳״')
        if not plain:
            continue
        if re.search(r"[.!?…][\"'”׳״)]?$", plain) or count_content_words(plain) >= 5:
            sentence_like += 1
    return sentence_like >= max(3, len(source_segments) - 1)


def _restore_source_layout(post: Post, translated: str, quoted: bool = False) -> str:
    """Restore X/Twitter paragraphs while removing artificial sentence rows.

    Real blank-line paragraphs and lists are preserved.  When an RSS mirror or
    Google Translate split a normal paragraph into one sentence per line, the
    final Telegram body is joined back into natural continuous prose.
    """
    source = _post_original_text(post, quoted=quoted)
    value = _strip_internal_translation_output(translated)
    value = _remove_channel_signature_artifacts(value)
    value = _attach_orphan_emoji_lines(value)
    source_segments, source_separators = _source_logical_layout(source)

    source_is_single_prose_block = (
        len(source_segments) == 1
        or _source_layout_is_artificial_sentence_rows(source_segments, source_separators)
    )

    if not source_segments:
        value = re.sub(r"\n{3,}", "\n\n", value).strip()
    elif source_is_single_prose_block:
        # One ordinary X paragraph must stay one paragraph, even if Google
        # translated each sentence separately or an RSS mirror inserted rows.
        value = re.sub(r"\s*\n+\s*", " ", value).strip()
    else:
        translated_segments = _allocate_translation_to_source_segments(source_segments, value)
        if len(translated_segments) == len(source_segments):
            rebuilt = translated_segments[0]
            for separator, segment in zip(source_separators, translated_segments[1:]):
                rebuilt += separator + segment
            value = rebuilt
        else:
            # Last-resort conservative layout: never create more blocks than the
            # source, and never leave one sentence per paragraph.
            blocks = [part.strip() for part in re.split(r"\n{2,}", value) if part.strip()]
            value = "\n\n".join(_merge_blocks_to_count(blocks, len(source_segments))) if blocks else value

    value = _compact_lists_and_spacing(value)
    value = re.sub(r"(?:\.\s*){2,}(?=📝)", ".", value)
    value = re.sub(r"([!?])\s*\.\s*(?=📝)", r"\1", value)
    value = re.sub(r"([.!?])\s+(?=📝)", r"\1", value)
    value = _TRAILING_ATTRIBUTION_RE.sub("", value).rstrip()
    return re.sub(r"\n{3,}", "\n\n", value).strip()


_CONFIRMATION_GENERIC_WORDS = {
    "agreement", "contract", "extension", "renewal", "deal", "transfer", "move", "sign", "signed",
    "signing", "join", "joined", "joins", "club", "player", "today", "tomorrow", "option", "year",
    "years", "june", "july", "official", "confirmed", "documents", "medical", "talks", "negotiations",
    "offer", "bid", "fee", "million", "report", "reported", "source", "sources", "exclusive", "new",
    "הסכם", "חוזה", "הארכה", "עסקה", "העברה", "מעבר", "חתם", "חתמה", "יחתום", "מצטרף", "הצטרף",
    "מועדון", "שחקן", "היום", "מחר", "אופציה", "שנה", "שנים", "יוני", "יולי", "רשמי", "אושר",
    "מסמכים", "בדיקות", "רפואיות", "שיחות", "מגעים", "הצעה", "סכום", "מיליון", "דיווח", "בלעדי",
}


def _confirmation_item_text(item: dict[str, Any]) -> str:
    signature = item.get("signature", {}) if isinstance(item, dict) else {}
    return str(
        item.get("ai_text") or item.get("original_text") or item.get("text") or
        (signature.get("text") if isinstance(signature, dict) else "") or ""
    )


def _confirmation_team_ids(text: str) -> set[str]:
    normalized = _duplicate_phrase_norm(text)
    found: set[str] = set()
    try:
        catalog = all_team_catalog_items()
    except Exception:
        catalog = TEAM_CATALOG
    for key, info in (catalog or {}).items():
        aliases = [key, str((info or {}).get("name", ""))] + list((info or {}).get("aliases", []) or [])
        for alias in aliases:
            alias_norm = _duplicate_phrase_norm(alias)
            if alias_norm and _duplicate_phrase_present_in_normalized_text(alias_norm, normalized):
                found.add(str(key))
                break
    return found


def _remove_confirmation_team_phrases(text: str) -> str:
    value = str(text or "")
    try:
        catalog = all_team_catalog_items()
    except Exception:
        catalog = TEAM_CATALOG
    aliases: list[str] = []
    for key, info in (catalog or {}).items():
        aliases.extend([str(key), str((info or {}).get("name", ""))])
        aliases.extend(str(alias) for alias in ((info or {}).get("aliases", []) or []))
    for alias in sorted({a for a in aliases if a}, key=len, reverse=True):
        value = re.sub(r"(?<![A-Za-z0-9א-ת])" + re.escape(alias) + r"(?![A-Za-z0-9א-ת])", " ", value, flags=re.I)
    return re.sub(r"\s+", " ", value).strip()


def _confirmation_name_phrases(text: str) -> set[str]:
    """Extract real named subjects; team names and football action words are excluded."""
    raw = html.unescape(_remove_confirmation_team_phrases(text))
    phrases: set[str] = set()
    # Most X sources use capitalised Latin names. Capture full names first.
    latin_pattern = re.compile(
        r"(?<!\w)(?:[A-ZÀ-ÖØ-Þ][A-Za-zÀ-ÖØ-öø-ÿ'’.-]{2,}"
        r"(?:\s+(?:de|da|di|del|van|von|dos|do|la|le))?\s+){1,3}"
        r"[A-ZÀ-ÖØ-Þ][A-Za-zÀ-ÖØ-öø-ÿ'’.-]{2,}(?!\w)"
    )
    for match in latin_pattern.finditer(raw):
        norm = _duplicate_phrase_norm(match.group(0))
        if norm and not any(word in _CONFIRMATION_GENERIC_WORDS for word in norm.split()):
            phrases.add(norm)

    normalized = _duplicate_phrase_norm(raw)
    tokens = [token for token in normalized.split() if token]
    filtered = [
        token for token in tokens
        if len(re.sub(r"[^A-Za-zא-ת]", "", token)) >= 4
        and token.casefold() not in _CONFIRMATION_GENERIC_WORDS
        and token not in NEWS_DUP_STOPWORDS
        and token not in NEWS_DUP_ACTION_WORDS
    ]
    # Hebrew or all-lowercase source fallback: an adjacent pair is accepted only
    # after team/action words were removed, making a player's full name the stable key.
    for first, second in zip(filtered, filtered[1:]):
        phrases.add(first + " " + second)
    # A distinctive surname can be enough when the destination club and action
    # family also match, but only for long non-generic tokens.
    for token in filtered:
        if len(token) >= 6:
            phrases.add(token)
    return phrases


def _fabrizio_confirmation_match(post: Post, item: Any) -> bool:
    """Return True only for the same named player/person, same club context and same event family."""
    if not isinstance(item, dict):
        return False
    source = str(item.get("username") or item.get("source") or "").strip().lstrip("@").casefold()
    if source not in _FABRIZIO_CONFIRMATION_SOURCES or is_pending_memory_item(item):
        return False

    previous_signature = item.get("signature", {})
    if not isinstance(previous_signature, dict) or not previous_signature:
        return False
    current_signature = news_event_signature(post)
    current_actions = set(current_signature.get("actions", []))
    previous_actions = set(previous_signature.get("actions", []))
    if not _duplicate_family_overlap(current_actions, previous_actions):
        return False

    current_text = _post_original_text(post) or post.text
    previous_text = _confirmation_item_text(item)
    current_teams = _confirmation_team_ids(current_text)
    previous_teams = _confirmation_team_ids(previous_text)
    if not (current_teams & previous_teams):
        return False

    current_players, _ = _canonical_sets_from_signature(current_signature)
    previous_players, _ = _canonical_sets_from_signature(previous_signature)
    if current_players and previous_players:
        return bool(current_players & previous_players)

    current_names = _confirmation_name_phrases(current_text)
    previous_names = _confirmation_name_phrases(previous_text)
    return bool(current_names & previous_names)


def mark_fabrizio_confirmation_from_state(post: Post, state: dict[str, Any]) -> str:
    # Clear any stale dynamic flag if the same Post instance is rechecked.
    setattr(post, "fabrizio_confirmation", False)
    setattr(post, "fabrizio_confirmation_source", "")
    if str(getattr(post, "username", "") or "").casefold() != _FABRIZIO_USERNAME:
        return ""
    for item in reversed(cleanup_recent_news_events(state)):
        if _fabrizio_confirmation_match(post, item):
            source_key = str(item.get("username") or "").strip().lstrip("@").casefold()
            setattr(post, "fabrizio_confirmation", True)
            setattr(post, "fabrizio_confirmation_source", source_key)
            return source_key
    return ""


_previous_find_reply_target_strict_fabrizio = find_bot_reply_target_for_post


def find_bot_reply_target_for_post(post: Post, state: dict[str, Any]) -> dict[str, int]:
    """Fabrizio replies only after the dedicated 100%-same-report matcher succeeds."""
    if str(getattr(post, "username", "") or "").casefold() != _FABRIZIO_USERNAME:
        return _previous_find_reply_target_strict_fabrizio(post, state)

    mark_fabrizio_confirmation_from_state(post, state)
    if not bool(getattr(post, "fabrizio_confirmation", False)):
        # A good but uncertain/different Fabrizio report is sent normally, with no
        # confirmation heading and no reply target. It is not blocked.
        return {}

    for source_items in (cleanup_bot_sent_reply_targets(state), cleanup_channel_recent_news_events(state)):
        for item in reversed(source_items):
            if _fabrizio_confirmation_match(post, item):
                stored = _message_ids_from_reply_item(item)
                if stored:
                    return stored
    return {}


# Fabrizio reports that pass the hard safety gates are never suppressed by fuzzy
# similarity. Absolute post-id/link dedupe remains unchanged in the normal state path.
_previous_find_recent_duplicate_strict_fabrizio = find_recent_duplicate_event
_previous_find_channel_duplicate_strict_fabrizio = find_channel_duplicate_event
_previous_find_translation_duplicate_strict_fabrizio = find_post_translation_duplicate_event


