#   leaving the monitoring menu untouched, like the daily summary button.

_BEN_JACOBS_USERNAME = "jacobsben"
_BEN_JACOBS_CONCRETE_NEWS_RE = re.compile(
    r"\b(?:agreement(?:\s+in\s+principle)?|agreed(?:\s+in\s+principle)?|deal|bid|offer|proposal|"
    r"negotiations?|talks?|contacts?|approach(?:ed)?|interest|shortlist|target|sign(?:ing|ed|s)?|"
    r"join(?:ing|ed|s)?|transfer|move|contract|extension|renewal|medical|documents?|paperwork|"
    r"fee|million|deadline|hours?|reject(?:ed|s)?|accept(?:ed|s)?|decision|exit|departure|"
    r"free agent|loan|option to buy|release clause|sell[- ]on|resale clause)\b|"
    r"הסכ(?:ם|מה|ימו)|סיכמ(?:ה|ו)?|עסק(?:ה|ת)|הצעה|משא\s+ומתן|מו[\"״']?מ|מגעים|שיחות|"
    r"פנתה|פנה|עניין|מועמד|יעד|החתמ(?:ה|ת)|חתמ(?:ה|ו)?|יצטרף|מצטרף|העבר(?:ה|ת)|מעבר|"
    r"חוזה|הארכה|בדיקות\s+רפואיות|מסמכים|דמי\s+העברה|מיליון|דדליין|שעות|דחה|דחתה|נדחתה|"
    r"אישר|אישרה|עזיבה|לעזוב|שחקן\s+חופשי|השאלה|אופציית\s+רכישה|סעיף\s+שחרור|סעיף\s+מכירה",
    re.IGNORECASE | re.UNICODE,
)
_BEN_JACOBS_STRONG_DETAIL_RE = re.compile(
    r"(?:€|£|\$)\s*\d|\b\d+(?:[.,]\d+)?\s*(?:m|million|hours?|days?)\b|"
    r"\d+(?:[.,]\d+)?\s*(?:מיליון|שעות|ימים)|agreement\s+in\s+principle|"
    r"הסכם\s+עקרוני|עסקה\s+עקרונית|הצעה\s+(?:שנייה|שלישית|רשמית|אחרונה)",
    re.IGNORECASE | re.UNICODE,
)


def is_ben_jacobs_concrete_report(post: Any) -> bool:
    """Recognize a substantive Ben Jacobs football-news update.

    The report may still be provisional (talks, bid, agreement in principle,
    rejection or deadline). It does not need to be 100% completed to be useful.
    """
    if not isinstance(post, Post):
        return False
    if str(getattr(post, "username", "") or "").strip().lstrip("@").casefold() != _BEN_JACOBS_USERNAME:
        return False
    source = html.unescape("\n".join([_post_original_text(post), _post_original_text(post, quoted=True)]))
    cleaned = clean_for_ai_translation(source)
    if count_content_words(cleaned) < 10:
        return False
    if not _BEN_JACOBS_CONCRETE_NEWS_RE.search(cleaned):
        return False
    # Require actual report substance: a strong mechanic/detail, a tracked club,
    # or multiple concrete transfer actions. This prevents generic opinion posts.
    mechanics = len(_BEN_JACOBS_CONCRETE_NEWS_RE.findall(cleaned))
    substantive = bool(
        _BEN_JACOBS_STRONG_DETAIL_RE.search(cleaned)
        or _CONCRETE_TRANSFER_REPORT_RE.search(cleaned)
        or _TRANSFER_NEWS_MECHANIC_RE.search(cleaned)
        or _matches_any(FINAL_OR_NEAR_FINAL_PATTERNS, cleaned)
        or _matches_any(FINAL_ONLY_STRICT_PATTERNS, cleaned)
        or _tracked_club_in_text(cleaned)
        or mechanics >= 2
    )
    return substantive


_previous_concrete_report_before_ben_jacobs = concrete_tracked_football_report


def concrete_tracked_football_report(post: Post) -> bool:
    if is_ben_jacobs_concrete_report(post):
        return True
    return _previous_concrete_report_before_ben_jacobs(post)


# Two early run_once filters execute before the consolidated final rescue.
# Bypass them only for a substantive Ben Jacobs report.
def _install_ben_jacobs_false_filter(name: str) -> None:
    previous = globals().get(name)
    if not callable(previous):
        return

    def wrapper(post: Post, *args: Any, _previous=previous, **kwargs: Any):
        if is_ben_jacobs_concrete_report(post):
            return False
        return _previous(post, *args, **kwargs)

    wrapper.__name__ = name
    globals()[name] = wrapper


for _ben_early_filter in (
    "has_small_total_transfer_fee",
    "is_minor_destination_from_big_club_source",
):
    _install_ben_jacobs_false_filter(_ben_early_filter)


_previous_importance_before_ben_jacobs = football_importance_block_reason


