def persistent_duplicate_candidate(*parts: Any, threshold: float = 0.86) -> dict[str, Any] | None:
    if any(isinstance(part, Post) and is_ben_jacobs_concrete_report(part) for part in parts):
        return None
    return _previous_persistent_duplicate_before_ben_jacobs(*parts, threshold=threshold)


_previous_cluster_before_ben_jacobs = cluster_parallel_candidates


def cluster_parallel_candidates(candidates: list[tuple[str, Post, float]]) -> list[tuple[str, Post, float]]:
    protected = [item for item in candidates if is_ben_jacobs_concrete_report(item[1])]
    ordinary = [item for item in candidates if item not in protected]
    combined = list(_previous_cluster_before_ben_jacobs(ordinary) or []) + protected
    seen_absolute: set[str] = set()
    result: list[tuple[str, Post, float]] = []
    for item in sorted(combined, key=lambda row: float(getattr(row[1], "published_ts", 0.0) or 0.0), reverse=True):
        post = item[1]
        identity = str(post.post_id or post.link or post_content_signature(post.username, post.text, post.quoted_text))
        if identity and identity in seen_absolute:
            continue
        if identity:
            seen_absolute.add(identity)
        result.append(item)
    return result


