def process_control_update(update: dict[str, Any]) -> None:
    callback = update.get("callback_query") or {}
    data = str(callback.get("data", "") or "")
    if data not in {"football_last_blocked", "football_last_duplicate"}:
        return _previous_process_control_before_separate_reports(update)

    callback_id = str(callback.get("id", "") or "")
    message = callback.get("message", {}) or {}
    chat_id = str((message.get("chat", {}) or {}).get("id", ""))
    if CONTROL_CHAT_ID and chat_id != CONTROL_CHAT_ID:
        if callback_id:
            answer_control_callback(callback_id, "אין הרשאה לערוץ הזה")
        return

    if data == "football_last_blocked":
        if callback_id:
            answer_control_callback(callback_id, "שולח 30 חסימות בהודעה נפרדת")
        send_control_text_async(
            "📋 מכין 30 חסימות אחרונות...",
            _recent_blocked_separate_report,
            message.get("message_id"),
            monitor_menu_reply_markup(),
            result_reply_markup=control_delete_message_reply_markup(),
            full_result=True,
            loading_new_message=True,
        )
        return

    if callback_id:
        answer_control_callback(callback_id, "שולח 10 כפילויות בהודעה נפרדת")
    send_control_text_async(
        "🧠 מכין 10 כפילויות אחרונות...",
        _recent_duplicate_separate_report,
        message.get("message_id"),
        monitor_menu_reply_markup(),
        result_reply_markup=control_delete_message_reply_markup(),
        full_result=True,
        loading_new_message=True,
    )

