def _ensure_post_original_structure(post: Any) -> Any:
    if not isinstance(post, Post):
        return post
    if not str(getattr(post, "original_text", "") or ""):
        post.original_text = str(getattr(post, "text", "") or "")
    if not str(getattr(post, "original_quoted_text", "") or ""):
        post.original_quoted_text = str(getattr(post, "quoted_text", "") or "")
    if not hasattr(post, "source_structure_available"):
        source = "\n".join([
            str(getattr(post, "original_text", "") or ""),
            str(getattr(post, "original_quoted_text", "") or ""),
        ])
        post.source_structure_available = "\n" in source
    return post


