def post_to_control_payload(post: "Post") -> dict[str, Any]:
    payload = _previous_post_to_control_payload_deep(post)
    payload["original_text"] = str(getattr(post, "original_text", "") or getattr(post, "text", "") or "")
    payload["original_quoted_text"] = str(getattr(post, "original_quoted_text", "") or getattr(post, "quoted_text", "") or "")
    payload["raw_source_html"] = str(getattr(post, "raw_source_html", "") or "")
    payload["source_structure_available"] = bool(getattr(post, "source_structure_available", False))
    return payload


