def post_from_control_payload(payload: Any) -> "Post | None":
    post = _previous_post_from_control_payload_deep(payload)
    if post is None:
        return None
    if isinstance(payload, dict):
        post.original_text = str(payload.get("original_text", "") or post.text or "")
        post.original_quoted_text = str(payload.get("original_quoted_text", "") or post.quoted_text or "")
        post.raw_source_html = str(payload.get("raw_source_html", "") or "")
        post.source_structure_available = bool(
            payload.get("source_structure_available", False)
            or "\n" in post.original_text
            or "\n" in post.original_quoted_text
        )
    return _ensure_post_original_structure(post)


def _daemon_call_with_timeout(label: str, producer: Any, timeout_seconds: float) -> tuple[Any, str]:
    """Run a control-only reader without allowing one mirror to freeze the button."""
    import queue
    result_queue: "queue.Queue[tuple[bool, Any]]" = queue.Queue(maxsize=1)

    def runner() -> None:
        try:
            result_queue.put((True, producer()))
        except Exception as exc:
            result_queue.put((False, exc))

    Thread(target=runner, daemon=True, name=f"control-{label}").start()
    try:
        ok, value = result_queue.get(timeout=max(1.0, float(timeout_seconds)))
    except queue.Empty:
        return None, f"{label}: timeout after {timeout_seconds:.0f}s"
    if ok:
        return value, ""
    return None, f"{label}: {short_error(value, 260)}"


def _control_history_aliases(username: str) -> list[str]:
    value = str(username or "").strip().lstrip("@")
    if value_contains_football_factly(value):
        return [FOOTBALL_FACTLY_DEFAULT_ACTIVE_USERNAME, "footballfactly", "Football_Factly"]
    if value_contains_optajoe(value):
        return [OPTAJOE_DEFAULT_ACTIVE_USERNAME, "optajoe", "Opta_Joe"]
    return [value]


def _collect_history_nonnetwork(username: str, merged: dict[str, Post], diagnostics: dict[str, Any]) -> None:
    def add(stage: str, values: Any) -> None:
        before = len(merged)
        try:
            for post in values or []:
                if not isinstance(post, Post):
                    continue
                _ensure_post_original_structure(post)
                post.username = username
                identity = _ten_history_post_identity(username, post)
                if identity and identity not in merged:
                    merged[identity] = post
            diagnostics["sources"][stage] = len(merged) - before
        except Exception as exc:
            diagnostics["sources"][stage] = 0
            diagnostics["errors"].append(f"{stage}: {short_error(exc, 240)}")

    add("memory_cache", _control_cached_posts(username))
    add("saved_history", _ten_history_load(username))
    add("known_control_state", _ten_history_collect_existing_state_posts(username))

    sent_rows = load_json_list_file(persistent_memory_path("football_sent_memory.json"))[-900:]
    add("sent_memory", [post for item in sent_rows if (post := _post_from_sent_memory_item(username, item)) is not None])


def fetch_last_ten_control_isolated(username: str, limit: int = 10) -> list[Post]:
    """Fast, failure-tolerant ten-post reader; automatic RSS publishing is untouched."""
    username = _canonical_control_source_username(username) if "_canonical_control_source_username" in globals() else str(username or "")
    merged: dict[str, Post] = {}
    diagnostics: dict[str, Any] = {"sources": {}, "errors": [], "requested": int(limit)}
    _collect_history_nonnetwork(username, merged, diagnostics)

    def add_network(stage: str, values: Any) -> None:
        before = len(merged)
        for post in values or []:
            if not isinstance(post, Post):
                continue
            _ensure_post_original_structure(post)
            post.username = username
            identity = _ten_history_post_identity(username, post)
            if identity and identity not in merged:
                merged[identity] = post
        diagnostics["sources"][stage] = len(merged) - before

    # One real RSS aggregation is normally enough. Older code retried the same
    # mirrors through several wrappers and could keep FootballFactly spinning for
    # over a minute. This call has a hard control-only timeout.
    if len(merged) < limit:
        fetched: list[Post] = []
        for alias_index, alias in enumerate(_control_history_aliases(username)):
            values, error = _daemon_call_with_timeout(
                f"rss_{alias}", lambda a=alias: fetch_posts(a) or [], CONTROL_TEN_FETCH_TIMEOUT_SECONDS
            )
            if error:
                diagnostics["errors"].append(error)
            if values:
                fetched = list(values)
                diagnostics["rss_alias"] = alias
                break
            # Do not repeat three slow mirror sweeps. A second spelling is useful
            # only for the two special sources and gets a shorter attempt.
            if alias_index == 0 and len(_control_history_aliases(username)) > 1:
                continue
            break
        add_network("normal_fetch", fetched)

    # A separate safe fallback is attempted only when the first reader returned
    # no post at all and history is still empty. Failure never aborts the button.
    if not merged:
        fallback, error = _daemon_call_with_timeout(
            "control_fallback",
            lambda: fetch_control_posts_reliable(username, limit=max(10, int(limit))) or [],
            max(8.0, CONTROL_TEN_FETCH_TIMEOUT_SECONDS),
        )
        if error:
            diagnostics["errors"].append(error)
        add_network("control_fallback", fallback or [])

    ordered = sorted(merged.values(), key=lambda post: float(getattr(post, "published_ts", 0.0) or 0.0), reverse=True)
    diagnostics["after_dedupe"] = len(ordered)
    diagnostics["returned"] = min(int(limit), len(ordered))
    LAST_TEN_HISTORY_DIAGNOSTICS[_ten_history_account_key(username)] = diagnostics
    if ordered:
        try:
            _remember_control_rss_posts(username, ordered)
        except Exception as exc:
            diagnostics["errors"].append(f"memory_cache_save: {short_error(exc, 180)}")
        try:
            _ten_history_save(username, ordered)
        except Exception as exc:
            diagnostics["errors"].append(f"saved_history_write: {short_error(exc, 180)}")
    return ordered[:max(1, int(limit))]


def _translate_history_posts_parallel(posts: list[Post]) -> list[str]:
    if not posts:
        return []
    executor = ThreadPoolExecutor(max_workers=min(5, len(posts)))
    futures = {executor.submit(_translate_history_post, post): index for index, post in enumerate(posts)}
    results = [""] * len(posts)
    try:
        from concurrent.futures import wait
        done, pending = wait(futures, timeout=max(3.0, CONTROL_TEN_TRANSLATE_TIMEOUT_SECONDS))
        for future in done:
            index = futures[future]
            try:
                results[index] = str(future.result() or "").strip()
            except Exception:
                results[index] = ""
        for future in pending:
            future.cancel()
    finally:
        executor.shutdown(wait=False, cancel_futures=True)
    for index, post in enumerate(posts):
        if not results[index]:
            results[index] = clean_for_ai_translation(html.unescape(post.text or "")).strip() or "אין טקסט זמין"
    return results


