# HERE WE GO may come only from the untouched textual X/RSS caption. Image text,
# deal status and model invention never authorize it.
_HERE_WE_GO_SOURCE_RE = re.compile(
    r"(?<![A-Za-z])#?here\s*[,!:.\-–—]*\s*we\s*[,!:.\-–—]*\s*go(?![A-Za-z])|"
    r"(?<![A-Za-z])#?herewego(?![A-Za-z])",
    re.IGNORECASE | re.UNICODE,
)
_HERE_WE_GO_OUTPUT_RE = re.compile(
    r"(?<![A-Za-z])#?here\s*[,!:.\-–—]*\s*we\s*[,!:.\-–—]*\s*go(?![A-Za-z])|"
    r"(?<![A-Za-z])#?herewego(?![A-Za-z])|היר\s*ווי\s*גו|"
    r"הנה\s*[,!:-]?\s*(?:זה\s+קורה|אנחנו\s+הולכים|זה\s+בא|זה\s+הולך)|"
    r"כאן\s+אנחנו\s+הולכים",
    re.IGNORECASE | re.UNICODE,
)


def _enforce_here_we_go_from_source(post: Post, translated: str) -> str:
    source = _post_original_text(_ensure_post_original_structure(post), quoted=False)
    source_has = bool(_HERE_WE_GO_SOURCE_RE.search(source))
    value = str(translated or "")
    matches = list(_HERE_WE_GO_OUTPUT_RE.finditer(value))
    if source_has:
        if matches:
            value = _HERE_WE_GO_OUTPUT_RE.sub("HERE WE GO", value)
            seen = False
            value = re.sub(
                r"(?i)(?<![A-Za-z])HERE\s+WE\s+GO(?![A-Za-z])",
                lambda m: "HERE WE GO" if not (seen := getattr(_enforce_here_we_go_from_source, '_seen', False)) else "",
                value,
            )
            # The lambda above cannot safely carry local assignment across calls;
            # normalize once more deterministically.
            parts = re.split(r"(?i)(?<![A-Za-z])HERE\s+WE\s+GO(?![A-Za-z])", value)
            value = parts[0] + "HERE WE GO" + "".join(parts[1:]) if len(parts) > 1 else value
        else:
            value = value.rstrip(" .,!;:") + ", HERE WE GO!"
    else:
        value = _HERE_WE_GO_OUTPUT_RE.sub("", value)
    value = re.sub(r"[ \t]+([,.;!?])", r"\1", value)
    value = re.sub(r"([,;])\s*([.!?])", r"\2", value)
    value = re.sub(r"[ \t]{2,}", " ", value)
    value = re.sub(r"(?m)^\s*[,;:.-]+\s*$", "", value)
    return re.sub(r"\n{3,}", "\n\n", value).strip(" \t,;:-")


# Strict Fabrizio confirmation: no person match means no confirmation. A shared
# club or similar wording alone is never enough. Uncertain reports are still sent
# normally because Fabrizio fuzzy-duplicate blockers remain disabled below.
def _strict_confirmation_person_keys(text: str, signature: dict[str, Any]) -> set[str]:
    players, _teams = _canonical_sets_from_signature(signature)
    keys = {f"player:{str(value).casefold()}" for value in players if str(value).strip()}
    cleaned = _remove_confirmation_team_phrases(str(text or "")) if "_remove_confirmation_team_phrases" in globals() else str(text or "")
    for phrase in _confirmation_name_phrases(cleaned):
        norm = _duplicate_phrase_norm(phrase)
        words = [word for word in norm.split() if word and word not in _CONFIRMATION_GENERIC_WORDS]
        # Require a full two-word name. Single surnames and generic adjacent words
        # are too risky for a "Fabrizio confirms" heading.
        if len(words) >= 2:
            keys.add("name:" + " ".join(words[:4]))
    return keys


def _fabrizio_confirmation_match(post: Post, item: Any) -> bool:
    if not isinstance(post, Post) or not isinstance(item, dict):
        return False
    if str(getattr(post, "username", "") or "").strip().lstrip("@").casefold() != _FABRIZIO_USERNAME:
        return False
    source = str(item.get("username") or item.get("source") or "").strip().lstrip("@").casefold()
    if source not in _FABRIZIO_CONFIRMATION_SOURCES or is_pending_memory_item(item):
        return False
    item_ts = float(item.get("ts", 0.0) or 0.0)
    if item_ts and time.time() - item_ts > 72 * 60 * 60:
        return False
    previous_signature = item.get("signature", {})
    if not isinstance(previous_signature, dict) or not previous_signature:
        return False
    current_signature = news_event_signature(post)
    if not _duplicate_family_overlap(set(current_signature.get("actions", [])), set(previous_signature.get("actions", []))):
        return False
    current_text = _post_original_text(post) or post.text
    previous_text = _confirmation_item_text(item)
    current_people = _strict_confirmation_person_keys(current_text, current_signature)
    previous_people = _strict_confirmation_person_keys(previous_text, previous_signature)
    if not current_people or not previous_people or not (current_people & previous_people):
        return False
    current_teams = _confirmation_team_ids(current_text)
    previous_teams = _confirmation_team_ids(previous_text)
    if not current_teams or not previous_teams or not (current_teams & previous_teams):
        return False
    return True


