    r"negotiations?\s+with|appointed|named\s+(?:as\s+)?(?:head\s+)?coach|sacked|dismissed|fired|left|leaves|resigned|"
    r"contract\s+extension|extended\s+(?:his\s+)?contract|federation\s+decision)\b|"
