# ---------------------------------------------------------------------------
# 6) Quiet-channel preparation sends every media item the main channel would
#    receive. Telegram albums cannot carry inline buttons, so multi-photo posts
#    are sent as one captioned album followed only by a compact action row.
# ---------------------------------------------------------------------------
_PRE_ALL_MEDIA_CONTROL_CANDIDATE = _send_full_control_candidate


def _send_full_control_candidate(post: Post, token: str, message_html: str) -> list[int]:
    _reliable_hydrate_exact_post(post, force=True)
    if _acceptance_post_requires_video(post):
        return _PRE_ALL_MEDIA_CONTROL_CANDIDATE(post, token, message_html)
    images = selected_post_images(post)
    if len(images) <= 1:
        return _PRE_ALL_MEDIA_CONTROL_CANDIDATE(post, token, message_html)
    if not CONTROL_CHAT_ID:
        return []
    if not _acceptance_caption_fits(message_html):
        send_control_text(
            "⛔ לא ניתן להכין את אלבום התמונות עם הכיתוב המלא בהודעה אחת.\n\n" +
            hebrew_block_reason("caption_too_long_for_single_media_message"),
            None,
            control_delete_message_reply_markup(),
        )
        return []
    media: list[dict[str, Any]] = []
    for index, image_url in enumerate(images):
        item: dict[str, Any] = {"type": "photo", "media": image_url}
        if index == 0:
            item["caption"] = message_html
            item["parse_mode"] = "HTML"
        media.append(item)
    try:
        response = telegram_api(
            "sendMediaGroup",
            {"chat_id": CONTROL_CHAT_ID, "media": media},
            max_attempts=1,
            timeout=max(TELEGRAM_BUTTON_FAST_TIMEOUT_SECONDS, REQUEST_TIMEOUT_SECONDS),
        )
        ids = _telegram_result_message_ids(response)
        if ids:
            CONTROL_TELEGRAM_MEDIA_CACHE[token] = list(ids)
            _save_prepared_media_ids(token, ids)
            send_control_html(
                "✅ הפוסט הוכן עם כל המדיה המקורית.",
                control_send_to_main_reply_markup(token),
            )
        return ids
    except Exception as exc:
        logging.warning("Full quiet-channel album preparation failed: %s", short_error(exc, 500))
        send_control_text(
            "⛔ הכנת כל התמונות בערוץ השקט נכשלה; לא נשלחה תצוגה חלקית.\n\n" + short_error(exc, 800),
            None,
            control_delete_message_reply_markup(),
        )
        return []


# ---------------------------------------------------------------------------
# 7) Returning/forwarding a post to the quiet channel produces ONE details
#    message containing the complete Google translation. It never copies the
#    same post again as a separate message.
# ---------------------------------------------------------------------------
def _single_details_post_from_row(row: dict[str, Any]) -> Post | None:
    value = row.get("post") if isinstance(row, dict) else None
    if isinstance(value, Post):
        return value
    if isinstance(value, dict):
        try:
            return post_from_control_payload(value)
        except Exception:
            return None
    return None


def _single_details_original_text(row: dict[str, Any], message: dict[str, Any], post: Post | None) -> str:
    candidates: list[str] = []
    if isinstance(post, Post):
        try:
            candidates.append(_requested_source_text(post))
        except Exception:
            candidates.append(str(getattr(post, "text", "") or ""))
        quoted = str(getattr(post, "quoted_text", "") or "").strip()
        if quoted:
            candidates.append(quoted)
    for key in ("original_text", "text", "full_text", "rendered", "preview"):
        value = row.get(key) if isinstance(row, dict) else ""
        if value:
            candidates.append(str(value))
    target = _forward_target_message(message) if "_forward_target_message" in globals() else message
    candidates.extend([
        str(target.get("text") or ""),
        str(target.get("caption") or ""),
    ])
    value = max((candidate.strip() for candidate in candidates if str(candidate).strip()), key=len, default="")
    value = html_message_to_plain_text(value)
    value = re.sub(
        r"(?is)(?:\n\s*){1,3}נטו\s+ספורט\.?\s*📝(?:\s*\([^\n]*t\.me/neto_sport[^\n]*\))?\s*$",
        "",
        value,
    ).strip()
    return value


def _google_translate_preserve_full_layout(value: str) -> str:
    original = str(value or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not original:
        return ""
    parts = re.split(r"(\n\s*\n)", original)
    output: list[str] = []
    for part in parts:
        if re.fullmatch(r"\n\s*\n", part or ""):
            output.append("\n\n")
            continue
        paragraph = part.strip()
        if not paragraph:
            output.append(part)
            continue
        try:
            translated = google_translate(paragraph)
        except Exception:
            translated = paragraph
        translated = preserve_original_country_flags(paragraph, preserve_original_emojis(paragraph, translated))
        translated = final_hebrew_polish(translated)
        output.append(str(translated or paragraph).strip())
    result = "".join(output)
    result = re.sub(r"\n{3,}", "\n\n", result).strip()
    return _ensure_real_paragraph_punctuation(result)


def _single_details_reason(row: dict[str, Any], post: Post | None) -> str:
    for key in ("reason_he", "block_reason_he", "reason", "raw_reason", "block_reason"):
        value = str(row.get(key) or "").strip() if isinstance(row, dict) else ""
        if value:
            return hebrew_block_reason(value)
    if isinstance(post, Post):
        try:
            value = _requested_block_reason_for_post(post)
            if value and value != "הפוסט הוכן או הוחזר לבדיקה ידנית":
                return value
        except Exception:
            pass
    return ""


def _single_details_compact_header(row: dict[str, Any], message: dict[str, Any]) -> str:
    username = str(row.get("username") or "").strip().lstrip("@")
    source_label = str(row.get("source_label") or "").strip()
    if not source_label and username:
        source_label = _hebrew_account_label(username)
    context = row.get("context") if isinstance(row.get("context"), dict) else {}
    link = str(row.get("link") or "").strip()
    lines = ["🔎 פרטי ההודעה", "", f"מקור הדיווח: {source_label or 'מקור לא מזוהה'}"]
    if username:
        lines.append(f"חשבון X: @{username}")
    lines.append(f"תאריך ושעת הפוסט: {_format_local_datetime(row.get('published_ts'))}")
    if link:
        lines.append(f"קישור לפוסט המקורי: {link}")
    telegram_link = _telegram_channel_link_from_context(context)
    if telegram_link:
        lines.append(f"קישור להודעה בערוץ: {telegram_link}")
    return "\n".join(lines)


def _send_single_control_details_message(text: str, message: dict[str, Any]) -> int | None:
    if not CONTROL_CHAT_ID:
        return None
    payload: dict[str, Any] = {
        "chat_id": CONTROL_CHAT_ID,
        "text": rtl(text),
        "disable_web_page_preview": True,
        "reply_markup": control_delete_message_reply_markup(),
    }
    if message.get("message_id"):
        payload["reply_to_message_id"] = int(message.get("message_id"))
        payload["allow_sending_without_reply"] = True
    if message.get("message_thread_id"):
        payload["message_thread_id"] = int(message.get("message_thread_id"))
    response = telegram_api(
        "sendMessage",
        payload,
        max_attempts=max(1, HTTP_RETRIES),
        timeout=max(TELEGRAM_BUTTON_FAST_TIMEOUT_SECONDS, REQUEST_TIMEOUT_SECONDS),
    )
    return _control_sent_message_id(response)


_PRE_SINGLE_DETAILS_CONTROL_TEXT_UPDATE = process_control_text_update


def process_control_text_update(update: dict[str, Any]) -> None:
    message = update.get("message") or update.get("channel_post") or update.get("edited_channel_post") or {}
    if isinstance(message, dict):
        chat_id = str((message.get("chat") or {}).get("id", ""))
        is_control = bool(CONTROL_CHAT_ID and chat_id == str(CONTROL_CHAT_ID))
        prepared_match = None
        if is_control:
            try:
                prepared_match = _requested_find_prepared_item(message)
            except Exception:
                prepared_match = None
        if is_control and (_message_has_forward_source_context(message) or prepared_match):
            try:
                if prepared_match:
                    _token, prepared_item = prepared_match
                    post = prepared_item.get("post")
                    if not isinstance(post, Post):
                        post = post_from_control_payload(post)
                    row = {
                        "post": post,
                        "username": str(getattr(post, "username", "") or "") if isinstance(post, Post) else "",
                        "source_label": _hebrew_account_label(str(getattr(post, "username", "") or "")) if isinstance(post, Post) else "",
                        "published_ts": float(getattr(post, "published_ts", 0.0) or 0.0) if isinstance(post, Post) else 0.0,
                        "link": str(getattr(post, "link", "") or "") if isinstance(post, Post) else "",
                        "context": _forward_context_v3(message) if "_forward_context_v3" in globals() else {},
                    }
                else:
                    row = _lookup_forwarded_source_v3(message)
                    post = _single_details_post_from_row(row)

                details = _forwarded_source_details_text(message) if not prepared_match else _single_details_compact_header(row, message)
                original = _single_details_original_text(row, message, post)
                translated = _google_translate_preserve_full_layout(original)
                source_label = str(row.get("source_label") or "").strip()
                username = str(row.get("username") or "").strip().lstrip("@")
                if not source_label and username:
                    source_label = _hebrew_account_label(username)
                if source_label and translated:
                    first_line = next((line.strip() for line in translated.splitlines() if line.strip()), "")
                    if first_line.rstrip(":：") != source_label.rstrip(":："):
                        translated = f"{source_label}:\n\n{translated}"
                reason = _single_details_reason(row, post)
                sections = [details]
                if reason:
                    sections.append("סיבת החסימה: " + reason)
                sections.append("📰 התוכן המקורי המלא בתרגום Google\n\n" + (translated or "לא נמצא תוכן מלא לשחזור"))
                combined = "\n\n".join(section.strip() for section in sections if section.strip())

                # Telegram permits one text message up to 4096 characters. Keep
                # the full translation authoritative and compact only technical
                # metadata when necessary; never send the post again separately.
                if len(rtl(combined)) > 4096:
                    compact_details = _single_details_compact_header(row, message)
                    sections[0] = compact_details
                    combined = "\n\n".join(section.strip() for section in sections if section.strip())
                if len(rtl(combined)) > 4096:
                    minimal = ["🔎 פרטי ההודעה", f"מקור הדיווח: {source_label or 'מקור לא מזוהה'}"]
                    if reason:
                        minimal.append("סיבת החסימה: " + reason)
                    minimal.append("📰 התוכן המקורי המלא בתרגום Google\n\n" + (translated or "לא נמצא תוכן מלא לשחזור"))
                    combined = "\n\n".join(minimal)
                _send_single_control_details_message(combined, message)
                return
            except Exception as exc:
                logging.exception("Single-message forwarded details reconstruction failed")
                try:
                    _send_single_control_details_message(
                        "לא הצלחתי לשחזר את פרטי ההודעה והתרגום המלא:\n" + short_error(exc, 900),
                        message,
                    )
                except Exception:
                    pass
                return
    return _PRE_SINGLE_DETAILS_CONTROL_TEXT_UPDATE(update)


# ---------------------------------------------------------------------------
# 2 + 4) Fast buttons and immediate NEW preparation status message.
# All non-prepare callbacks run in a bounded executor so one slow operation never
# blocks Telegram polling or another button click.
# ---------------------------------------------------------------------------
_CONTROL_BUTTON_EXECUTOR = ThreadPoolExecutor(max_workers=8, thread_name_prefix="control-button")
_PREPARE_BUTTON_INFLIGHT: set[str] = set()
_PREPARE_BUTTON_LOCK = RLock()
_PRE_FAST_BUTTON_PROCESS_CONTROL_UPDATE = process_control_update


def _run_prepare_button(token: str, status_message_id: int | None) -> None:
    try:
        prepare_history_post_with_ai(token)
        if status_message_id:
            send_control_text(
                "✅ הכנת הדיווח הסתיימה. ההודעה המוכנה מוצגת בהודעה חדשה.",
                status_message_id,
                control_delete_message_reply_markup(),
            )
    except Exception as exc:
        logging.exception("Prepare-report button task failed")
        if status_message_id:
            send_control_text(
                "⛔ הכנת הדיווח נכשלה:\n" + short_error(exc, 900),
                status_message_id,
                control_delete_message_reply_markup(),
            )
    finally:
        with _PREPARE_BUTTON_LOCK:
            _PREPARE_BUTTON_INFLIGHT.discard(token)


def process_control_update(update: dict[str, Any]) -> None:
    callback = update.get("callback_query") or {}
    if not callback:
        return _PRE_FAST_BUTTON_PROCESS_CONTROL_UPDATE(update)
    data = str(callback.get("data", "") or "")
    callback_id = str(callback.get("id", "") or "")
    message = callback.get("message", {}) or {}
    chat_id = str((message.get("chat", {}) or {}).get("id", ""))
    if CONTROL_CHAT_ID and chat_id != str(CONTROL_CHAT_ID):
        if callback_id:
            answer_control_callback(callback_id, "אין הרשאה לערוץ הזה")
        return

    if data.startswith("football_prepare_history_ai:"):
        token = data.split(":", 1)[1].strip()
        with _PREPARE_BUTTON_LOCK:
            already_running = token in _PREPARE_BUTTON_INFLIGHT
            if not already_running:
                _PREPARE_BUTTON_INFLIGHT.add(token)
        if already_running:
            if callback_id:
                answer_control_callback(callback_id, "הדיווח כבר נמצא בהכנה")
            return
        if callback_id:
            answer_control_callback(callback_id, "מתחיל להכין את הדיווח")
        status_id = send_control_text(
            "⏳ מתחיל להכין את הדיווח המלא באמצעות Gemini...",
            None,
            control_delete_message_reply_markup(),
        )
        Thread(target=_run_prepare_button, args=(token, status_id), daemon=True).start()
        return

    # Return immediately to getUpdates; the established callback handler keeps
    # its exact behavior inside the bounded worker.
    try:
        _CONTROL_BUTTON_EXECUTOR.submit(_PRE_FAST_BUTTON_PROCESS_CONTROL_UPDATE, update)
    except RuntimeError:
        Thread(target=_PRE_FAST_BUTTON_PROCESS_CONTROL_UPDATE, args=(update,), daemon=True).start()

# ====== END FINAL FOUR-RETRY / FAST CONTROL / FULL QUIET PREVIEW PATCH ======


# ----- Runtime attempt-index correction + exact returned-layout correction -----
_ACTIVE_TRANSLATION_ATTEMPT_LOCK = RLock()
_ACTIVE_TRANSLATION_ATTEMPT_BY_ID: dict[str, int] = {}
_PRE_ACTIVE_RETRY_SEND_POST = send_post
_PRE_ACTIVE_RETRY_LOG_SKIP = log_skip_once


def send_post(post: Post, reply_message_ids: dict[str, int] | None = None, state: dict[str, Any] | None = None) -> dict[str, Any]:
    identity = _acceptance_retry_identity(post)
    current_attempt = 0
    try:
        schedule = _gemini_retry_schedule(state)
        entry = dict(schedule.get(identity, {}) or {}) if identity else {}
        attempts_done = int(entry.get("attempts_done", 0) or 0)
        next_retry_at = float(entry.get("next_retry_at", 0.0) or 0.0)
        due = (
            not bool(entry.get("sent", False))
            and not bool(entry.get("exhausted", False))
            and attempts_done < TRANSLATION_TOTAL_ATTEMPTS
            and (attempts_done == 0 or time.time() >= next_retry_at)
        )
        if due:
            current_attempt = attempts_done + 1
            with _ACTIVE_TRANSLATION_ATTEMPT_LOCK:
                _ACTIVE_TRANSLATION_ATTEMPT_BY_ID[identity] = current_attempt
    except Exception:
        current_attempt = 1
        if identity:
            with _ACTIVE_TRANSLATION_ATTEMPT_LOCK:
                _ACTIVE_TRANSLATION_ATTEMPT_BY_ID[identity] = current_attempt
    try:
        return _PRE_ACTIVE_RETRY_SEND_POST(post, reply_message_ids=reply_message_ids, state=state)
    finally:
        if identity:
            with _ACTIVE_TRANSLATION_ATTEMPT_LOCK:
                _ACTIVE_TRANSLATION_ATTEMPT_BY_ID.pop(identity, None)


def log_skip_once(reason: str, post: "Post", message: str, *args: Any) -> None:
    if _four_retry_translation_reason(reason):
        identity = _acceptance_retry_identity(post)
        with _ACTIVE_TRANSLATION_ATTEMPT_LOCK:
            current_attempt = int(_ACTIVE_TRANSLATION_ATTEMPT_BY_ID.get(identity, 0) or 0)
        if current_attempt and current_attempt < TRANSLATION_TOTAL_ATTEMPTS:
            logging.warning(
                "Gemini translation attempt %s/%s failed for @%s; post remains pending and is not recorded as blocked.",
                current_attempt,
                TRANSLATION_TOTAL_ATTEMPTS,
                getattr(post, "username", ""),
            )
            return
        if current_attempt >= TRANSLATION_TOTAL_ATTEMPTS:
            return _PRE_FOUR_RETRY_LOG_SKIP("translation_unavailable", post, message, *args)
    return _PRE_ACTIVE_RETRY_LOG_SKIP(reason, post, message, *args)


# Combine main + quoted source instead of choosing only the longest fragment.
def _single_details_original_text(row: dict[str, Any], message: dict[str, Any], post: Post | None) -> str:
    candidates: list[str] = []
    if isinstance(post, Post):
        try:
            main_text = _requested_source_text(post)
        except Exception:
            main_text = str(getattr(post, "text", "") or "")
        quoted = str(getattr(post, "quoted_text", "") or "").strip()
        combined_post = str(main_text or "").strip()
        if quoted:
            combined_post = (combined_post + "\n\n" + quoted).strip()
        if combined_post:
            candidates.append(combined_post)
    for key in ("original_text", "text", "full_text", "rendered", "preview"):
        value = row.get(key) if isinstance(row, dict) else ""
        if value:
            candidates.append(str(value))
    target = _forward_target_message(message) if "_forward_target_message" in globals() else message
    candidates.extend([str(target.get("text") or ""), str(target.get("caption") or "")])
    value = max((candidate.strip() for candidate in candidates if str(candidate).strip()), key=len, default="")
    value = html_message_to_plain_text(value)
    value = re.sub(
        r"(?is)(?:\n\s*){1,3}נטו\s+ספורט\.?\s*📝(?:\s*\([^\n]*t\.me/neto_sport[^\n]*\))?\s*$",
        "",
        value,
    ).strip()
    return value


# Preserve every original line and every blank line in the Google translation.
def _google_translate_preserve_full_layout(value: str) -> str:
    original = str(value or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not original:
        return ""
    output: list[str] = []
    for line in original.split("\n"):
        if not line.strip():
            output.append("")
            continue
        source_line = line.strip()
        try:
            translated = google_translate(source_line)
        except Exception:
            translated = source_line
        translated = preserve_original_country_flags(source_line, preserve_original_emojis(source_line, translated))
        translated = final_hebrew_polish(translated)
        output.append(str(translated or source_line).strip())
    result = "\n".join(output)
    result = re.sub(r"\n{3,}", "\n\n", result).strip()
    return _ensure_real_paragraph_punctuation(result)

# ====== END RUNTIME ATTEMPT-INDEX CORRECTION ======


# ----- Prefer untouched source text and recover stored block reasons by identity -----
def _single_details_original_text(row: dict[str, Any], message: dict[str, Any], post: Post | None) -> str:
    ordered_candidates: list[str] = []
    if isinstance(post, Post):
        try:
            main_text = _requested_source_text(post)
        except Exception:
            main_text = str(getattr(post, "text", "") or "")
        quoted = str(getattr(post, "quoted_text", "") or "").strip()
        combined_post = str(main_text or "").strip()
        if quoted:
            combined_post = (combined_post + "\n\n" + quoted).strip()
        if combined_post:
            ordered_candidates.append(combined_post)
    if isinstance(row, dict):
        for key in ("original_text", "text", "full_text"):
            value = str(row.get(key) or "").strip()
            if value:
                ordered_candidates.append(value)
    target = _forward_target_message(message) if "_forward_target_message" in globals() else message
    for value in (str(target.get("text") or "").strip(), str(target.get("caption") or "").strip()):
        if value:
            ordered_candidates.append(value)
    if isinstance(row, dict):
        for key in ("rendered", "preview"):
            value = str(row.get(key) or "").strip()
            if value:
                ordered_candidates.append(value)
    value = next((candidate for candidate in ordered_candidates if candidate), "")
    value = html_message_to_plain_text(value)
    value = re.sub(
        r"(?is)(?:\n\s*){1,3}נטו\s+ספורט\.?\s*📝(?:\s*\([^\n]*t\.me/neto_sport[^\n]*\))?\s*$",
        "",
        value,
    ).strip()
    return value


def _single_details_reason(row: dict[str, Any], post: Post | None) -> str:
    for key in ("reason_he", "block_reason_he", "reason", "raw_reason", "block_reason"):
        value = str(row.get(key) or "").strip() if isinstance(row, dict) else ""
        if value:
            return hebrew_block_reason(value)
    if isinstance(post, Post):
        try:
            value = _requested_block_reason_for_post(post)
            if value and value != "הפוסט הוכן או הוחזר לבדיקה ידנית":
                return value
        except Exception:
            pass
    wanted_link = str(row.get("link") or "").split("?", 1)[0].rstrip("/") if isinstance(row, dict) else ""
    wanted_id = str(row.get("post_id") or "").strip() if isinstance(row, dict) else ""
    try:
        state = load_control_state()
    except Exception:
        state = {}
    if isinstance(state, dict):
        for key in ("last_blocked_posts", "last_duplicate_posts", "last_borderline_posts", "last_filtered_posts"):
            values = state.get(key, [])
            if not isinstance(values, list):
                continue
            for item in reversed(values):
                if not isinstance(item, dict):
                    continue
                item_link = str(item.get("link") or "").split("?", 1)[0].rstrip("/")
                item_id = str(item.get("post_id") or "").strip()
                if (wanted_link and item_link == wanted_link) or (wanted_id and item_id == wanted_id):
                    raw = str(item.get("reason_he") or item.get("reason") or item.get("raw_reason") or item.get("block_reason") or "").strip()
                    if raw:
                        return hebrew_block_reason(raw)
    return ""

# ====== END SOURCE PRIORITY / REASON RECOVERY ======


# ====== FINAL EXACT SOURCE LAYOUT / 20 BLOCKS / FACTS DELAY PATCH (2026-07-27) ======
# Scope: only the four requested changes. Existing RSS URLs/order, filters,
# translation models, account toggles and persistent JSON filenames/keys stay intact.

BOT_BUILD_ID = "winner-exact-source-layout-20-blocks-facts-delay-2026-07-27"
RECENT_BLOCKS_VISIBLE_LIMIT = 20
RECENT_BLOCKS_VISIBLE_MAX_AGE_SECONDS = 2 * 60 * 60


# ---------------------------------------------------------------------------
# 1) After translation, AS/אס רומא is always displayed simply as רומא.
# ---------------------------------------------------------------------------
_AS_ROMA_OUTPUT_RE = re.compile(
    r"(?iu)(?<![A-Za-zא-ת])(?:A\s*\.?\s*S\s*\.?|א\s*\.?\s*ס\s*\.?)\s+רומא(?![A-Za-zא-ת])"
)


def _remove_as_from_roma(value: str) -> str:
    text = _AS_ROMA_OUTPUT_RE.sub("רומא", str(value or ""))
    # When AS appeared after a Hebrew prefix, removing it may leave forms such
    # as "ל-רומא". Normalize only that exact artifact.
    text = re.sub(r"(?iu)(?<![א-ת])([בלכמשהו])-\s*רומא(?![א-ת])", r"\1רומא", text)
    text = re.sub(r"[ \t]{2,}", " ", text)
    return text


_PRE_EXACT_ROMA_FINAL_HEBREW_POLISH = final_hebrew_polish


def final_hebrew_polish(text: str) -> str:
    return _remove_as_from_roma(_PRE_EXACT_ROMA_FINAL_HEBREW_POLISH(text))


# ---------------------------------------------------------------------------
# 3) The final Telegram layout follows the actual X/RSS line separators exactly.
# No formatter is allowed to join a real source line or invent a paragraph.
# Orphan emoji-only lines keep the established behavior of attaching to the
# preceding content line, matching the expected flag layout in the user's sample.
# ---------------------------------------------------------------------------
def _exact_source_segments_and_separators(post: Post, quoted: bool = False) -> tuple[list[str], list[str]]:
    source = _post_original_text(post, quoted=quoted)
    source = _attach_orphan_emoji_lines(str(source or "").replace("\r\n", "\n").replace("\r", "\n"))
    source = _DIRECTIONAL_ONLY_RE.sub("", source).strip()
    if not source:
        return [], []
    chunks = re.split(r"(\n+)", source)
    segments: list[str] = []
    separators: list[str] = []
    pending = ""
    for chunk in chunks:
        if not chunk:
            continue
        if chunk.startswith("\n"):
            pending = "\n" * len(chunk)
            continue
        clean = chunk.strip()
        if not clean:
            continue
        if segments:
            # Preserve one newline versus a real blank line exactly. Telegram
            # cannot meaningfully display more than one blank row, so 3+ source
            # newlines remain a standard paragraph separator of two newlines.
            separators.append("\n\n" if len(pending) >= 2 else "\n")
        segments.append(clean)
        pending = ""
    return segments, separators


_PRE_EXACT_SOURCE_LAYOUT_FINAL = _restore_source_layout


# Preserve an already correctly positioned HERE WE GO token. Older final cleanup
# removed it and reinserted it by character ratio, which could reorder Hebrew words.
_PRE_EXACT_POSITION_SPECIAL_PHRASES = _final_restore_authorized_special_phrases


def _final_restore_authorized_special_phrases(post: Post, value: str) -> str:
    source = _post_original_text(_ensure_post_original_structure(post), quoted=False)
    text = str(value or "")
    if _FINAL_HWG_SOURCE_RE.search(source) and re.search(r"(?iu)#?HERE(?:_|\s)+WE(?:_|\s)+GO", text):
        text = re.sub(r"(?iu)#?HERE(?:_|\s)+WE(?:_|\s)+GO", "#HERE_WE_GO", text)
        first = text.find("#HERE_WE_GO")
        if first >= 0:
            head = text[:first + len("#HERE_WE_GO")]
            tail = text[first + len("#HERE_WE_GO"):].replace("#HERE_WE_GO", "")
            text = head + tail
        text = re.sub(r"[ \t]+([,.;!?])", r"\1", text)
        text = re.sub(r"\n{3,}", "\n\n", text)
        return text.strip()
    return _PRE_EXACT_POSITION_SPECIAL_PHRASES(post, text)


def _restore_source_layout(post: Post, translated: str, quoted: bool = False) -> str:
    value = _strip_internal_translation_output(translated)
    value = _remove_channel_signature_artifacts(value)
    value = _attach_orphan_emoji_lines(value)
    source_segments, source_separators = _exact_source_segments_and_separators(post, quoted=quoted)
    if not source_segments:
        return re.sub(r"\n{3,}", "\n\n", value).strip()

    translated_segments = [part.strip() for part in re.split(r"\n+", value) if part.strip()]
    if len(translated_segments) != len(source_segments):
        translated_segments = _allocate_translation_to_source_segments(source_segments, value)

    if len(translated_segments) == len(source_segments):
        rebuilt = translated_segments[0]
        for separator, segment in zip(source_separators, translated_segments[1:]):
            rebuilt += separator + segment
        value = rebuilt
    else:
        # Last resort: preserve the source separator positions by proportional
        # allocation. Never invoke the old paragraph invention/collapse logic.
        allocated = _allocate_translation_to_source_segments(source_segments, re.sub(r"\s*\n+\s*", " ", value))
        if len(allocated) == len(source_segments):
            value = allocated[0]
            for separator, segment in zip(source_separators, allocated[1:]):
                value += separator + segment

    value = _remove_as_from_roma(value)
    value = re.sub(r"[ \t]+\n", "\n", value)
    value = re.sub(r"\n[ \t]+", "\n", value)
    value = re.sub(r"\n{3,}", "\n\n", value)
    return value.strip()


# The prior patch added punctuation to every paragraph. Exact source layout means
# punctuation is never invented inside the body. The existing final-body rule may
# still add a missing terminal period only at the very end of the whole report.
def _ensure_real_paragraph_punctuation(value: str) -> str:
    return str(value or "")


# Build directly from the final source-driven body so older formatter wrappers
# cannot rejoin lines or add a period after an intermediate line such as "מרומא".
_FINAL_VISUAL_SUFFIX_RE = re.compile(
    r"(?s)(?P<suffix>[\s\u200d\ufe0e\ufe0f]*(?:(?:[\U0001F1E6-\U0001F1FF]{2})|[\U0001F300-\U0001FAFF]|[\u2600-\u27BF]|[\u200d\ufe0e\ufe0f])*)$"
)


def _clean_terminal_punctuation_without_touching_internal_lines(post: Post, value: str) -> str:
    text = str(value or "").rstrip()
    if not text:
        return text
    # Some historical HERE WE GO normalizers could leave punctuation after a
    # final emoji sequence. Remove it only when the untouched source has no such
    # punctuation after its final emoji.
    source = _post_original_text(_ensure_post_original_structure(post), quoted=False).rstrip()
    if not re.search(r"[.!?…]\s*$", source):
        text = re.sub(
            r"(?s)((?:(?:[\U0001F1E6-\U0001F1FF]{2})|[\U0001F300-\U0001FAFF]|[\u2600-\u27BF]|[\u200d\ufe0e\ufe0f])+)[,;:!?]+$",
            r"\1",
            text,
        )
    match = _FINAL_VISUAL_SUFFIX_RE.search(text)
    suffix = match.group("suffix") if match else ""
    core = text[:len(text) - len(suffix)].rstrip() if suffix else text.rstrip()
    if core and not re.search(r"[.!?…][\"'״׳)\]]*$", core):
        core += "."
    return (core + suffix).strip()


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    translated = _remove_as_from_roma(translated)
    body = _outgoing_body_text(post, translated, quoted=False)
    body = _remove_as_from_roma(body)
    if _final_is_plettigoal(post):
        body = _FINAL_SKY_INLINE_RE.sub(" ", body)
        body = re.sub(r"[ \t]{2,}", " ", body)
    body = _requested_safe_tail_cleanup(body)
    body = _final_remove_detached_short_tail(body)
    body = _requested_safe_tail_cleanup(body)
    # Add punctuation only at the end of the complete body, never at the end of
    # an internal source line or paragraph.
    body = _clean_terminal_punctuation_without_touching_internal_lines(post, body)
    body = _remove_as_from_roma(body) or "עדכון חדש"

    hide_writer = _is_footballfactly_post(post) or _is_optajoe_post(post) or should_hide_writer_header(post, body)
    display_name = ACCOUNT_DISPLAY_NAMES.get(post.username, post.username)
    if should_label_recycled_report(post):
        display_name = f"מיחזור של {display_name}"
    if bool(getattr(post, "fabrizio_confirmation", False)):
        display_name = "פבריציו רומאנו מאשר"
        hide_writer = False

    parts: list[str] = []
    if not hide_writer:
        parts.extend([f"<b>{html.escape(rtl(display_name + ':'), quote=False)}</b>", ""])
    parts.append(_safe_markdown_to_telegram_html(rtl(body)))
    signature = f'<a href="{html.escape(SIGNATURE_LINK, quote=True)}">{html.escape(rtl(SIGNATURE_TEXT), quote=False)}</a>'
    parts.extend(["", signature])
    return "\n".join(parts).strip()


# ---------------------------------------------------------------------------
# 2) Show only the latest 20 blocked posts, and only posts published in the last
# two hours. This applies to the regular monitor and the dedicated facts hub.
# ---------------------------------------------------------------------------
def _twenty_recent_visible_blocks(facts_only: bool = False) -> list[dict[str, Any]]:
    state = load_control_state()
    rows: list[dict[str, Any]] = []
    keys = ("last_blocked_posts", "last_duplicate_posts", "last_filtered_posts") if facts_only else ("last_blocked_posts",)
    for key in keys:
        raw = state.get(key, [])
        if not isinstance(raw, list):
            continue
        for item in raw:
            if not isinstance(item, dict):
                continue
            if _final_hide_from_block_reports(item):
                continue
            if facts_only and not _facts_item_canonical(item):
                continue
            rows.append(item)
    timestamp = _facts_item_timestamp if facts_only else lambda item: float(item.get("ts", 0.0) or item.get("created_at", 0.0) or _final_record_published_ts(item) or 0.0)
    rows.sort(key=timestamp)
    # Deduplicate records that were mirrored into more than one history list.
    unique: dict[str, dict[str, Any]] = {}
    for item in rows:
        identity = str(item.get("id") or item.get("post_id") or item.get("link") or hashlib.sha1(json.dumps(item, ensure_ascii=False, sort_keys=True, default=str).encode()).hexdigest())
        unique[identity] = item
    return list(unique.values())[-RECENT_BLOCKS_VISIBLE_LIMIT:]


def _final_visible_recent_block_items(limit: int = RECENT_BLOCKS_VISIBLE_LIMIT) -> list[dict[str, Any]]:
    return _twenty_recent_visible_blocks(False)[-max(1, min(int(limit), RECENT_BLOCKS_VISIBLE_LIMIT)):]


def _recent_blocked_separate_report() -> str:
    items = _twenty_recent_visible_blocks(False)
    return _control_list_text(
        "📋 20 חסימות אחרונות",
        items,
        "אין חסימות של פוסטים מהשעתיים האחרונות.",
        limit=RECENT_BLOCKS_VISIBLE_LIMIT,
    )


def facts_recent_blocks_text(limit: int = RECENT_BLOCKS_VISIBLE_LIMIT) -> str:
    rows = _twenty_recent_visible_blocks(True)[-max(1, min(int(limit), RECENT_BLOCKS_VISIBLE_LIMIT)):]
    if not rows:
        return "📋 20 חסימות אחרונות של מקורות העובדות\n\nאין חסימות של פוסטים מהשעתיים האחרונות."
    lines = ["📋 20 חסימות אחרונות של מקורות העובדות", ""]
    for item in reversed(rows):
        source = _facts_item_canonical(item)
        reason = hebrew_block_reason(str(item.get("reason_he") or item.get("raw_reason") or item.get("reason") or item.get("block_reason") or ""))
        preview = re.sub(r"\s+", " ", str(item.get("preview") or item.get("text") or item.get("original_text") or "")).strip()
        lines.append(f"• {_facts_source_label(source)}: {reason}" + (f" — {trim(preview, 100)}" if preview else ""))
    return "\n".join(lines)


def _replace_30_with_20_in_markup(markup: dict[str, Any]) -> dict[str, Any]:
    rows = [[dict(button) for button in row if isinstance(button, dict)] for row in (markup.get("inline_keyboard", []) if isinstance(markup, dict) else [])]
    for row in rows:
        for button in row:
            text = str(button.get("text", "") or "")
            if "30 חסימות" in text:
                button["text"] = text.replace("30 חסימות", "20 חסימות")
    return stable_reply_markup(rows)


_PRE_20_BLOCKS_MONITOR_MENU = monitor_menu_reply_markup


def monitor_menu_reply_markup() -> dict[str, Any]:
    return _replace_30_with_20_in_markup(_PRE_20_BLOCKS_MONITOR_MENU())


_PRE_20_BLOCKS_FACTS_MONITOR_MENU = facts_monitor_reply_markup


def facts_monitor_reply_markup() -> dict[str, Any]:
    markup = _replace_30_with_20_in_markup(_PRE_20_BLOCKS_FACTS_MONITOR_MENU())
    rows = [[dict(button) for button in row] for row in markup.get("inline_keyboard", [])]
    for row in rows:
        for button in row:
            if str(button.get("callback_data", "") or "") == "football_pipeline_timings":
                button["callback_data"] = "football_facts_pipeline_timings"
    return stable_reply_markup(rows)


# ---------------------------------------------------------------------------
# 4) Facts-source delay diagnostics are returned as one organized Telegram
# message, never one message per source/post.
# ---------------------------------------------------------------------------
def _facts_delay_metric(row: dict[str, Any], key: str, digits: int = 1) -> str:
    measured = row.get("measured") if isinstance(row.get("measured"), dict) else {}
    if not bool(measured.get(key, False)) or row.get(key) is None:
        return "—"
    return f"{float(row.get(key) or 0.0):.{digits}f}"


def facts_pipeline_timing_report_text(limit: int = 10) -> str:
    rows = [row for row in _final_recent_timing_rows(100) if _is_facts_source(str(row.get("username") or row.get("source") or ""))]
    rows = rows[-max(1, int(limit)):]
    if not rows:
        return "⏱️ בדיקת עיכוב למקורות העובדות\n\nעדיין אין מדידות של פוסטים ממקורות העובדות."

    lines = [
        "⏱️ בדיקת עיכוב למקורות העובדות",
        "",
        f"כל {len(rows)} הפוסטים האחרונים שנמדדו מוצגים יחד בהודעה הזאת.",
        "זמנים בשניות: גילוי | המתנה לעיבוד | סינון | כפילות | תרגום | מדיה | הכנה | שליחה/חסימה",
    ]
    for index, row in enumerate(rows, 1):
        source = _facts_source_label(str(row.get("username") or row.get("source") or ""))
        status = str(row.get("status") or "blocked")
        final_key = "telegram_send_seconds" if status == "sent" else "publish_to_blocked_seconds"
        final_label = "נשלח" if status == "sent" else "נחסם"
        published = _final_timing_clock(row.get("published_at"))
        metrics = " | ".join([
            _facts_delay_metric(row, "publish_to_first_seen_seconds", 1),
            _facts_delay_metric(row, "first_seen_to_processing_seconds", 2),
            _facts_delay_metric(row, "filter_seconds", 3),
            _facts_delay_metric(row, "duplicate_seconds", 3),
            _facts_delay_metric(row, "translation_seconds", 1),
            _facts_delay_metric(row, "media_lookup_seconds", 1),
            _facts_delay_metric(row, "prepare_seconds", 3),
            _facts_delay_metric(row, final_key, 1),
        ])
        lines.extend(["", f"{index}. {source} — {final_label} — {published}", metrics])
        if status != "sent":
            reason = str(row.get("block_reason_he") or hebrew_block_reason(str(row.get("block_reason") or "")))
            if reason:
                lines.append("סיבה: " + trim(reason, 120))

    lines.extend(["", "ממוצעים לפי כל הפוסטים שנמדדו:"])
    for key, label, digits in (
        ("publish_to_first_seen_seconds", "פרסום → גילוי", 1),
        ("first_seen_to_processing_seconds", "גילוי → עיבוד", 2),
        ("filter_seconds", "סינון", 3),
        ("duplicate_seconds", "כפילויות", 3),
        ("translation_seconds", "תרגום", 1),
        ("media_lookup_seconds", "מדיה", 1),
        ("prepare_seconds", "הכנה", 3),
    ):
        values = []
        for row in rows:
            measured = row.get("measured") if isinstance(row.get("measured"), dict) else {}
            if bool(measured.get(key, False)) and row.get(key) is not None:
                values.append(float(row.get(key) or 0.0))
        lines.append(f"• {label}: {sum(values) / len(values):.{digits}f} שנ׳ (n={len(values)})" if values else f"• {label}: לא נמדד")

    result = "\n".join(lines)
    # Stay inside one Telegram message while retaining every measured post.
    return result[:4096]


_PRE_EXACT_FINAL_PROCESS_CONTROL_UPDATE = process_control_update


def process_control_update(update: dict[str, Any]) -> None:
    callback = update.get("callback_query") or {}
    data = str(callback.get("data", "") or "")
    if data not in {"football_last_blocked", "football_facts_blocks", "football_facts_pipeline_timings"}:
        return _PRE_EXACT_FINAL_PROCESS_CONTROL_UPDATE(update)

    callback_id = str(callback.get("id", "") or "")
    message = callback.get("message", {}) or {}
    chat_id = str((message.get("chat", {}) or {}).get("id", ""))
    if CONTROL_CHAT_ID and chat_id != str(CONTROL_CHAT_ID):
        if callback_id:
            answer_control_callback(callback_id, "אין הרשאה לערוץ הזה")
        return

    if data == "football_last_blocked":
        if callback_id:
            answer_control_callback(callback_id, "מציג 20 חסימות")
        items = _twenty_recent_visible_blocks(False)
        send_control_text(
            _control_list_text(
                "📋 20 חסימות אחרונות",
                items,
                "אין חסימות של פוסטים מהשעתיים האחרונות.",
                limit=RECENT_BLOCKS_VISIBLE_LIMIT,
            ),
            message.get("message_id"),
            control_history_reply_markup() if items else monitor_menu_reply_markup(),
        )
        return

    if data == "football_facts_blocks":
        if callback_id:
            answer_control_callback(callback_id, "מציג 20 חסימות של מקורות העובדות")
        send_control_text(facts_recent_blocks_text(RECENT_BLOCKS_VISIBLE_LIMIT), message.get("message_id"), facts_monitor_reply_markup())
        return

    if callback_id:
        answer_control_callback(callback_id, "מרכז את בדיקת העיכוב בהודעה אחת")
    send_control_text(facts_pipeline_timing_report_text(10), message.get("message_id"), facts_monitor_reply_markup())

