def _working_merge_history_rows(username: str, rows: list[Post], limit: int) -> list[Post]:
    canonical = str(username or "").strip().lstrip("@")
    merged = list(rows or [])
    for loader in (
        lambda: _working_rss_cached(canonical, max(60, limit * 6)),
        lambda: _ten_history_load(canonical),
        lambda: _ten_history_collect_existing_state_posts(canonical),
    ):
        if len(merged) >= limit:
            break
        try:
            extra = list(loader() or [])
            try:
                merged = _canonical_merge(merged, extra, canonical)
            except Exception:
                merged.extend(extra)
        except Exception:
            pass
    unique: dict[str, Post] = {}
    for post in merged:
        if not isinstance(post, Post):
            continue
        key = str(post.post_id or post.link or post_content_signature(canonical, post.text, post.quoted_text) or "").strip()
        if key:
            unique.setdefault(key, post)
    ordered = sorted(
        unique.values(),
        key=lambda post: float(getattr(post, "published_ts", 0.0) or 0.0),
        reverse=True,
    )
    return ordered[:max(1, int(limit))]


