# ====== FINAL REQUESTED CLUB/LIST/PROMO/SHORT-DUPLICATE PATCH (2026-08-01) ======
# Scope is intentionally limited to outgoing text cleanup, local content gates,
# duplicate detection and atomic exact-text protection.  RSS discovery functions,
# feed templates, account cadence and persistent filenames are not modified here.

BOT_BUILD_ID = "winner-facts-area-restored-centregoals-credit-only-2026-08-01"
REQUESTED_RECENT_EVENT_WINDOW_SECONDS = int(os.environ.get(
    "REQUESTED_RECENT_EVENT_WINDOW_SECONDS", str(2 * 60 * 60)
))
REQUESTED_MIN_REPORT_WORDS = max(15, int(os.environ.get("REQUESTED_MIN_REPORT_WORDS", "15")))

# Explicit source aliases are applied before/after translation.  In addition,
# the generic prefix stripper below acts only when the Hebrew club name is a
# known display name from the existing team database, so ordinary initials or
# player names are never altered.
TEAM_REPLACEMENTS.update({
    "RC Strasbourg": "שטרסבורג",
    "Racing Club de Strasbourg": "שטרסבורג",
    "RC Strasbourg Alsace": "שטרסבורג",
    "Strasbourg Alsace": "שטרסבורג",
    "AZ Alkmaar": "אלקמאר",
    "Alkmaar Zaanstreek": "אלקמאר",
})

_REQUESTED_CLUB_PREFIXES: tuple[str, ...] = (
    "RCD", "RSC", "KRC", "LOSC", "OGC", "TSG", "VFB", "VFL",
    "AFC", "AC", "AS", "AZ", "BK", "CA", "CD", "CF", "CR", "EC",
    "FC", "FK", "IF", "IK", "NK", "RC", "RB", "SC", "SK", "SL",
    "SS", "SV", "UD", "US",
)


def _requested_known_hebrew_club_names() -> list[str]:
    names: set[str] = set()
    catalog = globals().get("TEAM_CATALOG", {})
    if isinstance(catalog, dict):
        for row in catalog.values():
            if not isinstance(row, dict):
                continue
            name = str(row.get("name") or "").strip()
            if name and re.search(r"[א-ת]", name):
                names.add(name)
    for value in TEAM_REPLACEMENTS.values():
        name = str(value or "").strip()
        if name and re.search(r"[א-ת]", name):
            names.add(name)
    names.update({"שטרסבורג", "אלקמאר", "רומא"})
    return sorted(names, key=len, reverse=True)


def _requested_normalize_club_display_names(value: Any) -> str:
    text = str(value or "")
    if not text:
        return text
    # First use the complete known alias dictionary, longest aliases first.
    for alias, replacement in sorted(TEAM_REPLACEMENTS.items(), key=lambda item: len(str(item[0])), reverse=True):
        alias_text = str(alias or "").strip()
        replacement_text = str(replacement or "").strip()
        if not alias_text or not replacement_text:
            continue
        # Hebrew short aliases such as "ריבר" -> "ריבר פלייט" can already be
        # part of the canonical display name. The established Hebrew polish layer
        # handles those aliases; this pass is only for Latin/source club names.
        if not re.search(r"[A-Za-z]", alias_text):
            continue
        text = re.sub(
            rf"(?<![A-Za-z0-9א-ת]){re.escape(alias_text)}(?![A-Za-z0-9א-ת])",
            replacement_text,
            text,
            flags=re.IGNORECASE,
        )
    club_names = _requested_known_hebrew_club_names()
    if club_names:
        prefix = "|".join(re.escape(item) for item in _REQUESTED_CLUB_PREFIXES)
        clubs = "|".join(re.escape(item) for item in club_names)
        # Supports forms such as RC שטרסבורג, AZ אלקמאר, AS רומא and
        # Hebrew prepositions attached to the Latin prefix: ל-RC שטרסבורג.
        text = re.sub(
            rf"(?iu)(?P<prep>(?<![א-ת])[בלמכהו]-?)?(?:{prefix})[.\s\-־]+(?P<club>{clubs})(?![A-Za-z0-9א-ת])",
            lambda match: (match.group("prep") or "") + match.group("club"),
            text,
        )
    text = re.sub(r"(?iu)\b(?:AS|A\.S\.)\s+רומא\b", "רומא", text)
    # Hebrew prepositions conventionally attach directly to the normalized club
    # name: ל-RC שטרסבורג -> לשטרסבורג.
    club_names = _requested_known_hebrew_club_names()
    if club_names:
        clubs = "|".join(re.escape(item) for item in club_names)
        text = re.sub(
            rf"(?iu)(?<![א-ת])(?P<prep>[בלמכהו])-+(?P<club>{clubs})(?![A-Za-z0-9א-ת])",
            lambda match: match.group("prep") + match.group("club"),
            text,
        )
    return re.sub(r"[ \t]{2,}", " ", text)


_PRE_REQUESTED_CLUB_FINAL_HEBREW_POLISH = final_hebrew_polish


def final_hebrew_polish(text: str) -> str:
    return _requested_normalize_club_display_names(_PRE_REQUESTED_CLUB_FINAL_HEBREW_POLISH(text))


_REQUESTED_HANDLE_RE = re.compile(
    r"(?<![A-Za-z0-9א-ת])@[A-Za-z0-9_א-ת][A-Za-z0-9_א-ת.'׳״\-]{0,63}",
    re.UNICODE,
)
_REQUESTED_LIST_MARKERS = ("✅", "☑️", "✔️", "🆕", "▪️", "▫️", "🔹", "🔸")
_REQUESTED_HANDSHAKE_RE = re.compile(r"(?:🤝|🫱🏻‍🫲🏼|🫱🏽‍🫲🏻|🫱🏼‍🫲🏽|🫱🏾‍🫲🏻)")


def _requested_strip_all_account_handles(value: str) -> str:
    text = _REQUESTED_HANDLE_RE.sub("", str(value or ""))
    text = re.sub(r"[ \t]{2,}", " ", text)
    text = re.sub(r"[ \t]+\n", "\n", text)
    return text.strip()


def _requested_fix_certain_list_layout(value: str) -> str:
    """Repair only structures that prove they are lists.

    1. A handshake followed by a list marker is separated only when at least two
       items with that same marker exist.
    2. A short unmarked first item receives a trailing orphan marker only when at
       least three following lines already use exactly that marker.
    """
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    for marker in _REQUESTED_LIST_MARKERS:
        if text.count(marker) < 2:
            continue
        escaped = re.escape(marker)
        # A repeated marker proves a list. Put every marked item on its own line,
        # even when the RSS mirror flattened the original Twitter line breaks.
        text = re.sub(
            rf"(?<!^)(?<!\n)[ \t]+(?={escaped}\s+\S)",
            "\n",
            text,
        )
        text = re.sub(
            rf"(?m)(?P<hand>(?:🤝|🫱🏻‍🫲🏼|🫱🏽‍🫲🏻|🫱🏼‍🫲🏽|🫱🏾‍🫲🏻))\s*(?:\n)?(?={escaped}\s+\S)",
            lambda match: match.group("hand") + "\n\n",
            text,
            count=1,
        )

    lines = text.split("\n")
    nonempty = [index for index, line in enumerate(lines) if line.strip()]
    if len(nonempty) >= 5:
        first_index = nonempty[0]
        last_index = nonempty[-1]
        first = lines[first_index].strip()
        orphan = lines[last_index].strip()
        if orphan in _REQUESTED_LIST_MARKERS and 1 <= count_regular_words(first) <= 4:
            marked_indices = [
                index for index in nonempty[1:-1]
                if lines[index].strip().startswith(orphan + " ")
            ]
            other_nonempty = [index for index in nonempty[1:-1] if index not in marked_indices]
            if len(marked_indices) >= 3 and not other_nonempty:
                lines[first_index] = f"{orphan} {first}"
                lines[last_index] = ""
                # Remove blank lines between the repaired first item and the list.
                next_marked = marked_indices[0]
                for index in range(first_index + 1, next_marked):
                    lines[index] = ""
                # This is one compact list, so the repaired first item must sit
                # directly above the remaining marked items.
                lines = lines[:first_index + 1] + lines[next_marked:last_index] + lines[last_index + 1:]
                compact: list[str] = []
                for line in lines:
                    if not line.strip() and compact and not compact[-1].strip():
                        continue
                    compact.append(line)
                lines = compact
    # Consecutive marked list items are a compact list, not separate paragraphs.
    compact_lines: list[str] = []
    for line in lines:
        if not line.strip() and compact_lines:
            previous_nonempty = next((item.strip() for item in reversed(compact_lines) if item.strip()), "")
            # Look ahead is handled by a second pass below.
            compact_lines.append(line)
            continue
        compact_lines.append(line)
    lines = compact_lines
    changed = True
    while changed:
        changed = False
        for index in range(1, len(lines) - 1):
            if lines[index].strip():
                continue
            previous = lines[index - 1].strip()
            following = lines[index + 1].strip()
            if any(previous.startswith(marker + " ") for marker in _REQUESTED_LIST_MARKERS) and any(
                following.startswith(marker + " ") for marker in _REQUESTED_LIST_MARKERS
            ):
                lines.pop(index)
                changed = True
                break
    text = "\n".join(lines)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


def _requested_writer_aliases() -> list[str]:
    aliases: set[str] = set()
    for value in ACCOUNT_DISPLAY_NAMES.values():
        if str(value or "").strip():
            aliases.add(str(value).strip())
    for values in SELF_QUOTE_ALIASES.values():
        for value in values:
            if str(value or "").strip():
                aliases.add(str(value).strip())
    for value in ATTRIBUTION_HANDLE_REPLACEMENTS.values():
        if str(value or "").strip():
            aliases.add(str(value).strip())
    return sorted(aliases, key=len, reverse=True)


def _requested_remove_detached_source_tail(value: str) -> str:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    # Handle a source credit flattened into the final sentence before inspecting
    # physical lines, because an RSS mirror may return the whole post on one line.
    for alias in (item for item in _requested_writer_aliases() if len(item) >= 4):
        inline = re.match(
            rf"(?is)^(?P<body>.*[.!?…])\s+(?P<tail>(?:[A-Z]{{1,5}}\d{{0,2}}\s+)?{re.escape(alias)}[.!?]?)\s*$",
            text,
        )
        if inline and count_regular_words(inline.group("tail")) <= 7:
            return inline.group("body").rstrip()
    lines = text.split("\n")
    while lines and not lines[-1].strip():
        lines.pop()
    if len([line for line in lines if line.strip()]) < 2:
        return text
    last_index = len(lines) - 1
    tail = lines[last_index].strip()
    body = "\n".join(lines[:last_index]).strip()
    if not body or count_regular_words(tail) > 7:
        return text
    normalized_tail = tail.rstrip(".!?… ")
    contains_writer = any(
        re.search(rf"(?<![A-Za-z0-9א-ת]){re.escape(alias)}(?![A-Za-z0-9א-ת])", normalized_tail, re.IGNORECASE)
        for alias in _requested_writer_aliases()
        if len(alias) >= 4
    )
    source_tag = bool(re.fullmatch(
        r"(?iu)(?:[A-Z]{1,5}\d{0,2}\s+)?(?:ג['׳]?אנלוקה\s+די\s+מארציו|פבריציו\s+רומאנו|"
        r"מתאו\s+מורטו|בן\s+ג['׳]?ייקובס|פלוריאן\s+פלטנברג|סקיי\s+ספורט\s+גרמניה)",
        normalized_tail,
    ))
    if contains_writer or source_tag:
        lines = lines[:last_index]
        while lines and not lines[-1].strip():
            lines.pop()
        return "\n".join(lines).strip()

    # Mirrors sometimes flatten a detached source credit into the final sentence.
    # Remove it only when the suffix contains a known reporter/source name and is
    # at most seven words after a completed sentence.
    aliases = [alias for alias in _requested_writer_aliases() if len(alias) >= 4]
    for alias in aliases:
        inline = re.match(
            rf"(?is)^(?P<body>.*[.!?…])\s+(?P<tail>(?:[A-Z]{{1,5}}\d{{0,2}}\s+)?{re.escape(alias)}[.!?]?)\s*$",
            text,
        )
        if inline and count_regular_words(inline.group("tail")) <= 7:
            return inline.group("body").rstrip()
    return text


_CENTREGOALS_DETACHED_CREDIT_LEAD_RE = re.compile(
    r"(?iu)^\s*(?:מקור|קרדיט|לפי|על\s+פי|דיווח|דווח|מדווח|כפי\s+שדווח(?:\s+לראשונה)?(?:\s+על\s+ידי)?|"
    r"source|credit|via|reported\s+by|according\s+to)\s*[:\-–—]?\s*"
)
_CENTREGOALS_DETACHED_HANDLE_RE = re.compile(
    r"@[A-Za-z0-9_א-ת][A-Za-z0-9_א-ת.'׳״\-]{0,63}",
    re.IGNORECASE | re.UNICODE,
)


def _centregoals_remove_detached_credit_line(value: str) -> str:
    """Remove only a detached attribution/credit line from CentreGoals text."""
    text = html.unescape(str(value or "")).replace("\r\n", "\n").replace("\r", "\n")
    kept: list[str] = []
    for line in text.split("\n"):
        stripped = line.strip()
        if not stripped:
            kept.append(line)
            continue
        has_handle = bool(_CENTREGOALS_DETACHED_HANDLE_RE.search(stripped))
        starts_as_credit = bool(_CENTREGOALS_DETACHED_CREDIT_LEAD_RE.match(stripped))
        bracketed_credit = bool(re.fullmatch(
            r"\s*[\[(][^\]\)]*@[A-Za-z0-9_א-ת][A-Za-z0-9_א-ת.'׳״\-]{0,63}[^\]\)]*[\])][.!]?\s*",
            stripped,
            re.IGNORECASE | re.UNICODE,
        ))
        handle_only = bool(re.fullmatch(
            r"\s*@[A-Za-z0-9_א-ת][A-Za-z0-9_א-ת.'׳״\-]{0,63}(?:\s*[,|·•/&+]\s*@[A-Za-z0-9_א-ת][A-Za-z0-9_א-ת.'׳״\-]{0,63})*[.!]?\s*",
            stripped,
            re.IGNORECASE | re.UNICODE,
        ))
        if has_handle and (starts_as_credit or bracketed_credit or handle_only):
            continue
        kept.append(line)
    result = "\n".join(kept)
    result = re.sub(r"\n{3,}", "\n\n", result)
    return result.strip()


def _requested_clean_outgoing_body(post: Post, value: str) -> str:
    if _facts_source_canonical(getattr(post, "username", "")) == CENTREGOALS_USERNAME:
        value = _centregoals_remove_detached_credit_line(value)
    text = _requested_normalize_club_display_names(value)
    text = _requested_fix_certain_list_layout(text)
    text = _requested_remove_detached_source_tail(text)
    text = _requested_strip_all_account_handles(text)
    text = re.sub(r"(?iu)(?<![א-ת])[בלמכהו][־-]\s*(?=(?:עם|ו?לפי|[,.;:!?]|$))", "", text)
    text = _requested_normalize_club_display_names(text)
    text = _requested_safe_tail_cleanup(text)
    text = _final_remove_detached_short_tail(text)
    text = _requested_remove_detached_source_tail(text)
    text = _requested_fix_certain_list_layout(text)
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


# Rebuild the active message formatter with the same writer/signature behavior,
# adding only the requested final cleanup before Telegram HTML conversion.
def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    translated = _requested_normalize_club_display_names(translated)
    body = _outgoing_body_text(post, translated, quoted=False)
    if _final_is_plettigoal(post):
        body = _FINAL_SKY_INLINE_RE.sub(" ", body)
        body = re.sub(r"[ \t]{2,}", " ", body)
    body = _requested_clean_outgoing_body(post, body)
    body = _clean_terminal_punctuation_without_touching_internal_lines(post, body)
    body = _requested_normalize_club_display_names(body) or "עדכון חדש"

    hide_writer = _is_footballfactly_post(post) or _is_optajoe_post(post) or should_hide_writer_header(post, body)
    display_name = ACCOUNT_DISPLAY_NAMES.get(post.username, post.username)
    if should_label_recycled_report(post):
        display_name = f"מיחזור של {display_name}"
    if bool(getattr(post, "fabrizio_confirmation", False)):
        display_name = "פבריציו רומאנו מאשר"
        hide_writer = False

    parts: list[str] = []
    if not hide_writer:
        parts.extend([f"<b>{html.escape(rtl(display_name + ':'), quote=False)}</b>", ""])
    parts.append(_safe_markdown_to_telegram_html(rtl(body)))
    signature = f'<a href="{html.escape(SIGNATURE_LINK, quote=True)}">{html.escape(rtl(SIGNATURE_TEXT), quote=False)}</a>'
    parts.extend(["", signature])
    return "\n".join(parts).strip()


# ---------------------------------------------------------------------------
# Local source gates: media appearances/program promos, live transfer shows and
# the requested 15-word minimum.  Existing source-specific filters run first.
# ---------------------------------------------------------------------------
_REQUESTED_MEDIA_APPEARANCE_RE = re.compile(
    r"(?iu)(?:"
    r"(?:latest\s+)?update\s+(?:on|regarding|about).{0,180}\b(?:with|for|on)\s+@[A-Za-z0-9_]+\s+(?:for|on)\s+talkSPORT|"
    r"\bwith\s+(?:ben\s+jacobs|fabrizio\s+romano|florian\s+plettenberg).{0,80}\b(?:for|on)\s+talkSPORT|"
    r"\b(?:podcast|full\s+episode|new\s+episode|listen\s+now|watch\s+the\s+full\s+show)\b|"
    r"(?:עדכון|העדכון\s+האחרון).{0,160}(?:עם|עבור).{0,80}(?:talkSPORT|טוקספורט)|"
    r"פודקאסט|פרק\s+מלא|התוכנית\s+המלאה"
    r")"
)
_REQUESTED_LIVE_PROGRAM_RE = re.compile(
    r"(?iu)(?:"
    r"\btransfer\s+update\b.{0,160}\b(?:show|programme|program|live|sky)\b|"
    r"\b(?:live\s+show|live\s+programme|live\s+program|on\s+air)\b|"
    r"(?:היום\s+בשעה\s+\d{1,2}:\d{2}.{0,120})?(?:עדכון\s+העברות|תוכנית\s+העברות).{0,160}(?:שידור\s+חי|לייב|בסְקיי|בסקיי)|"
    r"התוכנית.{0,100}(?:בשידור\s+חי|לייב)"
    r")"
)


def _requested_clean_source_for_word_count(post: Post) -> str:
    source = _requested_source_text(post) if "_requested_source_text" in globals() else _final_source_text(post)
    source = html.unescape(str(source or ""))
    source = URL_RE.sub(" ", source)
    source = BARE_EXTERNAL_DOMAIN_RE.sub(" ", source)
    source = _REQUESTED_HANDLE_RE.sub(" ", source)
    source = re.sub(r"\s+", " ", source).strip()
    return source


_PRE_REQUESTED_CONTENT_BLOCK = pre_send_final_local_block_reason


def pre_send_final_local_block_reason(post: Post) -> str:
    source = html.unescape(str(
        _requested_source_text(post) if "_requested_source_text" in globals() else _final_source_text(post)
    ))
    # Promotional/live-program detection is deliberately evaluated before club
    # routing so a show advertisement is explained as a show advertisement.
    if _REQUESTED_MEDIA_APPEARANCE_RE.search(source):
        return "media_appearance_or_podcast_promo"
    if _REQUESTED_LIVE_PROGRAM_RE.search(source):
        return "live_transfer_program_promo"
    # Dedicated facts sources retain their existing per-source minimum wording.
    explicit_hwg = bool(
        callable(globals().get("_requested_has_explicit_fabrizio_hwg"))
        and _requested_has_explicit_fabrizio_hwg(post)
    )
    if not _is_facts_source(post) and not explicit_hwg and count_regular_words(_requested_clean_source_for_word_count(post)) < REQUESTED_MIN_REPORT_WORDS:
        return "report_under_15_words"
    existing = _PRE_REQUESTED_CONTENT_BLOCK(post)
    if existing:
        return existing
    return ""


_PRE_REQUESTED_CONTENT_REASON = hebrew_block_reason


def hebrew_block_reason(reason: str) -> str:
    raw = str(reason or "")
    if "media_appearance_or_podcast_promo" in raw:
        return "הופעה בתוכנית, פודקאסט או קידום תוכן תקשורתי — לא דיווח כדורגל עצמאי"
    if "live_transfer_program_promo" in raw:
        return "פרסום לתוכנית העברות או לשידור חי — לא דיווח העברה"
    if "report_under_15_words" in raw:
        return f"הדיווח קצר מדי: פחות מ-{REQUESTED_MIN_REPORT_WORDS} מילים רגילות"
    if "requested_recent_same_event_duplicate" in raw:
        return "אותו שחקן, אותן קבוצות ואותו מצב כבר דווחו בשעתיים האחרונות ללא פרט ממשי חדש"
    if "requested_exact_text_duplicate" in raw:
        return "אותה הודעה כבר נשלחה או נמצאת כעת בתהליך שליחה"
    return _PRE_REQUESTED_CONTENT_REASON(reason)


# ---------------------------------------------------------------------------
# Two-hour event duplicate layer.  Reporter priority never overrides a duplicate;
# only an explicit Fabrizio HERE WE GO bypasses semantic event dedupe.  Exact post
# identity/text remains blocked even for HERE WE GO.
# ---------------------------------------------------------------------------
_REQUESTED_EVENT_GENERIC_ENTITIES = {
    "agreement", "agreed", "deal", "transfer", "move", "sign", "signed", "signs",
    "contract", "new", "summer", "until", "valid", "medical", "medicals", "talks",
    "offer", "bid", "club", "player", "team", "personal", "terms", "official",
    "אגרימהנט", "הסכם", "עסקה", "העברה", "חוזה", "רפואיות", "שיחות", "הצעה",
    "חדש", "חתם", "חותם", "רשמי", "קבוצה", "שחקן", "תנאים",
}
_REQUESTED_EVENT_FAMILY_PATTERNS: tuple[tuple[str, re.Pattern[str]], ...] = (
    ("contract", re.compile(r"(?iu)\b(?:new\s+contract|contract\s+extension|renewal|new\s+deal)\b|חוזה\s+חדש|הארכת\s+חוזה|חידוש\s+חוזה")),
    ("coach", re.compile(r"(?iu)\b(?:coach|manager|head\s+coach|technical\s+director)\b|מאמן|מנהל\s+טכני|מנהל\s+מקצועי")),
    ("transfer", re.compile(r"(?iu)\b(?:transfer|move|join|sign|bid|offer|talks|interest|medical|deal)\b|העברה|מעבר|יצטרף|יחתום|הצעה|שיחות|עניין|בדיקות\s+רפואיות|עסקה")),
)


def _requested_has_explicit_fabrizio_hwg(post: Post) -> bool:
    username = str(getattr(post, "username", "") or "").strip().lstrip("@").casefold()
    if username != "fabrizioromano":
        return False
    source = _final_source_text(post)
    return bool(re.search(r"(?i)#?HERE(?:_|\s)+WE(?:_|\s)+GO\b", str(source or "")))


def _requested_event_text_from_item(item: dict[str, Any]) -> str:
    for key in ("source_text", "original_text", "full_text", "text", "rendered", "message", "normalized_message"):
        value = str(item.get(key) or "").strip()
        if value:
            return html_message_to_plain_text(value) if "html_message_to_plain_text" in globals() else value
    try:
        return str(_final_duplicate_item_text(item) or "")
    except Exception:
        return ""


def _requested_event_signature_for_item(item: dict[str, Any], text: str) -> dict[str, Any]:
    for key in ("event_signature", "signature"):
        value = item.get(key)
        if isinstance(value, dict) and value:
            return value
    return _final_signature_from_text(text, str(item.get("username") or "memory"))


def _requested_signature_teams(signature: dict[str, Any]) -> set[str]:
    result = {
        str(entity).casefold() for entity in signature.get("entities", [])
        if str(entity).casefold().startswith("team:")
    }
    # Hebrew curly apostrophes sometimes prevent the older signature builder from
    # recognizing צ׳לסי/פ.ס.ז׳. Re-run the existing team catalog matcher on a
    # punctuation-normalized copy of the signature text.
    signature_text = str(signature.get("text") or "").replace("׳", "'").replace("’", "'").replace("`", "'")
    try:
        for team in _final_logical_team_ids(signature_text):
            result.add("team:" + str(team).casefold())
    except Exception:
        pass
    return result


def _requested_signature_subjects(signature: dict[str, Any]) -> set[str]:
    result: set[str] = set()
    # Entities are preferred, but the existing signature intentionally excludes
    # some unknown player names. Tokens restore those names (e.g. דני וולבק) while
    # the stopword list below removes transaction wording.
    raw_values = list(signature.get("entities", [])) + list(signature.get("tokens", []))
    generic = set(_REQUESTED_EVENT_GENERIC_ENTITIES) | {
        "קרובה", "מתקרבת", "השלמת", "עסקת", "עסקה", "לאחר", "פריצת", "דרך",
        "שיחות", "משא", "ומתן", "מתקדמ", "מתקדם", "שלבים", "שלבימ", "סופיים",
        "סופיימ", "תנאיו", "רייטונ", "צלסי", "נוטינגהאמ", "פורסט",
        "close", "completing", "breakthrough", "expected", "opening", "submit",
        "prepare", "wants", "financial", "place", "permission", "undergo",
    }
    for raw in raw_values:
        token = str(raw or "").strip().casefold()
        if not token or token.startswith("team:") or token in generic:
            continue
        if len(token) < 3 or token.isdigit():
            continue
        if token in globals().get("_FINAL_EVENT_IDENTITY_STOPWORDS", set()):
            continue
        result.add(token)
    return result


def _requested_event_family(text: str, signature: dict[str, Any]) -> str:
    for name, pattern in _REQUESTED_EVENT_FAMILY_PATTERNS:
        if pattern.search(str(text or "")):
            return name
    actions = " ".join(str(value) for value in signature.get("actions", []))
    if "contract" in actions:
        return "contract"
    if any(value in actions for value in ("transfer", "deal", "bid", "signed", "signs")):
        return "transfer"
    return ""


def _requested_word_number(value: str) -> int | None:
    words = {
        "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
        "שנה": 1, "שנתיים": 2, "שלוש": 3, "ארבע": 4, "חמש": 5,
    }
    return words.get(str(value or "").casefold())


def _requested_material_facts(text: str) -> set[str]:
    raw = html.unescape(str(text or ""))
    normalized = unicodedata.normalize("NFKC", raw).casefold()
    facts: set[str] = set()
    # Exact monetary facts only; ordinary ages, dates and shirt numbers do not
    # make a repeated report new.
    money_patterns = (
        r"(?:€|£|\$)\s*\d+(?:[.,]\d+)?\s*(?:m|mn|million|bn|billion)?",
        r"\d+(?:[.,]\d+)?\s*(?:m|mn|million|מיליון|bn|billion|מיליארד)\s*(?:euros?|euro|אירו|pounds?|פאונד|dollars?|דולר)",
    )
    for pattern in money_patterns:
        for match in re.findall(pattern, normalized, re.IGNORECASE):
            facts.add("fee:" + re.sub(r"\s+", "", str(match)))
    if re.search(r"(?iu)\b(?:salary|wage|per\s+week|per\s+year)\b|שכר|לשבוע|לעונה", raw):
        for number in re.findall(r"(?:€|£|\$)?\s*\d+(?:[.,]\d+)?\s*(?:k|m|אלף|מיליון)?", normalized):
            if re.search(r"\d", number):
                facts.add("salary:" + re.sub(r"\s+", "", number))
    for year in re.findall(r"(?iu)(?:until|through|valid\s+until|עד|בתוקף\s+עד)\s+(?:june\s+|summer\s+|יוני\s+|קיץ\s+)?(20\d{2})", normalized):
        facts.add("contract_end:" + year)
        try:
            duration = int(year) - datetime.now(ZoneInfo(SHABBAT_TIMEZONE)).year
            if 1 <= duration <= 8:
                facts.add(f"contract_duration:{duration}")
        except Exception:
            pass
    duration_re = re.compile(r"(?iu)\b(one|two|three|four|five|\d+)\s*[- ]?year\s+(?:deal|contract)|חוזה\s+ל(?:משך\s+)?(שנה|שנתיים|שלוש|ארבע|חמש|\d+)\s*שנים?")
    for match in duration_re.finditer(normalized):
        token = next((group for group in match.groups() if group), "")
        number = int(token) if str(token).isdigit() else _requested_word_number(token)
        if number:
            facts.add(f"contract_duration:{number}")
    if re.search(r"(?iu)#?HERE(?:_|\s)+WE(?:_|\s)+GO\b", raw):
        facts.add("here_we_go")
    if re.search(r"(?iu)\b(?:deal\s+done|done\s+deal|full\s+agreement|agreement\s+reached|deal\s+agreed)\b|עסקה\s+סגורה|הסכם\s+מלא|הושג\s+סיכום|העסקה\s+סוכמה", raw):
        facts.add("deal_done")
    if re.search(r"(?iu)\b(?:has\s+signed|have\s+signed|signs\s+for|completed\s+(?:the\s+)?(?:move|transfer)|joins?\s+officially)\b|חתם|חתמה|חתמו|הצטרף\s+רשמית|הושלמה\s+ההעברה", raw):
        facts.add("signed_or_completed")
    if re.search(r"(?iu)\b(?:medical(?:s)?\s+(?:booked|scheduled|approved)|green\s+light\s+for\s+medicals?|permission\s+to\s+undergo.{0,30}medicals?)\b|בדיקות\s+רפואיות\s+(?:נקבעו|אושרו)|אור\s+ירוק\s+לבדיקות|אישור\s+לעבור\s+בדיקות", raw):
        facts.add("medical:approved")
    if re.search(r"(?iu)\b(?:formal\s+bid|official\s+bid|bid\s+submitted|offer\s+submitted)\b|הוגשה\s+הצעה|הצעה\s+רשמית", raw) and not re.search(r"(?iu)\b(?:expected|prepare|preparing|considering|may|could)\b|צפוי|מכינה|שוקלת|עשויה", raw):
        facts.add("formal_bid:submitted")
    if re.search(r"(?iu)\b(?:bid|offer)\s+(?:accepted|rejected)\b|ההצעה\s+(?:התקבלה|נדחתה)", raw):
        facts.add("bid_decision")
    if re.search(r"(?iu)\b(?:official|confirmed)\b|רשמי|אושר", raw):
        facts.add("official")
    if re.search(r"(?iu)\b(?:cancelled|canceled|called\s+off|withdrawn|deal\s+off)\b|בוטל|ירדה\s+מהפרק|נמשכה\s+ההצעה", raw):
        facts.add("cancelled")
    if re.search(r"(?iu)\b(?:willing|open|ready)\s+to\s+sell\b|מוכנה\s+למכור|פתוחה\s+למכירה", raw):
        facts.add("willing_to_sell")
    if re.search(r"(?iu)\b(?:clubs?\s+(?:made|have\s+made)\s+(?:enquiries|inquiries)|enquiries\s+received)\b|מועדונים\s+(?:ביצעו|עשו)\s+בירורים", raw):
        facts.add("enquiries")
    if re.search(r"(?iu)\bpersonal\s+terms\s+agreed\b|סוכמו\s+התנאים\s+האישיים|סיכם\s+את\s+תנאיו", raw):
        facts.add("personal_terms")
    return facts


def _requested_recent_sent_items() -> list[dict[str, Any]]:
    try:
        rows = load_json_list_file(persistent_memory_path("football_sent_memory.json"))
    except Exception:
        rows = []
    now = time.time()
    result: list[dict[str, Any]] = []
    for item in rows[-1200:]:
        if not isinstance(item, dict):
            continue
        try:
            timestamp = float(item.get("ts") or item.get("sent_at") or item.get("original_published_ts") or item.get("published_ts") or 0.0)
        except Exception:
            timestamp = 0.0
        if timestamp and now - timestamp <= REQUESTED_RECENT_EVENT_WINDOW_SECONDS:
            result.append(item)
    return result


def _requested_same_subject_event(
    current_signature: dict[str, Any],
    current_family: str,
    previous_signature: dict[str, Any],
    previous_family: str,
) -> bool:
    if current_family and previous_family and current_family != previous_family:
        return False
    current_teams = _requested_signature_teams(current_signature)
    previous_teams = _requested_signature_teams(previous_signature)
    current_subjects = _requested_signature_subjects(current_signature)
    previous_subjects = _requested_signature_subjects(previous_signature)
    team_overlap = current_teams & previous_teams
    subject_overlap = current_subjects & previous_subjects
    return bool(
        (len(subject_overlap) >= 2 and len(team_overlap) >= 1)
        or (len(subject_overlap) >= 4)
        or (len(team_overlap) >= 2 and len(subject_overlap) >= 1)
    )


def _requested_recent_same_event_duplicate(post: Post) -> dict[str, Any] | None:
    if _requested_has_explicit_fabrizio_hwg(post):
        return None
    current_text = _final_source_text(post)
    current_signature = news_event_signature(post)
    current_family = _requested_event_family(current_text, current_signature)
    if not current_family:
        return None
    current_facts = _requested_material_facts(current_text)
    matched: list[tuple[dict[str, Any], str, dict[str, Any]]] = []
    previous_facts: set[str] = set()
    previous_teams: set[str] = set()
    for item in reversed(_requested_recent_sent_items()):
        previous_text = _requested_event_text_from_item(item)
        if not previous_text:
            continue
        previous_signature = _requested_event_signature_for_item(item, previous_text)
        previous_family = _requested_event_family(previous_text, previous_signature)
        if not _requested_same_subject_event(current_signature, current_family, previous_signature, previous_family):
            continue
        matched.append((item, previous_text, previous_signature))
        previous_facts.update(_requested_material_facts(previous_text))
        previous_teams.update(_requested_signature_teams(previous_signature))
    if not matched:
        return None
    current_teams = _requested_signature_teams(current_signature)
    if current_teams - previous_teams:
        return None
    # Only a concrete requested fact makes a repeated short-window event new.
    # Generic wording such as "still interested", "talks continue", "close" or
    # "expected to bid" does not qualify.
    new_facts = current_facts - previous_facts
    if new_facts:
        return None
    candidate = dict(matched[0][0])
    candidate.update({
        "duplicate": True,
        "is_duplicate": True,
        "duplicate_verdict": "SAME_EVENT_NO_NEW_FACT",
        "duplicate_source": str(candidate.get("username") or candidate.get("source") or "דיווח קודם"),
        "reason": "requested_recent_same_event_duplicate",
        "raw_reason": "requested_recent_same_event_duplicate",
        "requested_current_facts": sorted(current_facts),
        "requested_previous_facts": sorted(previous_facts),
    })
    return candidate


_PRE_REQUESTED_EVENT_FIND_RECENT = find_recent_duplicate_event
_PRE_REQUESTED_EVENT_FIND_CHANNEL = find_channel_duplicate_event
_PRE_REQUESTED_EVENT_FIND_TRANSLATED = find_post_translation_duplicate_event


def find_recent_duplicate_event(post: Post, state: dict[str, Any]) -> dict[str, Any] | None:
    candidate = _requested_recent_same_event_duplicate(post)
    if candidate:
        return candidate
    return _PRE_REQUESTED_EVENT_FIND_RECENT(post, state)


def find_channel_duplicate_event(post: Post, state: dict[str, Any]) -> dict[str, Any] | None:
    candidate = _requested_recent_same_event_duplicate(post)
    if candidate:
        return candidate
    return _PRE_REQUESTED_EVENT_FIND_CHANNEL(post, state)


def find_post_translation_duplicate_event(post: Post, translated_message: str, state: dict[str, Any]) -> dict[str, Any] | None:
    candidate = _requested_recent_same_event_duplicate(post)
    if candidate:
        return candidate
    return _PRE_REQUESTED_EVENT_FIND_TRANSLATED(post, translated_message, state)


# Exact source-text reservation closes the remaining race where the same content
# arrives from two automatic discovery paths with different mirror IDs.
_REQUESTED_EXACT_TEXT_LOCK = RLock()
_REQUESTED_EXACT_TEXT_INFLIGHT: dict[str, float] = {}
_REQUESTED_EXACT_TEXT_SENT: dict[str, float] = {}


def _requested_exact_text_fingerprint(post: Post) -> str:
    text = _final_repost_normalize(_final_source_text(post))
    username = str(getattr(post, "username", "") or "").strip().lstrip("@").casefold()
    return hashlib.sha256((username + "\n" + text).encode("utf-8", errors="ignore")).hexdigest() if text else ""


def _requested_exact_text_already_in_memory(post: Post, fingerprint: str) -> bool:
    if not fingerprint:
        return False
    now = time.time()
    try:
        rows = load_json_list_file(persistent_memory_path("football_sent_memory.json"))[-1200:]
    except Exception:
        rows = []
    username = str(getattr(post, "username", "") or "").strip().lstrip("@").casefold()
    for item in reversed(rows):
        if not isinstance(item, dict):
            continue
        try:
            timestamp = float(item.get("ts") or item.get("sent_at") or 0.0)
        except Exception:
            timestamp = 0.0
        if timestamp and now - timestamp > 48 * 60 * 60:
            continue
        previous_username = str(item.get("username") or item.get("source") or "").strip().lstrip("@").casefold()
        if previous_username and username and previous_username != username:
            continue
        previous_text = str(item.get("source_text") or item.get("original_text") or item.get("text") or "")
        previous_normalized = _final_repost_normalize(previous_text)
        if previous_normalized:
            previous_fingerprint = hashlib.sha256((username + "\n" + previous_normalized).encode("utf-8", errors="ignore")).hexdigest()
            if previous_fingerprint == fingerprint:
                return True
    return False


_PRE_REQUESTED_EXACT_SEND_POST = send_post


def send_post(post: Post, reply_message_ids: dict[str, int] | None = None, state: dict[str, Any] | None = None) -> dict[str, Any]:
    fingerprint = _requested_exact_text_fingerprint(post)
    now = time.time()
    if fingerprint:
        with _REQUESTED_EXACT_TEXT_LOCK:
            for mapping in (_REQUESTED_EXACT_TEXT_INFLIGHT, _REQUESTED_EXACT_TEXT_SENT):
                for key, timestamp in list(mapping.items()):
                    if now - timestamp > 48 * 60 * 60:
                        mapping.pop(key, None)
            if fingerprint in _REQUESTED_EXACT_TEXT_INFLIGHT or fingerprint in _REQUESTED_EXACT_TEXT_SENT:
                return {"sent": False, "mode": "pre_send_blocked:requested_exact_text_duplicate", "total_seconds": 0.0}
            if _requested_exact_text_already_in_memory(post, fingerprint):
                _REQUESTED_EXACT_TEXT_SENT[fingerprint] = now
                return {"sent": False, "mode": "pre_send_blocked:requested_exact_text_duplicate", "total_seconds": 0.0}
            _REQUESTED_EXACT_TEXT_INFLIGHT[fingerprint] = now
    result: dict[str, Any] | None = None
    try:
        result = _PRE_REQUESTED_EXACT_SEND_POST(post, reply_message_ids=reply_message_ids, state=state)
        return result
    finally:
        if fingerprint:
            with _REQUESTED_EXACT_TEXT_LOCK:
                _REQUESTED_EXACT_TEXT_INFLIGHT.pop(fingerprint, None)
                if isinstance(result, dict) and bool(result.get("sent")):
                    _REQUESTED_EXACT_TEXT_SENT[fingerprint] = time.time()

# ====== END FINAL REQUESTED CLUB/LIST/PROMO/SHORT-DUPLICATE PATCH ======


# ====== FINAL ALL CONTROL RESULTS IN NEW MESSAGES PATCH (2026-08-01) ======
# Every report, diagnostic, statistic, history/list output and help text is sent
# as a brand-new control-chat message. Menu navigation and setting toggles may
# still edit the existing menu, so the operator never loses the keyboard.
# RSS fetching, scanning cadence, filters and persistent state are untouched.

BOT_BUILD_ID = "winner-all-control-results-new-message-2026-08-01"
CONTROL_RESULTS_ALWAYS_NEW_MESSAGE = True

_PRE_ALL_NEW_RESULTS_PROCESS_CONTROL_UPDATE = process_control_update


def _all_new_results_authorized(message: dict[str, Any]) -> bool:
    chat_id = str((message.get("chat", {}) or {}).get("id", ""))
    return not CONTROL_CHAT_ID or chat_id == str(CONTROL_CHAT_ID)


def _all_new_results_submit(callback_id: str, acknowledgement: str, compute_fn, reply_markup: dict[str, Any] | None = None) -> None:
    """Acknowledge immediately and send every result in a fresh message."""
    if callback_id:
        answer_control_callback(callback_id, acknowledgement)

    def _worker() -> None:
        try:
            result = compute_fn()
            if isinstance(result, (list, tuple)):
                parts = [str(item) for item in result if str(item).strip()]
            else:
                value = str(result or "").strip()
                parts = [value] if value else []
            if not parts:
                parts = ["לא נמצאו נתונים להצגה."]
            markup = reply_markup if reply_markup is not None else control_delete_message_reply_markup()
            for part in parts:
                send_control_text_full(part, markup)
        except Exception as exc:
            try:
                send_control_text(
                    "הפעולה נכשלה:\n" + short_error(exc, 900),
                    None,
                    control_delete_message_reply_markup(),
                )
            except Exception:
                logging.exception("Could not send fresh control-result error")

    try:
        _CONTROL_BUTTON_EXECUTOR.submit(_worker)
    except Exception:
        Thread(target=_worker, daemon=True).start()


def _all_new_results_pipeline_text() -> str:
    result = pipeline_timing_report_parts(10)
    if isinstance(result, (list, tuple)):
        return "\n\n".join(str(item) for item in result if str(item).strip())
    return str(result or "")


def _all_new_results_team_list(data: str) -> str:
    return team_tier_list_text(data.split(":", 1)[1])


def _all_new_results_team_help(data: str) -> str:
    return teams_help_text(data.split(":", 1)[1])


def _all_new_results_category_help(data: str) -> str:
    return category_help_text(data.split(":", 1)[1])


def process_control_update(update: dict[str, Any]) -> None:
    callback = update.get("callback_query") or {}
    if not callback:
        return _PRE_ALL_NEW_RESULTS_PROCESS_CONTROL_UPDATE(update)

    data = str(callback.get("data", "") or "")
    callback_id = str(callback.get("id", "") or "")
    message = callback.get("message", {}) or {}
    if not _all_new_results_authorized(message):
        if callback_id:
            answer_control_callback(callback_id, "אין הרשאה לערוץ הזה")
        return

    # Results and reports that must never replace/edit the menu message.
    fixed_actions: dict[str, tuple[str, Any]] = {
        "football_persistence_guide": ("מציג מדריך שמירת זיכרון", persistent_memory_guide_text),
        "football_check_all_accounts_now": ("בודק את כל הכתבים", check_all_accounts_now_text),
        "football_active_accounts_status": ("מציג כתבים פעילים", active_accounts_status_text),
        "football_rss_status": ("בודק RSS", rss_status_text),
        "football_gemini_status": ("בודק Gemini", gemini_status_text),
        "football_system_health": ("בודק חיבורים", system_health_text),
        "football_gemini_toggle_quota_guard": ("מעדכן הגנת Gemini", gemini_toggle_quota_guard),
        "football_gemini_clear_local_cooldown": ("משחרר קירור מקומי", gemini_clear_local_cooldowns),
        "football_last_sent_post": ("מציג פוסט אחרון", last_sent_post_text),
        "football_daily_report_now": ("מכין סיכום יום", build_daily_quality_report_text),
        "football_last_blocked": ("מציג 20 חסימות", _final_recent_block_report),
        "football_blocked_summary": ("מכין סיכום חסימות", last_blocked_summary_text),
        "football_last_duplicate": ("מציג 10 כפילויות", _final_recent_duplicate_report),
        "football_pipeline_timings": ("מציג בדיקת עיכוב", _all_new_results_pipeline_text),
        "football_buttons_help": ("מציג הסבר כפתורים", control_buttons_help_text),
        "football_facts_stats": ("מציג סטטיסטיקות עובדות", facts_stats_text),
        "football_facts_rules": ("מציג כללים וחסימות", special_sources_diagnostics_text),
        "football_facts_rss": ("בודק RSS של מקורות העובדות", facts_rss_status_text),
        "football_facts_check_all": ("בודק את כל מקורות העובדות", facts_check_all_text),
        "football_special_sources_diagnostics": ("מכין אבחון מקורות עובדות", special_sources_diagnostics_text),
        "football_facts_blocks": ("מציג חסימות של מקורות העובדות", lambda: facts_recent_blocks_text(RECENT_BLOCKS_VISIBLE_LIMIT)),
        "football_facts_pipeline_timings": ("מציג בדיקת עיכוב של העובדות", lambda: facts_pipeline_timing_report_text(10)),
    }
    action = fixed_actions.get(data)
    if action:
        acknowledgement, compute_fn = action
        _all_new_results_submit(callback_id, acknowledgement, compute_fn)
        return

    if data.startswith("football_stat_"):
        kind = data.replace("football_stat_", "", 1)
        _all_new_results_submit(callback_id, "מציג נתון", lambda: simple_stat_text(kind))
        return

    if data.startswith("football_teams_list:"):
        _all_new_results_submit(callback_id, "מציג רשימה", lambda: _all_new_results_team_list(data))
        return

    if data.startswith("football_teams_help:"):
        _all_new_results_submit(callback_id, "מציג הסבר", lambda: _all_new_results_team_help(data))
        return

    if data.startswith("football_category_help:"):
        _all_new_results_submit(callback_id, "מציג הסבר קטגוריה", lambda: _all_new_results_category_help(data))
        return

    # Writer/source latest and history handlers already create a new loading
    # message and replace only that new message with the final result.
    return _PRE_ALL_NEW_RESULTS_PROCESS_CONTROL_UPDATE(update)


