# ====== FINAL UNTRANSLATED / SOURCE-ONLY HERE-WE-GO / PUNCTUATION PATCH (2026-08-02) ======
# Scope is deliberately narrow:
# - reject a Gemini result that is still substantially the original English text;
# - never show HERE WE GO unless it exists explicitly in the corresponding source;
# - remove punctuation collisions such as ",!".
# Exact source line/paragraph reconstruction is not changed here.

_FINAL_EXPLICIT_HWG_RE = re.compile(r"(?iu)#?HERE(?:_|\s)+WE(?:_|\s)+GO\b")
_FINAL_UNAUTHORIZED_HWG_VARIANTS_RE = re.compile(
    r"(?iu)(?:#?HERE(?:_|\s)+WE(?:_|\s)+GO\b|היר\s+וי\s+גו|הנה\s+זה\s+קורה|כאן\s+אנחנו\s+הולכים)"
)
_FINAL_ENGLISH_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'’\-]{2,}")


def _final_corresponding_source_text(post: Post, quoted: bool = False) -> str:
    if quoted:
        value = str(getattr(post, "quoted_text", "") or "")
    else:
        value = str(getattr(post, "original_text", "") or getattr(post, "text", "") or "")
        if not value:
            try:
                value = str(_post_original_text(post, quoted=False) or "")
            except Exception:
                value = str(getattr(post, "text", "") or "")
    return html.unescape(value).replace("\r\n", "\n").replace("\r", "\n")


def _final_translation_is_still_english(source: str, translated: str) -> bool:
    """Return True only for a clear untranslated/near-copy result.

    Proper names and club acronyms may remain in Latin. The result is rejected
    only when the source is substantially English and the output still contains
    most of the same English wording with too little Hebrew translation.
    """
    src = clean_before_translation(strip_google_translate_markers(str(source or "")))
    out = clean_before_translation(strip_google_translate_markers(str(translated or "")))
    src = re.sub(r"⟪LB\d{4}⟫", " ", src)
    out = re.sub(r"⟪LB\d{4}⟫", " ", out)
    src_latin = len(re.findall(r"[A-Za-z]", src))
    if src_latin < 45:
        return False
    out_latin = len(re.findall(r"[A-Za-z]", out))
    out_hebrew = len(re.findall(r"[א-ת]", out))
    src_tokens = [token.casefold().replace("’", "'") for token in _FINAL_ENGLISH_TOKEN_RE.findall(src)]
    out_tokens = [token.casefold().replace("’", "'") for token in _FINAL_ENGLISH_TOKEN_RE.findall(out)]
    if not src_tokens or not out_tokens:
        return out_hebrew < 10 and out_latin >= 35
    src_set = set(src_tokens)
    shared = sum(1 for token in out_tokens if token in src_set)
    shared_ratio = shared / max(1, len(out_tokens))
    source_coverage = len(src_set.intersection(out_tokens)) / max(1, len(src_set))
    normalized_src = re.sub(r"\s+", " ", src).strip().casefold()
    normalized_out = re.sub(r"\s+", " ", out).strip().casefold()
    similarity = SequenceMatcher(None, normalized_src, normalized_out).ratio()
    # A clear near-copy, or a body dominated by the same source-language words.
    if similarity >= 0.72 and out_hebrew < max(18, int(out_latin * 0.30)):
        return True
    if out_latin >= 45 and out_latin > out_hebrew * 1.35 and shared_ratio >= 0.60 and source_coverage >= 0.45:
        return True
    return False


def _final_clear_untranslated_cache(post: Post, include_quote: bool) -> None:
    clearer = globals().get("_final_clear_translation_cache_for_post")
    if callable(clearer):
        try:
            clearer(post, include_quote)
        except Exception:
            pass


_PRE_FINAL_UNTRANSLATED_GEMINI_TRANSLATE_POST_ONCE = gemini_translate_post_once


def gemini_translate_post_once(post: Post, include_quote: bool) -> tuple[str, str, str]:
    main_text, quote_text, author_text = _PRE_FINAL_UNTRANSLATED_GEMINI_TRANSLATE_POST_ONCE(post, include_quote)
    main_source = _final_corresponding_source_text(post, quoted=False)
    if _final_translation_is_still_english(main_source, main_text):
        _final_clear_untranslated_cache(post, include_quote)
        raise TranslationUnavailable("Gemini returned the original English text instead of a Hebrew translation")
    if include_quote and quote_text:
        quote_source = _final_corresponding_source_text(post, quoted=True)
        if _final_translation_is_still_english(quote_source, quote_text):
            _final_clear_untranslated_cache(post, include_quote)
            raise TranslationUnavailable("Gemini left the quoted post untranslated")
    return main_text, quote_text, author_text


def _final_remove_unauthorized_here_we_go(value: str, source: str) -> str:
    text = str(value or "")
    if _FINAL_EXPLICIT_HWG_RE.search(str(source or "")):
        return text
    # Remove only the unauthorized phrase; do not restructure source lines.
    text = _FINAL_UNAUTHORIZED_HWG_VARIANTS_RE.sub("", text)
    text = re.sub(r"[ \t]+([,.;:!?])", r"\1", text)
    text = re.sub(r"([,;:])\s*([!?])", r"\2", text)
    text = re.sub(r"[ \t]{2,}", " ", text)
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    return text.strip()


def _final_fix_punctuation_collisions_in_message(value: str) -> str:
    text = str(value or "")
    # Examples: ויאריאל,! -> ויאריאל! ; ויאריאל, ! -> ויאריאל!
    text = re.sub(r"[,;:]\s*([!?])", r"\1", text)
    text = re.sub(r"([!?])\s*[,;:]+", r"\1", text)
    return text


_PRE_FINAL_SOURCE_ONLY_HWG_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    translated = _final_remove_unauthorized_here_we_go(
        translated, _final_corresponding_source_text(post, quoted=False)
    )
    if quoted_translated:
        quoted_translated = _final_remove_unauthorized_here_we_go(
            quoted_translated, _final_corresponding_source_text(post, quoted=True)
        )
    message = _PRE_FINAL_SOURCE_ONLY_HWG_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    # Older body formatters may reinsert the phrase. Enforce the source rule once
    # more on the final rendered message, without changing any line separators.
    combined_source = _final_corresponding_source_text(post, quoted=False)
    if quoted_translated:
        combined_source += "\n" + _final_corresponding_source_text(post, quoted=True)
    message = _final_remove_unauthorized_here_we_go(message, combined_source)
    return _final_fix_punctuation_collisions_in_message(message)

# ====== END FINAL UNTRANSLATED / SOURCE-ONLY HERE-WE-GO / PUNCTUATION PATCH ======


# Manual/quiet preparation may use its established Google fallback after a
# Gemini exception. Validate that final fallback result as part of each one of
# the existing four attempts, so an unchanged English source is never accepted.
_PRE_FINAL_UNTRANSLATED_MANUAL_SINGLE_ATTEMPT = _PRE_FOUR_RETRY_MANUAL_TRANSLATION


def _final_validated_manual_single_attempt(post: Post) -> tuple[str, str, str]:
    main_text, quote_text, author_text = _PRE_FINAL_UNTRANSLATED_MANUAL_SINGLE_ATTEMPT(post)
    main_source = _final_corresponding_source_text(post, quoted=False)
    if _final_translation_is_still_english(main_source, main_text):
        _final_clear_untranslated_cache(post, bool(getattr(post, "quoted_text", "")))
        raise TranslationUnavailable("Manual preparation returned untranslated English text")
    if quote_text:
        quote_source = _final_corresponding_source_text(post, quoted=True)
        if _final_translation_is_still_english(quote_source, quote_text):
            _final_clear_untranslated_cache(post, True)
            raise TranslationUnavailable("Manual preparation left the quoted post untranslated")
    return main_text, quote_text, author_text


# The active four-attempt manual_force_translation resolves this global on every
# iteration; replacing only the single-attempt callable preserves its 0/+150s
# retry schedule and all existing control-button behavior.
_PRE_FOUR_RETRY_MANUAL_TRANSLATION = _final_validated_manual_single_attempt



# ====== FINAL SINGLE CONTROL PANEL / NO DUPLICATE KEYBOARDS FIX (2026-08-02) ======
# Keep exactly one persistent management panel:
# - startup edits/reuses the saved panel instead of forcing a fresh keyboard;
# - navigation continues to edit the clicked panel;
# - result messages never receive the full navigation keyboard, only Delete.
# This patch does not touch RSS, filters, translations, source lists or memory files.

BOT_BUILD_ID = "winner-single-control-panel-no-keyboard-reload-2026-08-02"

_PRE_SINGLE_PANEL_SEND_QUICK_CONTROL = send_quick_control_panel


def send_quick_control_panel(action_done: str = "", force_new: bool = False) -> None:
    """Reuse the existing root panel even when an older startup caller asks for force_new."""
    effective_force_new = bool(force_new)
    try:
        saved = load_control_state().get("quick_control_message_id")
        if saved:
            effective_force_new = False
    except Exception:
        pass
    return _PRE_SINGLE_PANEL_SEND_QUICK_CONTROL(action_done, force_new=effective_force_new)


def _final_control_markup_callbacks(reply_markup: dict[str, Any] | None) -> set[str]:
    if not isinstance(reply_markup, dict):
        return set()
    keyboard = reply_markup.get("inline_keyboard")
    if not isinstance(keyboard, list):
        return set()
    return {
        str(button.get("callback_data") or "")
        for row in keyboard if isinstance(row, list)
        for button in row if isinstance(button, dict)
        if str(button.get("callback_data") or "")
    }


def _final_is_navigation_keyboard(reply_markup: dict[str, Any] | None) -> bool:
    callbacks = _final_control_markup_callbacks(reply_markup)
    if not callbacks:
        return False
    exact_navigation = {
        "football_quick_main",
        "football_menu_monitor",
        "football_menu_filters",
        "football_menu_filter",
        "football_menu_categories",
        "football_menu_writers",
        "football_menu_teams",
        "football_menu_stats",
        "football_bot_on",
        "football_bot_off",
    }
    if callbacks & exact_navigation:
        return True
    return any(
        callback.startswith((
            "football_menu_",
            "football_facts_menu",
            "football_facts_main",
            "football_special_sources_menu",
        ))
        for callback in callbacks
    )


_PRE_SINGLE_PANEL_SEND_CONTROL_TEXT = send_control_text


def send_control_text(
    text: str,
    message_id: Any = None,
    reply_markup: dict[str, Any] | None = None,
) -> int | None:
    """Do not copy the complete management keyboard into new result messages."""
    clean_markup = reply_markup
    if message_id is None and _final_is_navigation_keyboard(reply_markup):
        clean_markup = control_delete_message_reply_markup()
    return _PRE_SINGLE_PANEL_SEND_CONTROL_TEXT(text, message_id, clean_markup)

# ====== END FINAL SINGLE CONTROL PANEL / NO DUPLICATE KEYBOARDS FIX ======


# ====== FINAL QUIET PREPARE CLEANUP / IMMEDIATE MAIN SEND PATCH (2026-08-02) ======
# Narrow scope only:
# - after "הכן דיווח", keep only the prepared post; remove the temporary loading
#   message instead of replacing it with a separate completion notice;
# - start quiet-channel -> Neto Sport sends immediately on a dedicated thread;
# - when the already-prepared Telegram preview has media/message IDs, copy that
#   exact Telegram message directly instead of rebuilding/downloading it again;
# - show a new control message only on failure. RSS, filters, formatting and
#   persistent-file names are untouched.

BOT_BUILD_ID = "winner-quiet-prepare-clean-immediate-send-2026-08-02"


def _quiet_delete_temporary_status(message_id: int | None) -> None:
    if not message_id or not CONTROL_CHAT_ID:
        return
    try:
        telegram_api(
            "deleteMessage",
            {"chat_id": CONTROL_CHAT_ID, "message_id": int(message_id)},
            max_attempts=1,
            timeout=max(TELEGRAM_BUTTON_FAST_TIMEOUT_SECONDS, 3.0),
        )
    except Exception as exc:
        logging.debug("Could not delete temporary prepare status message %s: %s", message_id, exc)


# The existing callback resolves this global when its worker starts, so replacing
# it here removes the unwanted completion message without changing preparation.
def _run_prepare_button(token: str, status_message_id: int | None) -> None:
    try:
        prepare_history_post_with_ai(token)
        # The prepared post has already been sent by prepare_history_post_with_ai.
        # Remove the temporary spinner so the operator sees only the ready post.
        _quiet_delete_temporary_status(status_message_id)
    except Exception as exc:
        logging.exception("Prepare-report button task failed")
        if status_message_id:
            send_control_text(
                "⛔ הכנת הדיווח נכשלה:\n" + short_error(exc, 900),
                status_message_id,
                control_delete_message_reply_markup(),
            )
    finally:
        with _PREPARE_BUTTON_LOCK:
            _PREPARE_BUTTON_INFLIGHT.discard(token)


def _quiet_prepared_message_ids(token: str, item: dict[str, Any] | None = None) -> list[int]:
    values: list[Any] = []
    values.extend(list(CONTROL_TELEGRAM_MEDIA_CACHE.get(token, []) or []))
    if isinstance(item, dict):
        values.extend(list(item.get("control_media_message_ids", []) or []))
    result: list[int] = []
    seen: set[int] = set()
    for value in values:
        try:
            message_id = int(value)
        except Exception:
            continue
        if message_id > 0 and message_id not in seen:
            seen.add(message_id)
            result.append(message_id)
    return result


def _quiet_copy_prepared_preview_immediately(token: str, item: dict[str, Any]) -> dict[str, int]:
    """Copy the exact ready Telegram preview to every main target with one attempt.

    This is the fastest and safest lane for media because Telegram already hosts
    the prepared photo/video and caption. All cached message IDs are copied so a
    prepared media group remains complete.
    """
    if not CONTROL_CHAT_ID:
        return {}
    message_ids = _quiet_prepared_message_ids(token, item)
    if not message_ids:
        return {}
    copied: dict[str, int] = {}
    for target_chat_id in TELEGRAM_CHAT_IDS:
        first_new_id = 0
        copied_for_chat = False
        for source_message_id in message_ids:
            try:
                response = telegram_api(
                    "copyMessage",
                    {
                        "chat_id": target_chat_id,
                        "from_chat_id": CONTROL_CHAT_ID,
                        "message_id": int(source_message_id),
                    },
                    max_attempts=1,
                    timeout=max(TELEGRAM_BUTTON_FAST_TIMEOUT_SECONDS, 5.0),
                )
                ids = _telegram_result_message_ids(response)
                if ids and not first_new_id:
                    first_new_id = int(ids[0])
                copied_for_chat = True
            except Exception as exc:
                logging.warning(
                    "Immediate prepared-message copy failed from %s to %s: %s",
                    source_message_id,
                    target_chat_id,
                    exc,
                )
        if copied_for_chat:
            copied[str(target_chat_id)] = first_new_id
    return copied


_PRE_QUIET_IMMEDIATE_SEND_PREPARED = send_prepared_control_post_to_main


def send_prepared_control_post_to_main(token: str) -> str:
    item = _restore_prepared_send(token)
    if not isinstance(item, dict):
        return _PRE_QUIET_IMMEDIATE_SEND_PREPARED(token)

    # A manually edited body must be sent through the established edited-text
    # path; otherwise the already-rendered Telegram preview is authoritative.
    edited = _get_manual_edit(token) if "_get_manual_edit" in globals() else ""
    if not edited:
        copied_ids = _quiet_copy_prepared_preview_immediately(token, item)
        if copied_ids:
            post = item.get("post")
            if isinstance(post, Post):
                message = str(item.get("prepared_final_message_html") or "").strip()
                if not message:
                    translated = str(item.get("translated", "") or "")
                    quoted_translated = str(item.get("quoted_translated", "") or "")
                    quoted_author_translated = str(item.get("quoted_author_translated", "") or "")
                    message = build_message(
                        post,
                        translated,
                        quoted_translated,
                        quoted_author_translated,
                        include_video_link=False,
                    )
                try:
                    remember_persistent_sent(post, message, "manual_telegram_immediate_copy")
                    state = load_state()
                    if copied_ids:
                        remember_bot_sent_reply_target(post, state, copied_ids)
                    remember_channel_news_text(
                        message,
                        state,
                        message_id=post.link,
                        source="manual_telegram_immediate_copy",
                    )
                    confirm_recent_news_event(post, state)
                    seen = set(state.get(post.username, []))
                    seen.update(post.dedupe_ids)
                    state[post.username] = list(seen)[-500:]
                    save_state(state)
                except Exception as exc:
                    logging.debug("Immediate manual-send memory update failed: %s", exc)
            return "נשלח לערוץ נטו ספורט."

    return _PRE_QUIET_IMMEDIATE_SEND_PREPARED(token)


_QUIET_SEND_INFLIGHT: set[str] = set()
_QUIET_SEND_LOCK = RLock()
_PRE_QUIET_IMMEDIATE_PROCESS_CONTROL_UPDATE = process_control_update


def _quiet_send_failed_text(result: str) -> bool:
    value = str(result or "").strip()
    return any(word in value for word in ("נכשל", "לא ניתן", "לא נמצא", "לא קיים", "אין מספיק"))


def _quiet_run_send_now(token: str, blocked_item: bool = False) -> None:
    key = ("blocked:" if blocked_item else "prepared:") + token
    try:
        if blocked_item:
            result = send_control_blocked_post_to_main(token)
        else:
            result = send_prepared_control_post_to_main(token)
        # Successful delivery is visible in Neto Sport itself; do not create a
        # second status message in the quiet channel. Only surface failures.
        if _quiet_send_failed_text(result):
            send_control_text(str(result), None, control_delete_message_reply_markup())
    except Exception as exc:
        logging.exception("Immediate quiet-to-main send failed")
        try:
            send_control_text(
                "⛔ השליחה לערוץ נטו ספורט נכשלה:\n" + short_error(exc, 900),
                None,
                control_delete_message_reply_markup(),
            )
        except Exception:
            pass
    finally:
        with _QUIET_SEND_LOCK:
            _QUIET_SEND_INFLIGHT.discard(key)


def process_control_update(update: dict[str, Any]) -> None:
    callback = update.get("callback_query") or {}
    if not callback:
        return _PRE_QUIET_IMMEDIATE_PROCESS_CONTROL_UPDATE(update)
    data = str(callback.get("data", "") or "")
    if not (data.startswith("football_send_test:") or data.startswith("football_force_blocked:")):
        return _PRE_QUIET_IMMEDIATE_PROCESS_CONTROL_UPDATE(update)

    callback_id = str(callback.get("id", "") or "")
    message = callback.get("message", {}) or {}
    chat_id = str((message.get("chat", {}) or {}).get("id", ""))
    if CONTROL_CHAT_ID and chat_id != str(CONTROL_CHAT_ID):
        if callback_id:
            answer_control_callback(callback_id, "אין הרשאה לערוץ הזה")
        return

    blocked_item = data.startswith("football_force_blocked:")
    token = data.split(":", 1)[1].strip()
    key = ("blocked:" if blocked_item else "prepared:") + token
    with _QUIET_SEND_LOCK:
        already_running = key in _QUIET_SEND_INFLIGHT
        if not already_running:
            _QUIET_SEND_INFLIGHT.add(key)

    if already_running:
        if callback_id:
            answer_control_callback(callback_id, "השליחה כבר מתבצעת")
        return

    # Start the delivery thread before the cosmetic callback acknowledgement,
    # so the actual send begins at the earliest possible moment.
    Thread(target=_quiet_run_send_now, args=(token, blocked_item), daemon=True).start()
    if callback_id:
        answer_control_callback(callback_id, "שולח עכשיו לנטו ספורט")

# ====== END FINAL QUIET PREPARE CLEANUP / IMMEDIATE MAIN SEND PATCH ======


# ====== FINAL FACTS MENU / CLEAN REPORT TEXT / RETROSPECTIVE FACT PATCH (2026-08-02) ======
# Narrow scope only:
# - remove the two unnecessary buttons from the Facts hub;
# - clean empty [] remnants and normalize "דיווח מיידי" to "דיווח";
# - allow a completed, retrospective own-goal-on-debut fact while keeping live
#   goals, scores and match updates blocked. RSS and discovery code are untouched.

BOT_BUILD_ID = "winner-facts-clean-menu-retrospective-fact-2026-08-02"


def facts_main_reply_markup() -> dict[str, Any]:
    """Facts hub without the unnecessary settings/statistics buttons."""
    return stable_reply_markup([
        [{"text": "👤 בדוק מקור ספציפי", "callback_data": "football_facts_latest"}],
        [{"text": "🔎 בדיקה וניטור", "callback_data": "football_facts_monitor"}],
        [{"text": "👥 ניהול מקורות", "callback_data": "football_facts_manage"}],
        [{"text": "📚 10 פוסטים אחרונים", "callback_data": "football_facts_history"}],
        [{"text": "⬅️ חזרה לראשי", "callback_data": "football_quick_main"}],
    ])


def facts_monitor_reply_markup() -> dict[str, Any]:
    """Facts monitoring menu, keeping only operational checks."""
    return stable_reply_markup([
        [{"text": "🔄 בדוק את כל המקורות עכשיו", "callback_data": "football_facts_check_all"}],
        [{"text": "📡 בדיקת RSS", "callback_data": "football_facts_rss"}],
        [{"text": "📋 20 חסימות אחרונות", "callback_data": "football_facts_blocks"}],
        [{"text": "⏱️ בדיקת עיכוב אמיתית", "callback_data": "football_facts_pipeline_timings"}],
        [{"text": "⬅️ חזרה לעובדות", "callback_data": "football_menu_facts"}],
    ])


_FINAL_EMPTY_BRACKETS_LINE_RE = re.compile(
    r"(?m)^[ \t]*\[\s*\][ \t]*(?:[.!?…]+)?[ \t]*$"
)
_FINAL_EMPTY_BRACKETS_INLINE_RE = re.compile(r"\[\s*\][ \t]*(?:\.)?")
_FINAL_IMMEDIATE_REPORT_RE = re.compile(r"(?iu)\bדיווח[ \t]+מיידי\b")


def _final_clean_facts_report_text(value: str) -> str:
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    # Remove the complete detached [] / []. line first, so no empty paragraph or
    # orphan full stop remains. Then remove any rare inline empty-bracket remnant.
    text = _FINAL_EMPTY_BRACKETS_LINE_RE.sub("", text)
    text = _FINAL_EMPTY_BRACKETS_INLINE_RE.sub("", text)
    text = _FINAL_IMMEDIATE_REPORT_RE.sub("דיווח", text)
    text = re.sub(r"[ \t]+([,.;:!?])", r"\1", text)
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


_PRE_FINAL_FACTS_CLEAN_OUTGOING_BODY = _requested_clean_outgoing_body


def _requested_clean_outgoing_body(post: Post, value: str) -> str:
    return _final_clean_facts_report_text(
        _PRE_FINAL_FACTS_CLEAN_OUTGOING_BODY(post, value)
    )


_FINAL_RETROSPECTIVE_OWN_GOAL_RE = re.compile(
    r"(?iu)(?:"
    r"\b(?:scored|scores|netted)\s+(?:an?\s+)?own\s+goal\b|"
    r"\bown\s+goal\b|שער\s+עצמי|כבש(?:ה|ו)?\s+שער\s+עצמי"
    r")"
)
_FINAL_DEBUT_CONTEXT_RE = re.compile(
    r"(?iu)(?:\b(?:home\s+)?debut\b|הופעת\s+הבכורה|בבכורה|משחק\s+הבכורה)"
)
_FINAL_ACTIVE_LIVE_MATCH_CUE_RE = re.compile(
    r"(?iu)(?:"
    r"^\s*GOAL\b|\bLIVE\b|\bNOW\b|\bcurrently\b|\bminute\s*\d+\b|"
    r"\b(?:HT|FT)\b|\bhalf[- ]?time\b|\bfull[- ]?time\b|"
    r"\b(?:takes?|took)\s+the\s+lead\b|\bequali[sz](?:er|es|ed|ing)?\b|"
    r"\b\d+\s*[-:]\s*\d+\b|עדכון\s+חי|בשידור\s+חי|לייב|כעת\s+במשחק|"
    r"דקה\s*\d+|מחצית|סיום\s+המשחק|תוצאה\s+סופית|עלה\s+ליתרון|השווה"
    r")"
)


def _final_is_completed_retrospective_own_goal_fact(post: Post) -> bool:
    if not _is_facts_source(post):
        return False
    source = _requested_source_text(post) if "_requested_source_text" in globals() else _final_source_text(post)
    text = html.unescape(str(source or "")).strip()
    if not text:
        return False
    # This exception is intentionally narrow: a completed anecdotal fact about an
    # own goal on a debut. It does not allow live goal alerts, scores or play-by-play.
    return bool(
        _FINAL_RETROSPECTIVE_OWN_GOAL_RE.search(text)
        and _FINAL_DEBUT_CONTEXT_RE.search(text)
        and not _FINAL_ACTIVE_LIVE_MATCH_CUE_RE.search(text)
    )


_PRE_FINAL_RETROSPECTIVE_FACT_LOCAL_BLOCK = pre_send_final_local_block_reason


def pre_send_final_local_block_reason(post: Post) -> str:
    reason = _PRE_FINAL_RETROSPECTIVE_FACT_LOCAL_BLOCK(post)
    if _final_is_completed_retrospective_own_goal_fact(post) and str(reason or "") in {
        "centregoals_live_match_update",
        "live_goal_or_match_moment",
        "match_result_or_engagement",
        "match_context_noise",
        "special_source_not_meaningful_fact",
        "media_without_report",
        "too_short_without_strong_news",
    }:
        return ""
    return reason

# ====== END FINAL FACTS MENU / CLEAN REPORT TEXT / RETROSPECTIVE FACT PATCH ======


# ====== FINAL WORKING CHANNEL LOGO ON IMAGES (2026-08-02) ======
# The exact user-provided Neto Sport logo is bundled next to this Python file.
# It is applied only to photos, in a small circular badge at the top-left.
# Videos are intentionally untouched to avoid expensive re-encoding.
# This final layer is loaded BEFORE main(), so it is active in Railway runtime.

def _load_pillow_for_single_file_logo() -> tuple[Any, Any, Any]:
    """Load Pillow, installing it once when the single-file server lacks it.

    The logo bytes themselves are embedded below, so this Python file is the only
    project file required.  A runtime install is attempted only when Pillow is not
    already available.
    """
    try:
        from PIL import Image as _Image, ImageOps as _ImageOps, ImageDraw as _ImageDraw
        return _Image, _ImageOps, _ImageDraw
    except Exception as first_error:
        try:
            import subprocess
            subprocess.run(
                [sys.executable, "-m", "pip", "install", "--disable-pip-version-check", "--no-input", "Pillow>=10,<13"],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=180,
            )
            from PIL import Image as _Image, ImageOps as _ImageOps, ImageDraw as _ImageDraw
            return _Image, _ImageOps, _ImageDraw
        except Exception as install_error:
            logging.error(
                "Pillow is unavailable and automatic installation failed: %s | %s",
                first_error,
                install_error,
            )
            return None, None, None


Image, ImageOps, ImageDraw = _load_pillow_for_single_file_logo()

