def _channel_logo_resolved_path() -> str:
    global _CHANNEL_LOGO_SOURCE_PATH
    if _CHANNEL_LOGO_SOURCE_PATH and os.path.isfile(_CHANNEL_LOGO_SOURCE_PATH):
        return _CHANNEL_LOGO_SOURCE_PATH
    try:
        import tempfile
        output = Path(tempfile.gettempdir()) / "neto_sport_logo_embedded.jpg"
        if not output.is_file() or output.stat().st_size == 0:
            output.write_bytes(base64.b64decode(_CHANNEL_LOGO_EMBEDDED_B64))
        _CHANNEL_LOGO_SOURCE_PATH = str(output)
        return _CHANNEL_LOGO_SOURCE_PATH
    except Exception:
        return ""


_CHANNEL_LOGO_CACHE_LOCK = RLock()
_CHANNEL_LOGO_BADGE_CACHE: dict[int, str] = {}
_CHANNEL_BRANDED_IMAGE_CACHE: dict[str, tuple[float, str]] = {}


def _channel_logo_enabled() -> bool:
    resolved = _channel_logo_resolved_path()
    return bool(Image is not None and resolved and os.path.isfile(resolved))


def _channel_logo_cache_dir() -> Path:
    try:
        base = Path(app_data_dir()) / "neto_sport_logo_cache"
    except Exception:
        import tempfile
        base = Path(tempfile.gettempdir()) / "neto_sport_logo_cache"
    base.mkdir(parents=True, exist_ok=True)
    return base


def _channel_logo_badge(size: int) -> str:
    size = max(24, int(size))
    with _CHANNEL_LOGO_CACHE_LOCK:
        cached = _CHANNEL_LOGO_BADGE_CACHE.get(size)
        if cached and os.path.isfile(cached):
            return cached
    output = _channel_logo_cache_dir() / f"badge_{size}.png"
    if output.is_file() and output.stat().st_size > 0:
        with _CHANNEL_LOGO_CACHE_LOCK:
            _CHANNEL_LOGO_BADGE_CACHE[size] = str(output)
        return str(output)
    if not _channel_logo_enabled():
        return ""
    source = Image.open(_channel_logo_resolved_path()).convert("RGBA")
    square = ImageOps.fit(source, (size, size), method=Image.Resampling.LANCZOS, centering=(0.5, 0.5))
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size - 1, size - 1), fill=255)
    badge = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    badge.paste(square, (0, 0), mask)
    border = max(2, size // 40)
    ImageDraw.Draw(badge).ellipse(
        (border // 2, border // 2, size - 1 - border // 2, size - 1 - border // 2),
        outline=(255, 255, 255, 235),
        width=border,
    )
    badge.save(output, "PNG")
    with _CHANNEL_LOGO_CACHE_LOCK:
        _CHANNEL_LOGO_BADGE_CACHE[size] = str(output)
    return str(output)


def _channel_read_image_bytes(source: str) -> bytes:
    if os.path.isfile(source):
        return Path(source).read_bytes()
    request = urllib.request.Request(
        str(source),
        headers={"User-Agent": "Mozilla/5.0", "Accept": "image/*,*/*;q=0.8"},
    )
    with urllib.request.urlopen(request, timeout=60) as response:
        return response.read()


def _channel_brand_image(source: str) -> str:
    if not _channel_logo_enabled():
        raise RuntimeError(
            "Neto Sport logo is unavailable. Ensure neto_sport_logo.jpg and Pillow are installed."
        )
    key = hashlib.sha256(("neto-logo-uniform-12pct-v2|" + str(source)).encode("utf-8", errors="ignore")).hexdigest()
    with _CHANNEL_LOGO_CACHE_LOCK:
        cached = _CHANNEL_BRANDED_IMAGE_CACHE.get(key)
        if cached and time.time() - cached[0] < 24 * 60 * 60 and os.path.isfile(cached[1]):
            return cached[1]
    folder = _channel_logo_cache_dir() / "photos"
    folder.mkdir(parents=True, exist_ok=True)
    output = folder / f"{key}.jpg"
    if output.is_file() and output.stat().st_size > 0:
        with _CHANNEL_LOGO_CACHE_LOCK:
            _CHANNEL_BRANDED_IMAGE_CACHE[key] = (time.time(), str(output))
        return str(output)
    raw = _channel_read_image_bytes(source)
    base = Image.open(io.BytesIO(raw)).convert("RGBA")
    width, height = base.size
    if width < 80 or height < 80:
        raise RuntimeError("image_too_small_for_logo")
    # Uniform proportional logo size for every image orientation.
    # Use the short side so square, portrait and landscape images look consistent.
    # The fixed floor/ceiling prevent the badge from becoming invisible or oversized.
    short_side = min(width, height)
    logo_size = max(24, round(short_side * 0.12))
    badge_path = _channel_logo_badge(logo_size)
    badge = Image.open(badge_path).convert("RGBA")
    margin = max(8, min(18, round(short_side * 0.014)))
    base.alpha_composite(badge, (margin, margin))
    base.convert("RGB").save(output, "JPEG", quality=95, optimize=True)
    with _CHANNEL_LOGO_CACHE_LOCK:
        _CHANNEL_BRANDED_IMAGE_CACHE[key] = (time.time(), str(output))
    return str(output)


def _channel_brand_images(images: list[str]) -> list[str]:
    result: list[str] = []
    for source in images or []:
        result.append(_channel_brand_image(source))
    return result


def _channel_multipart_telegram_api(method: str, fields: dict[str, Any], files: list[tuple[str, str]]) -> dict[str, Any]:
    boundary = "----NetoSportImageBoundary" + hashlib.sha256(f"{time.time_ns()}:{method}".encode()).hexdigest()[:24]
    body = bytearray()

    def add(value: bytes) -> None:
        body.extend(value)

    for key, raw_value in fields.items():
        if raw_value is None:
            continue
        if isinstance(raw_value, (dict, list)):
            value = json.dumps(raw_value, ensure_ascii=False, separators=(",", ":"))
        elif isinstance(raw_value, bool):
            value = "true" if raw_value else "false"
        else:
            value = str(raw_value)
        add(f"--{boundary}\r\n".encode())
        add(f'Content-Disposition: form-data; name="{key}"\r\n\r\n'.encode())
        add(value.encode("utf-8"))
        add(b"\r\n")

    for field_name, file_path in files:
        filename = os.path.basename(file_path) or "image.jpg"
        add(f"--{boundary}\r\n".encode())
        add(f'Content-Disposition: form-data; name="{field_name}"; filename="{filename}"\r\n'.encode())
        add(b"Content-Type: image/jpeg\r\n\r\n")
        with open(file_path, "rb") as handle:
            add(handle.read())
        add(b"\r\n")
    add(f"--{boundary}--\r\n".encode())

    request = urllib.request.Request(
        f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/{method}",
        data=bytes(body),
        headers={"Content-Type": f"multipart/form-data; boundary={boundary}"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=120) as response:
        payload = json.loads(response.read().decode("utf-8", errors="replace"))
    if not payload.get("ok"):
        raise RuntimeError(f"Telegram error: {payload}")
    return payload


def _channel_send_photo_set_to_chat(
    chat_id: str,
    images: list[str],
    caption: str,
    reply_markup: dict[str, Any] | None = None,
    reply_id: int | None = None,
) -> dict[str, Any]:
    if not images:
        raise RuntimeError("missing_images")
    common: dict[str, Any] = {"chat_id": chat_id}
    if reply_id:
        common["reply_to_message_id"] = int(reply_id)
        common["allow_sending_without_reply"] = True
    if len(images) == 1:
        common.update({"caption": caption, "parse_mode": "HTML"})
        if reply_markup:
            common["reply_markup"] = reply_markup
        return _channel_multipart_telegram_api("sendPhoto", common, [("photo", images[0])])

    media: list[dict[str, Any]] = []
    files: list[tuple[str, str]] = []
    for index, path in enumerate(images):
        field = f"photo{index}"
        row: dict[str, Any] = {"type": "photo", "media": f"attach://{field}"}
        if index == 0:
            row["caption"] = caption
            row["parse_mode"] = "HTML"
        media.append(row)
        files.append((field, path))
    common["media"] = media
    # Telegram does not support reply_markup on media groups. The actionable
    # button is sent separately only in the quiet/control channel when needed.
    return _channel_multipart_telegram_api("sendMediaGroup", common, files)


# Preserve the fully-built existing behavior as fallback for video and text posts.
_CHANNEL_PREVIOUS_SEND_PREPARED = send_prepared_message_to_main
_CHANNEL_PREVIOUS_MANUAL_SEND = manual_force_send_prepared_message
_CHANNEL_PREVIOUS_CONTROL_CANDIDATE = _send_full_control_candidate


def _channel_send_branded_to_main(
    post: Post,
    message: str,
    images: list[str],
    reply_message_ids: dict[str, int] | None = None,
) -> tuple[dict[str, int], str]:
    exact_images = _final_dedupe_exact_photos(images or selected_post_images(post)) if "_final_dedupe_exact_photos" in globals() else list(dict.fromkeys(images or selected_post_images(post)))
    branded = _channel_brand_images(exact_images)
    if not _acceptance_caption_fits(message):
        raise RuntimeError(hebrew_block_reason("caption_too_long_for_single_media_message"))
    message_ids: dict[str, int] = {}
    errors: list[str] = []
    for chat_id in TELEGRAM_CHAT_IDS:
        try:
            response = _channel_send_photo_set_to_chat(
                str(chat_id),
                branded,
                message,
                reply_id=(reply_message_ids or {}).get(str(chat_id)),
            )
            ids = _telegram_result_message_ids(response)
            if ids:
                message_ids[str(chat_id)] = int(ids[0])
        except Exception as exc:
            errors.append(f"{chat_id}: {exc}")
            logging.error("Branded photo send failed for chat %s: %s", chat_id, exc)
    if not message_ids:
        raise RuntimeError("Branded photo broadcast failed for all chats: " + " | ".join(errors))
    return message_ids, f"{len(branded)} branded_images"


def send_prepared_message_to_main(
    post: Post,
    message: str,
    images: list[str],
    video_url: str = "",
    reply_message_ids: dict[str, int] | None = None,
) -> tuple[dict[str, int], str]:
    if video_url or _acceptance_post_requires_video(post) or not (images or selected_post_images(post)):
        return _CHANNEL_PREVIOUS_SEND_PREPARED(
            post, message, images, video_url=video_url, reply_message_ids=reply_message_ids
        )
    if is_too_old_post(post):
        raise RuntimeError(hebrew_block_reason("old_post"))
    clean_message = _finalize_outgoing_message_only(message) if "_finalize_outgoing_message_only" in globals() else message
    return _channel_send_branded_to_main(post, clean_message, images, reply_message_ids=reply_message_ids)


def manual_force_send_prepared_message(
    post: Post,
    message: str,
    images: list[str],
    video_url: str = "",
    reply_message_ids: dict[str, int] | None = None,
) -> tuple[dict[str, int], str]:
    if video_url or _acceptance_post_requires_video(post) or not (images or selected_post_images(post)):
        return _CHANNEL_PREVIOUS_MANUAL_SEND(
            post, message, images, video_url=video_url, reply_message_ids=reply_message_ids
        )
    clean_message = _finalize_outgoing_message_only(message) if "_finalize_outgoing_message_only" in globals() else message
    return _channel_send_branded_to_main(post, clean_message, images, reply_message_ids=reply_message_ids)


# Some earlier manual paths intentionally call this alias directly.
_base_send_prepared_message_to_main = manual_force_send_prepared_message


def _send_full_control_candidate(post: Post, token: str, message_html: str) -> list[int]:
    """Prepare the quiet-channel preview with the same branded photos.

    Since the fast quiet-to-main path uses Telegram copyMessage, branding the
    preview here ensures the copied main-channel message already contains the logo.
    """
    _reliable_hydrate_exact_post(post, force=True)
    if _acceptance_post_requires_video(post):
        return _CHANNEL_PREVIOUS_CONTROL_CANDIDATE(post, token, message_html)
    images = selected_post_images(post)
    if not images:
        return _CHANNEL_PREVIOUS_CONTROL_CANDIDATE(post, token, message_html)
    if not CONTROL_CHAT_ID:
        return []
    if not _acceptance_caption_fits(message_html):
        raise RuntimeError(hebrew_block_reason("caption_too_long_for_single_media_message"))
    try:
        branded = _channel_brand_images(images)
        markup = ensure_delete_button_reply_markup(control_send_to_main_reply_markup(token))
        response = _channel_send_photo_set_to_chat(
            str(CONTROL_CHAT_ID),
            branded,
            message_html,
            reply_markup=markup if len(branded) == 1 else None,
        )
        ids = _telegram_result_message_ids(response)
        if ids:
            CONTROL_TELEGRAM_MEDIA_CACHE[token] = list(ids)
            _save_prepared_media_ids(token, ids)
            if len(branded) > 1:
                send_control_html("הפוסט מוכן לשליחה.", control_send_to_main_reply_markup(token))
        return ids
    except Exception as exc:
        logging.exception("Branded quiet-channel preview failed")
        send_control_text(
            "⛔ הכנת התמונה עם לוגו הערוץ נכשלה:\n" + short_error(exc, 900),
            None,
            control_delete_message_reply_markup(),
        )
        return []


