# ====== FINAL FABRIZIO / €8 / EXACT HERE-WE-GO POSITION PATCH (2026-08-02) ======
# Narrow requested scope only:
# 1) Fabrizio Romano is not blocked by the generic 15-word minimum.
# 2) The normal transfer-fee floor is €8m.
# 3) A genuine HERE WE GO remains on the exact source line and is never appended
#    to another paragraph. Existing source line/paragraph separators are preserved.

MIN_TRANSFER_FEE_MILLIONS_TO_SEND = 8.0

_PRE_FINAL_FABRIZIO_WORD_GATE = pre_send_final_local_block_reason


def pre_send_final_local_block_reason(post: Post) -> str:
    reason = _PRE_FINAL_FABRIZIO_WORD_GATE(post)
    if (
        str(getattr(post, "username", "") or "").casefold() == "fabrizioromano"
        and "report_under_15_words" in str(reason or "")
    ):
        return ""
    return reason


_FINAL_HWG_ANY_OUTPUT_RE = re.compile(
    r"(?iu)#?HERE(?:_|\s)+WE(?:_|\s)+GO\b"
)
_FINAL_HWG_TRANSLATED_PLACEHOLDER_RE = re.compile(
    r"(?iu)(?:הנה(?:\s+זה\s+(?:קורה|בא))?|כאן\s+אנחנו\s+הולכים|היר\s+וי\s+גו)\s*[!?.…]?"
)


def _final_hwg_source_parts(post: Post) -> tuple[list[str], int, re.Match[str] | None]:
    source = _final_corresponding_source_text(post, quoted=False)
    source = source.replace("\r\n", "\n").replace("\r", "\n")
    segments = [part.strip() for part in re.split(r"\n+", source) if part.strip()]
    for index, segment in enumerate(segments):
        match = _FINAL_EXPLICIT_HWG_RE.search(segment)
        if match:
            return segments, index, match
    return segments, -1, None


def _final_hwg_token_from_source(segment: str, match: re.Match[str]) -> str:
    raw = match.group(0)
    token = "#HERE_WE_GO" if ("#" in raw or "_" in raw) else "HERE WE GO"
    tail = segment[match.end():]
    punctuation = ""
    punctuation_match = re.match(r"\s*([!?…\.])", tail)
    if punctuation_match:
        punctuation = punctuation_match.group(1)
    return token + punctuation


def _final_remove_hwg_from_line(line: str, remove_placeholder: bool = False) -> str:
    value = re.sub(
        r"(?iu)#?HERE(?:_|\s)+WE(?:_|\s)+GO\b\s*[!?.…]?",
        "",
        str(line or ""),
    )
    if remove_placeholder:
        value = _FINAL_HWG_TRANSLATED_PLACEHOLDER_RE.sub("", value)
    value = re.sub(r"[ \t]+([,.;:!?])", r"\1", value)
    value = re.sub(r"([,;:])\s*([!?])", r"\2", value)
    value = value.strip()
    value = re.sub(r"([.!?…])[,;:]+$", r"\1", value)
    value = re.sub(r"([.!?…])[!?…]+$", r"\1", value)
    value = re.sub(r"[ \t]{2,}", " ", value)
    value = re.sub(r"\s+([.!?…])$", r"\1", value)
    return value.strip()


def _final_insert_hwg_on_source_line(line: str, source_segment: str, match: re.Match[str]) -> str:
    clean = _final_remove_hwg_from_line(line, remove_placeholder=True)
    token = _final_hwg_token_from_source(source_segment, match)
    before = source_segment[:match.start()].rstrip()
    after = source_segment[match.end():].strip()
    after_without_punctuation = re.sub(r"^[!?….,;:\s]+|[!?….,;:\s]+$", "", after)

    # The common Fabrizio form is "..., here we go!". Keep the token at that
    # exact point: the end of the corresponding translated source line.
    if not after_without_punctuation:
        source_needs_comma = before.endswith(",")
        core = clean.rstrip()
        # Remove only a terminal punctuation mark produced by translating HERE
        # WE GO itself. Keep a source comma because it belongs before the phrase.
        core = re.sub(r"[!?…\.]+$", "", core).rstrip()
        if source_needs_comma and not core.endswith(","):
            core = core.rstrip(";:") + ","
        return (core + " " + token).strip()

    # Phrase at the start of the source line.
    if not re.sub(r"[\s,;:]+", "", before):
        return (token + " " + clean.lstrip()).strip()

    # Rare middle-of-line case: insert by the source word ratio without changing
    # any newline or paragraph separator.
    source_before_words = re.findall(r"[A-Za-zÀ-ÿא-ת0-9]+", before)
    source_all_words = re.findall(r"[A-Za-zÀ-ÿא-ת0-9]+", source_segment)
    target_matches = list(re.finditer(r"[A-Za-zÀ-ÿא-ת0-9]+", clean))
    if not target_matches:
        return token
    ratio = len(source_before_words) / max(1, len(source_all_words))
    target_index = max(0, min(len(target_matches) - 1, round(ratio * len(target_matches)) - 1))
    insert_at = target_matches[target_index].end()
    return (clean[:insert_at].rstrip() + " " + token + " " + clean[insert_at:].lstrip()).strip()


def _final_relocate_hwg_in_rendered_message(post: Post, rendered: str) -> str:
    source_segments, target_segment_index, source_match = _final_hwg_source_parts(post)
    if target_segment_index < 0 or source_match is None:
        return _final_remove_unauthorized_here_we_go(rendered, _final_corresponding_source_text(post, quoted=False))

    message = str(rendered or "")
    signature_match = re.search(r"\n\n(?=<a\s+href=)", message)
    if not signature_match:
        return message
    before_signature = message[:signature_match.start()]
    signature = message[signature_match.start():]

    header = ""
    body = before_signature
    header_split = before_signature.find("\n\n")
    if before_signature.lstrip().startswith("<b>") and header_split >= 0:
        header = before_signature[:header_split + 2]
        body = before_signature[header_split + 2:]

    lines = body.split("\n")
    nonempty = [index for index, line in enumerate(lines) if line.strip()]
    if not nonempty:
        return message
    target_nonempty = min(target_segment_index, len(nonempty) - 1)
    target_line_index = nonempty[target_nonempty]

    # Remove any token incorrectly appended by an older formatter from every
    # body line, then restore it only on its corresponding source line.
    for index in nonempty:
        lines[index] = _final_remove_hwg_from_line(
            lines[index], remove_placeholder=(index == target_line_index)
        )
    source_segment = source_segments[target_segment_index]
    lines[target_line_index] = _final_insert_hwg_on_source_line(
        lines[target_line_index], source_segment, source_match
    )
    body = "\n".join(lines)
    body = re.sub(r"[ \t]+\n", "\n", body)
    body = re.sub(r"\n[ \t]+", "\n", body)
    return _final_fix_punctuation_collisions_in_message(header + body + signature)


_PRE_FINAL_EXACT_HWG_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    rendered = _PRE_FINAL_EXACT_HWG_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    return _final_relocate_hwg_in_rendered_message(post, rendered)

# ====== END FINAL FABRIZIO / €8 / EXACT HERE-WE-GO POSITION PATCH ======



# ====== FINAL HWG DESTINATION / GREEN-LIGHT PARAGRAPH / BLUE SIGNATURE PATCH (2026-08-02) ======
# Requested narrow scope only. RSS, filters and all other source-layout rules stay unchanged.

_PRE_USER_HWG_INSERT_ON_SOURCE_LINE = _final_insert_hwg_on_source_line


def _final_destination_aliases_before_hwg(source_before: str) -> list[str]:
    """Return destination-club aliases immediately before HERE WE GO.

    This avoids ratio-based insertion in RTL Hebrew.  For a source such as
    ``Juanlu to Bournemouth, here we go!`` the token must follow Bournemouth,
    not the player's name.
    """
    before = str(source_before or "").strip()
    match = re.search(
        r"(?iu)\b(?:to|for|joins?|signs?(?:\s+for)?)\s+([^,;!?\n]+?)\s*,?\s*$",
        before,
    )
    if not match:
        return []
    raw_destination = re.sub(r"\s+", " ", match.group(1)).strip(" .,:;!?")
    aliases: list[str] = [raw_destination]
    normalized_destination = unicodedata.normalize("NFKC", raw_destination).casefold()
    for source_name, hebrew_name in sorted(TEAM_REPLACEMENTS.items(), key=lambda item: len(item[0]), reverse=True):
        normalized_source = unicodedata.normalize("NFKC", str(source_name)).casefold()
        if normalized_source == normalized_destination or normalized_source in normalized_destination or normalized_destination in normalized_source:
            aliases.append(str(hebrew_name))
    # Useful canonical fallback for the reported case even if a legacy dictionary
    # entry is missing in an older persistent deployment.
    if "bournemouth" in normalized_destination:
        aliases.extend(["בורנמות'", "בורנמות׳", "בורנמות"])
    return list(dict.fromkeys(alias for alias in aliases if alias))


def _final_insert_hwg_on_source_line(line: str, source_segment: str, match: re.Match[str]) -> str:
    clean = _final_remove_hwg_from_line(line, remove_placeholder=True)
    token = _final_hwg_token_from_source(source_segment, match)
    before = source_segment[:match.start()].rstrip()

    # Prefer a real destination-club anchor.  Word-ratio placement is unreliable
    # when English LTR source order is translated into Hebrew RTL order.
    for alias in _final_destination_aliases_before_hwg(before):
        alias_match = re.search(re.escape(alias), clean, flags=re.IGNORECASE)
        if not alias_match:
            continue
        left = clean[:alias_match.end()].rstrip()
        right = clean[alias_match.end():].lstrip()
        left = re.sub(r"[!?…\.]+$", "", left).rstrip()
        if before.endswith(",") and not left.endswith(","):
            left = left.rstrip(";:") + ","
        result = left + " " + token
        if right:
            result += " " + right
        result = re.sub(r"[ \t]+([,.;:!?])", r"\1", result)
        result = re.sub(r"([,;:])\s*([!?])", r"\2", result)
        return result.strip()

    return _PRE_USER_HWG_INSERT_ON_SOURCE_LINE(line, source_segment, match)


def _final_split_green_light_like_source(post: Post, rendered: str) -> str:
    """Keep the source's Green-light update as its own paragraph.

    RSS mirrors occasionally collapse this one source break while retaining all
    text.  The repair is activated only when the original post itself contains a
    Green-light/medical-green-light clause and the Hebrew output contains the
    corresponding ``אור ירוק`` clause.
    """
    source = _final_corresponding_source_text(post, quoted=False)
    raw_html = html.unescape(str(getattr(post, "raw_source_html", "") or ""))
    source_probe = source + "\n" + re.sub(r"(?iu)<br\s*/?>|</(?:p|div|li)>", "\n", raw_html)
    if not re.search(r"(?iu)\b(?:medical\s+)?green\s+light\b", source_probe):
        return rendered

    message = str(rendered or "")
    signature_match = re.search(r"\n\n(?=<a\s+href=)", message)
    if signature_match:
        content = message[:signature_match.start()]
        signature = message[signature_match.start():]
    else:
        content, signature = message, ""

    # Do not alter wording or punctuation; only restore the missing paragraph
    # boundary before the Green-light clause.
    content = re.sub(r"(?<!\n)[ \t]+(?=אור\s+ירוק\b)", "\n\n", content, count=1)
    content = re.sub(r"\n[ \t]+", "\n", content)
    content = re.sub(r"\n{3,}", "\n\n", content)
    return content.rstrip() + signature


def _final_force_blue_channel_signature(message: str) -> str:
    """End every outgoing report with a real Telegram HTML link.

    Only the words ``נטו ספורט`` are linked; the period and pencil remain outside
    the anchor.  This is the most reliable visible-blue format in Telegram HTML.
    """
    value = str(message or "").strip()
    value = re.sub(
        r"(?is)\n*<a\b[^>]*href=[\"']https?://t\.me/neto_sport[\"'][^>]*>.*?</a>\s*\.?\s*📝?\s*$",
        "",
        value,
    ).rstrip()
    value = re.sub(
        r"(?im)\n*\s*נטו\s+ספורט\s*(?:\(https?://t\.me/neto_sport\)|https?://t\.me/neto_sport)?\s*\.?\s*📝?\s*$",
        "",
        value,
    ).rstrip()
    signature = f'<a href="{html.escape(SIGNATURE_LINK, quote=True)}">נטו ספורט</a>.📝'
    return (value + "\n\n" + signature).strip() if value else signature


_PRE_USER_FINAL_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    rendered = _PRE_USER_FINAL_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    rendered = _final_split_green_light_like_source(post, rendered)
    return _final_force_blue_channel_signature(rendered)


_PRE_USER_FINALIZE_OUTGOING_MESSAGE_ONLY = _finalize_outgoing_message_only


def _finalize_outgoing_message_only(message: Any) -> str:
    return _final_force_blue_channel_signature(_PRE_USER_FINALIZE_OUTGOING_MESSAGE_ONLY(message))

# ====== END FINAL HWG DESTINATION / GREEN-LIGHT PARAGRAPH / BLUE SIGNATURE PATCH ======



# ====== FINAL RTL HERE-WE-GO CROSS-LINE REPAIR (2026-08-02) ======
# Source-layout allocation can occasionally put the destination club at the
# beginning of the next Hebrew line.  Repair only the explicit "to CLUB, HERE WE
# GO" construction, preserving every existing paragraph separator.


def _final_destination_pattern(alias: str) -> re.Pattern[str]:
    escaped = re.escape(str(alias or ""))
    # Include a normal Hebrew preposition (for example ל+בורנמות') as part of the
    # destination that moves with the club name.
    return re.compile(rf"(?iu)(?<![א-ת])(?:[בלכמשהו][־-]?)?{escaped}(?![א-ת])")


def _final_repair_hwg_destination_across_lines(post: Post, rendered: str) -> str:
    source_segments, target_segment_index, source_match = _final_hwg_source_parts(post)
    if target_segment_index < 0 or source_match is None:
        return rendered
    source_segment = source_segments[target_segment_index]
    source_before = source_segment[:source_match.start()].rstrip()
    aliases = _final_destination_aliases_before_hwg(source_before)
    if not aliases:
        return rendered

    message = str(rendered or "")
    signature_match = re.search(r"\n\n(?=<a\s+href=)", message)
    if signature_match:
        before_signature = message[:signature_match.start()]
        signature = message[signature_match.start():]
    else:
        before_signature, signature = message, ""

    header = ""
    body = before_signature
    header_split = before_signature.find("\n\n")
    if before_signature.lstrip().startswith("<b>") and header_split >= 0:
        header = before_signature[:header_split + 2]
        body = before_signature[header_split + 2:]

    lines = body.split("\n")
    hwg_index = next((idx for idx, line in enumerate(lines) if _FINAL_HWG_ANY_OUTPUT_RE.search(line)), -1)
    if hwg_index < 0:
        return message

    destination_index = -1
    destination_match: re.Match[str] | None = None
    # Search the HERE WE GO line and the next two non-empty content lines only.
    checked_nonempty = 0
    for idx in range(hwg_index, len(lines)):
        if not lines[idx].strip():
            continue
        checked_nonempty += 1
        for alias in aliases:
            candidate = _final_destination_pattern(alias).search(lines[idx])
            if candidate:
                destination_index = idx
                destination_match = candidate
                break
        if destination_match or checked_nonempty >= 3:
            break
    if destination_match is None or destination_index < 0:
        return message

    destination_text = destination_match.group(0).strip()
    token = _final_hwg_token_from_source(source_segment, source_match)

    # Remove the destination from wherever source-layout allocation placed it.
    destination_line = lines[destination_index]
    destination_remainder = (
        destination_line[:destination_match.start()] + destination_line[destination_match.end():]
    )
    destination_remainder = re.sub(r"^[\s\u200e\u200f]*[,;:]\s*", "", destination_remainder)
    destination_remainder = re.sub(r"[ \t]{2,}", " ", destination_remainder).strip()

    # Rebuild the source's first clause in correct Hebrew order: player +
    # destination club + HERE WE GO.  Do not change the following report text.
    hwg_core = _final_remove_hwg_from_line(lines[hwg_index], remove_placeholder=True)
    if destination_index == hwg_index:
        # Remove the old destination occurrence from the same line as well.
        same_match = _final_destination_pattern(destination_text).search(hwg_core)
        if same_match:
            hwg_core = (hwg_core[:same_match.start()] + hwg_core[same_match.end():]).strip()
    hwg_core = re.sub(r"[,;:!?…\.\s]+$", "", hwg_core).rstrip()
    comma = "," if source_before.endswith(",") else ""
    lines[hwg_index] = f"{hwg_core} {destination_text.rstrip(',;:')}" + comma + f" {token}"
    lines[hwg_index] = re.sub(r"[ \t]{2,}", " ", lines[hwg_index]).strip()

    if destination_index != hwg_index:
        lines[destination_index] = destination_remainder
    else:
        # Preserve any text that followed the destination on the same translated
        # line by placing it after the repaired first clause.
        if destination_remainder:
            lines[hwg_index] = lines[hwg_index] + " " + destination_remainder

    # Remove empty content lines created only by moving the destination, but keep
    # existing blank paragraph rows between genuine content lines.
    body = "\n".join(lines)
    body = re.sub(r"\n[ \t\u200e\u200f]+\n", "\n\n", body)
    body = re.sub(r"\n{3,}", "\n\n", body)
    return header + body.rstrip() + signature


_PRE_RTL_HWG_FINAL_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    rendered = _PRE_RTL_HWG_FINAL_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    rendered = _final_repair_hwg_destination_across_lines(post, rendered)
    rendered = _final_split_green_light_like_source(post, rendered)
    return _final_force_blue_channel_signature(rendered)

# ====== END FINAL RTL HERE-WE-GO CROSS-LINE REPAIR ======


# ====== FINAL BLUE HERE-WE-GO HASHTAG PATCH (2026-08-02) ======
# Telegram highlights hashtags in blue. Keep all existing source-position and
# paragraph logic, and only normalize the final visible token to exactly:
# #HERE_WE_GO

_BLUE_HWG_VISIBLE_RE = re.compile(
    r"(?iu)(?:#HERE_WE_GO?|#?HERE(?:_|\s)+WE(?:_|\s)+GO)\s*[!?.…]?"
)


def _final_blue_hwg_hashtag(message: Any) -> str:
    value = str(message or "")
    # Existing authorization logic already removes unauthorized HERE WE GO.
    # This function changes only the surviving, genuine visible token.
    return _BLUE_HWG_VISIBLE_RE.sub("#HERE_WE_GO", value)


_PRE_BLUE_HWG_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    rendered = _PRE_BLUE_HWG_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    return _final_blue_hwg_hashtag(rendered)


_PRE_BLUE_HWG_FINALIZE_OUTGOING = _finalize_outgoing_message_only


def _finalize_outgoing_message_only(message: Any) -> str:
    return _final_blue_hwg_hashtag(_PRE_BLUE_HWG_FINALIZE_OUTGOING(message))

# ====== END FINAL BLUE HERE-WE-GO HASHTAG PATCH ======


# ====== FINAL DUPLICATE HERE-WE-GO CLAUSE GUARD / LOGO 1.75X (2026-08-02) ======
# A late layout repair could accidentally repeat the entire first clause while also
# repeating #HERE_WE_GO.  The source authorizes only one token, so when two or more
# appear on the same rendered line, preserve the first complete clause and any text
# that genuinely follows the final token, while removing the duplicated middle copy.

_FINAL_DUPLICATE_HWG_TOKEN_RE = re.compile(r"(?iu)#HERE_WE_GO")


def _final_remove_duplicate_hwg_clause(message: Any) -> str:
    value = str(message or "")
    fixed_lines: list[str] = []
    for line in value.split("\n"):
        matches = list(_FINAL_DUPLICATE_HWG_TOKEN_RE.finditer(line))
        if len(matches) < 2:
            fixed_lines.append(line)
            continue
        first = matches[0]
        last = matches[-1]
        prefix = line[:first.start()].rstrip(" \t,;:!?.…")
        suffix = line[last.end():]
        # Keep exactly one blue Telegram hashtag.  Punctuation surrounding the
        # duplicate copy is normalized without touching paragraph separators.
        suffix = re.sub(r"^[ \t,;:!?.…]+", "", suffix)
        rebuilt = prefix.rstrip()
        if rebuilt:
            rebuilt += ", " if not rebuilt.endswith((",", "-", "–", "—")) else " "
        rebuilt += "#HERE_WE_GO"
        if suffix:
            rebuilt += " " + suffix.lstrip()
        fixed_lines.append(re.sub(r"[ \t]{2,}", " ", rebuilt).strip())
    return "\n".join(fixed_lines)


_PRE_FINAL_HWG_DUPLICATE_GUARD_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    rendered = _PRE_FINAL_HWG_DUPLICATE_GUARD_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    return _final_remove_duplicate_hwg_clause(rendered)


_PRE_FINAL_HWG_DUPLICATE_GUARD_FINALIZE = _finalize_outgoing_message_only


def _finalize_outgoing_message_only(message: Any) -> str:
    return _final_remove_duplicate_hwg_clause(
        _PRE_FINAL_HWG_DUPLICATE_GUARD_FINALIZE(message)
    )

# ====== END FINAL DUPLICATE HERE-WE-GO CLAUSE GUARD / LOGO 1.75X ======



# ====== FINAL STABLE SINGLE-PASS HERE-WE-GO / QUIET PHOTO GUARANTEE (2026-08-02) ======
# Restore the last stable behavior: HERE WE GO is normalized in place exactly once.
# Do not reconstruct, move or append a second copy of the first sentence.  The quiet
# channel must receive the original photo(s), branded when possible, together with
# the exact final caption. RSS, filters, translation retries and persistent memory
# are intentionally untouched.

_STABLE_HWG_INVISIBLE = r"[\u200e\u200f\u202a-\u202e\u2066-\u2069]*"
_STABLE_HWG_TOKEN_RE = re.compile(
    rf"(?iu)#?{_STABLE_HWG_INVISIBLE}HERE{_STABLE_HWG_INVISIBLE}(?:_|\s)+"
    rf"WE{_STABLE_HWG_INVISIBLE}(?:_|\s)+GO\b{_STABLE_HWG_INVISIBLE}[!?.…]?"
)


def _stable_source_hwg_is_terminal(post: Post) -> bool:
    try:
        source_segments, index, match = _final_hwg_source_parts(post)
        if index < 0 or match is None:
            return False
        tail = source_segments[index][match.end():]
        return not bool(re.sub(r"[\s!?.…,:;\-–—]+", "", tail))
    except Exception:
        return False


def _stable_clean_duplicate_hwg_line(line: str, *, source_terminal: bool) -> str:
    value = str(line or "")
    matches = list(_STABLE_HWG_TOKEN_RE.finditer(value))
    if len(matches) < 2:
        return value

    # Keep the complete first clause and one hashtag.  The duplicated material
    # between the first and last token is the late formatter's repeated clause.
    prefix = value[:matches[0].start()].rstrip(" \t,;:!?.…")
    suffix = value[matches[-1].end():].strip()
    rebuilt = prefix
    if rebuilt and not rebuilt.endswith((",", "-", "–", "—")):
        rebuilt += ","
    if rebuilt:
        rebuilt += " "
    rebuilt += "#HERE_WE_GO"

    # In the common Fabrizio form the source token closes the line.  Do not keep
    # any copied suffix.  In a rare middle-of-line source form, preserve only a
    # genuinely informative suffix, never a repeated emoji/name fragment.
    if not source_terminal and suffix:
        words = re.findall(r"[A-Za-zÀ-ÿא-ת0-9]+", suffix)
        if len(words) >= 4 and not re.match(r"^[\s\u200e\u200f]*[🚨🍒🔴⚪️🟡🟢🔵]", suffix):
            rebuilt += " " + suffix
    return re.sub(r"[ \t]{2,}", " ", rebuilt).strip()


def _stable_preclean_hwg_translation(post: Post, translated: str) -> str:
    terminal = _stable_source_hwg_is_terminal(post)
    return "\n".join(
        _stable_clean_duplicate_hwg_line(line, source_terminal=terminal)
        for line in str(translated or "").split("\n")
    )


def _stable_postclean_hwg_message(post: Post, rendered: str) -> str:
    terminal = _stable_source_hwg_is_terminal(post)
    value = "\n".join(
        _stable_clean_duplicate_hwg_line(line, source_terminal=terminal)
        for line in str(rendered or "").split("\n")
    )
    value = _final_blue_hwg_hashtag(value)
    return _final_force_blue_channel_signature(value)


# Use the stable chain captured immediately before the faulty cross-line clause
# reconstruction.  It already preserves source paragraphs and puts HERE WE GO on
# the corresponding source line.  The later reconstruction layer is bypassed.
_STABLE_HWG_BUILD_BASE = _PRE_RTL_HWG_FINAL_BUILD_MESSAGE


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    clean_translated = _stable_preclean_hwg_translation(post, translated)
    clean_quoted = _stable_preclean_hwg_translation(post, quoted_translated)
    rendered = _STABLE_HWG_BUILD_BASE(
        post,
        clean_translated,
        clean_quoted,
        quoted_author_translated,
        include_video_link,
    )
    rendered = _final_split_green_light_like_source(post, rendered)
    return _stable_postclean_hwg_message(post, rendered)


# Bypass the later clause-reconstruction finalizers as well.  This is a message-only
# cleanup and therefore cannot create or move a player/club phrase.
_STABLE_HWG_FINALIZE_BASE = _PRE_USER_FINALIZE_OUTGOING_MESSAGE_ONLY


def _finalize_outgoing_message_only(message: Any) -> str:
    value = _STABLE_HWG_FINALIZE_BASE(message)
    value = "\n".join(
        _stable_clean_duplicate_hwg_line(line, source_terminal=True)
        for line in str(value or "").split("\n")
    )
    value = _final_blue_hwg_hashtag(value)
    return _final_force_blue_channel_signature(value)


_STABLE_QUIET_MEDIA_FALLBACK = _send_full_control_candidate


def _send_full_control_candidate(post: Post, token: str, message_html: str) -> list[int]:
    """Always put the original media in the quiet-channel prepared message.

    Photos are branded and sent with the final caption.  If branding/upload fails,
    fall back to the pre-existing media sender instead of leaving a text-only post.
    """
    try:
        _reliable_hydrate_exact_post(post, force=True)
    except Exception as exc:
        logging.debug("Quiet preview exact hydration failed; using stored media: %s", exc)

    if _acceptance_post_requires_video(post):
        return _STABLE_QUIET_MEDIA_FALLBACK(post, token, message_html)

    images = list(dict.fromkeys(list(getattr(post, "image_urls", []) or [])))[:MAX_IMAGES_PER_POST]
    if not images:
        try:
            images = list(dict.fromkeys(selected_post_images(post)))[:MAX_IMAGES_PER_POST]
        except Exception:
            images = []
    if not images or not CONTROL_CHAT_ID:
        return _STABLE_QUIET_MEDIA_FALLBACK(post, token, message_html)

    try:
        branded = _channel_brand_images(images)
        markup = ensure_delete_button_reply_markup(control_send_to_main_reply_markup(token))
        response = _channel_send_photo_set_to_chat(
            str(CONTROL_CHAT_ID),
            branded,
            message_html,
            reply_markup=markup if len(branded) == 1 else None,
        )
        ids = _telegram_result_message_ids(response)
        if ids:
            CONTROL_TELEGRAM_MEDIA_CACHE[token] = list(ids)
            _save_prepared_media_ids(token, ids)
            if len(branded) > 1:
                # Telegram albums cannot carry an inline keyboard. Send only the
                # action row, not another copy of the report text.
                send_control_html("שלח את ההודעה המוכנה:", control_send_to_main_reply_markup(token))
            return list(ids)
    except Exception as exc:
        logging.warning("Branded quiet-channel photo send failed; using original media path: %s", exc)

    return _STABLE_QUIET_MEDIA_FALLBACK(post, token, message_html)

# ====== END FINAL STABLE SINGLE-PASS HERE-WE-GO / QUIET PHOTO GUARANTEE ======


# ====== USER FINAL FIX: EXACT PARAGRAPHS / SINGLE FOOTER / 12% LOGO / CENTREGOALS GENERAL RULES (2026-08-02) ======
# This final layer is intentionally narrow and is loaded before main(). It keeps
# all persistent files and existing settings intact while correcting only the
# requested output, branding and CentreGoals routing behavior.

BOT_BUILD_ID = "winner-exact-paragraphs-single-footer-logo12-centregoals-general-2026-08-02"

# ---------------------------------------------------------------------------
# 1) Keep exactly one canonical Neto Sport signature and remove the accidental
# standalone `.📝` artifact wherever an older formatter left it in the body.
# ---------------------------------------------------------------------------
_USER_FINAL_INVISIBLE = r"[\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]*"
_USER_FINAL_NETO_ANCHOR_RE = re.compile(
    rf"(?is)<a\b[^>]*href=[\"']https?://t\.me/neto_sport/?[\"'][^>]*>"
    rf"{_USER_FINAL_INVISIBLE}\s*נטו\s+ספורט\s*{_USER_FINAL_INVISIBLE}</a>"
    rf"[ \t{chr(0x200e)}{chr(0x200f)}{chr(0x2066)}{chr(0x2067)}{chr(0x2068)}{chr(0x2069)}]*"
    rf"[.。]?[ \t]*📝?"
)
_USER_FINAL_PLAIN_NETO_LINE_RE = re.compile(
    rf"(?im)^[ \t]*{_USER_FINAL_INVISIBLE}נטו\s+ספורט"
    rf"(?:\s*\(https?://t\.me/neto_sport\)|\s+https?://t\.me/neto_sport)?"
    rf"\s*[.。]?[ \t]*📝?[ \t]*{_USER_FINAL_INVISIBLE}$"
)
_USER_FINAL_ORPHAN_PENCIL_LINE_RE = re.compile(
    rf"(?im)^[ \t]*{_USER_FINAL_INVISIBLE}[.。]?[ \t]*📝[ \t]*{_USER_FINAL_INVISIBLE}$"
)


def _user_final_single_neto_footer(message: Any) -> str:
    value = str(message or "").replace("\r\n", "\n").replace("\r", "\n")
    value = _USER_FINAL_NETO_ANCHOR_RE.sub("", value)
    value = _USER_FINAL_PLAIN_NETO_LINE_RE.sub("", value)
    value = _USER_FINAL_ORPHAN_PENCIL_LINE_RE.sub("", value)
    value = re.sub(r"[ \t]+\n", "\n", value)
    value = re.sub(r"\n[ \t]+", "\n", value)
    value = re.sub(r"\n{3,}", "\n\n", value).strip()
    signature = f'<a href="{html.escape(SIGNATURE_LINK, quote=True)}">נטו ספורט</a>.📝'
    return (value + "\n\n" + signature).strip() if value else signature


# Replace both footer helpers because different automatic/manual paths use them.
def _final_force_blue_channel_signature(message: str) -> str:
    return _user_final_single_neto_footer(message)


def normalize_neto_sport_footer(message: Any) -> str:
    return _user_final_single_neto_footer(message)


# ---------------------------------------------------------------------------
# 2) Normalize HERE WE GO without ever consuming a newline. Preserve the source
# punctuation and force the exact source paragraph boundary after the phrase.
# ---------------------------------------------------------------------------
_USER_FINAL_HSPACE = r"[ \t\u00a0\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]"
_USER_FINAL_HWG_INVISIBLE = r"[\u200e\u200f\u202a-\u202e\u2066-\u2069\ufeff]"
_USER_FINAL_HWG_RE = re.compile(
    rf"(?iu)#?{_USER_FINAL_HWG_INVISIBLE}*HERE{_USER_FINAL_HWG_INVISIBLE}*"
    rf"(?:_|{_USER_FINAL_HSPACE})+WE{_USER_FINAL_HWG_INVISIBLE}*"
    rf"(?:_|{_USER_FINAL_HSPACE})+GO\b{_USER_FINAL_HWG_INVISIBLE}*"
    rf"(?P<punct>[!?.…]?)"
)


def _user_final_blue_hwg(message: Any) -> str:
    value = str(message or "")

    def replace(match: re.Match[str]) -> str:
        return "#HERE_WE_GO" + (match.group("punct") or "")

    return _USER_FINAL_HWG_RE.sub(replace, value)


# Override the global normalizer used dynamically by the stable final chain.
def _final_blue_hwg_hashtag(message: Any) -> str:
    return _user_final_blue_hwg(message)


def _user_final_hwg_source_boundary(post: Post) -> tuple[str, str] | None:
    source = _final_corresponding_source_text(post, quoted=False)
    match = _USER_FINAL_HWG_RE.search(source)
    if not match:
        return None
    tail = source[match.end():]
    boundary = re.match(rf"{_USER_FINAL_HSPACE}*(?P<breaks>(?:\n{_USER_FINAL_HSPACE}*)+)", tail)
    if not boundary:
        return None
    newline_count = boundary.group("breaks").count("\n")
    separator = "\n\n" if newline_count >= 2 else "\n"
    return separator, (match.group("punct") or "")


def _user_final_restore_hwg_boundary(post: Post, rendered: Any) -> str:
    value = _user_final_blue_hwg(rendered)
    source_boundary = _user_final_hwg_source_boundary(post)
    if not source_boundary:
        return value
    separator, source_punctuation = source_boundary
    match = _USER_FINAL_HWG_RE.search(value)
    if not match:
        return value

    # If translation dropped the original !/?/., restore only that punctuation.
    current_punctuation = match.group("punct") or ""
    token = "#HERE_WE_GO" + (current_punctuation or source_punctuation)
    before = value[:match.start()]
    after = value[match.end():]

    # Replace only whitespace immediately after HERE WE GO. Horizontal spaces
    # must never absorb or replace the next source paragraph.
    leading = re.match(rf"{_USER_FINAL_HSPACE}*(?P<breaks>(?:\n{_USER_FINAL_HSPACE}*)*)", after)
    consumed = leading.end() if leading else 0
    remainder = after[consumed:]
    if not remainder:
        return before + token + after
    return before + token + separator + remainder


_USER_FINAL_PRE_BUILD_MESSAGE = build_message


def build_message(
    post: Post,
    translated: str,
    quoted_translated: str = "",
    quoted_author_translated: str = "",
    include_video_link: bool = False,
) -> str:
    rendered = _USER_FINAL_PRE_BUILD_MESSAGE(
        post,
        translated,
        quoted_translated,
        quoted_author_translated,
        include_video_link,
    )
    rendered = _user_final_restore_hwg_boundary(post, rendered)
    return _user_final_single_neto_footer(rendered)


_USER_FINAL_PRE_FINALIZE_OUTGOING = _finalize_outgoing_message_only


def _finalize_outgoing_message_only(message: Any) -> str:
    value = _USER_FINAL_PRE_FINALIZE_OUTGOING(message)
    value = _user_final_blue_hwg(value)
    return _user_final_single_neto_footer(value)


# ---------------------------------------------------------------------------
# 3) CentreGoals uses the same editorial filtering route as ordinary accounts.
# It remains available in the Facts control hub and keeps its existing saved
# enable/disable state, but source-specific over-filtering no longer drops reports.
# ---------------------------------------------------------------------------
if "EXTRA_FACT_SOURCE_USERNAMES" in globals() and isinstance(EXTRA_FACT_SOURCE_USERNAMES, list):
    EXTRA_FACT_SOURCE_USERNAMES[:] = [
        value for value in EXTRA_FACT_SOURCE_USERNAMES
        if str(value or "").strip().lstrip("@").casefold() != CENTREGOALS_USERNAME.casefold()
    ]

_USER_FINAL_PRE_IS_FACTS_SOURCE = _is_facts_source


def _is_facts_source(value: Any) -> bool:
    # Keep CentreGoals in the Facts menu when functions pass its username, but
    # treat an actual CentreGoals post as an ordinary report for editorial rules.
    if isinstance(value, Post):
        username = str(getattr(value, "username", "") or "").strip().lstrip("@").casefold()
        if username == CENTREGOALS_USERNAME.casefold():
            return False
    return _USER_FINAL_PRE_IS_FACTS_SOURCE(value)


_USER_FINAL_PRE_CENTREGOALS_BLOCK = pre_send_final_local_block_reason


def pre_send_final_local_block_reason(post: Post) -> str:
    username = str(getattr(post, "username", "") or "").strip().lstrip("@").casefold()
    if username != CENTREGOALS_USERNAME.casefold():
        return _USER_FINAL_PRE_CENTREGOALS_BLOCK(post)

    # Run the complete current ordinary-account rule chain. The temporary name
    # only disables CentreGoals/facts-source special gates; it does not alter the
    # post text, media, timestamp, link, duplicate identity or persistent memory.
    original_username = post.username
    try:
        post.username = "__centregoals_regular_report__"
        return _USER_FINAL_PRE_CENTREGOALS_BLOCK(post)
    finally:
        post.username = original_username


# ---------------------------------------------------------------------------
# 4) Every photo must be branded. Retry branding, verify one output per input,
# and never fall back to sending an original unbranded photo in the quiet channel.
# ---------------------------------------------------------------------------
_USER_FINAL_PRE_BRAND_IMAGES = _channel_brand_images


def _channel_brand_images(images: list[str]) -> list[str]:
    sources = list(dict.fromkeys(str(value) for value in (images or []) if str(value).strip()))
    if not sources:
        return []
    last_error: Exception | None = None
    for attempt in range(1, 4):
        try:
            branded = _USER_FINAL_PRE_BRAND_IMAGES(sources)
            if len(branded) != len(sources):
                raise RuntimeError(f"branding_count_mismatch:{len(branded)}/{len(sources)}")
            missing = [path for path in branded if not path or not os.path.isfile(path) or os.path.getsize(path) <= 0]
            if missing:
                raise RuntimeError("branded_file_missing")
            return branded
        except Exception as exc:
            last_error = exc
            logging.warning("Photo branding attempt %s/3 failed: %s", attempt, short_error(exc, 500))
            if attempt < 3:
                time.sleep(0.35 * attempt)
    raise RuntimeError("Every photo requires the 12% Neto Sport logo: " + short_error(last_error, 700))


_USER_FINAL_CONTROL_MEDIA_FALLBACK = _STABLE_QUIET_MEDIA_FALLBACK


